# "PlanDNA/src/plandna/analysis.py"
'''Dataset-level summaries for collections of floor-plan DNA files.'''

from __future__ import annotations

import csv
from pathlib import Path

from plandna.geometry import layout_summary
from plandna.parser import LayoutParseError, load_layout


def iter_layout_files(path: str | Path) -> list[Path]:
    root = Path(path)
    if root.is_file():
        return [root]
    return sorted(p for p in root.rglob('*.json') if p.is_file())


def summarize_paths(path: str | Path) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    for file_path in iter_layout_files(path):
        try:
            summary = layout_summary(load_layout(file_path))
            summary['path'] = str(file_path)
            summary['status'] = 'ok'
        except LayoutParseError as exc:
            summary = {'path': str(file_path), 'status': 'error', 'error': str(exc)}
        rows.append(summary)
    return rows


def write_summary_csv(rows: list[dict[str, object]], output: str | Path) -> Path:
    target = Path(output)
    target.parent.mkdir(parents=True, exist_ok=True)
    columns = sorted({key for row in rows for key in row.keys()})
    with target.open('w', newline='', encoding='utf-8') as handle:
        writer = csv.DictWriter(handle, fieldnames=columns)
        writer.writeheader()
        writer.writerows(rows)
    return target

# "PlanDNA/src/plandna/cli.py"
'''Command-line interface for PlanDNA.'''

from __future__ import annotations

import json
from pathlib import Path
from typing import Optional

import typer
from rich.console import Console
from rich.table import Table

from plandna.analysis import summarize_paths, write_summary_csv
from plandna.drawing import save_layout_plot
from plandna.geometry import layout_summary
from plandna.parser import LayoutParseError, load_layout

app = typer.Typer(help='Parse, analyze, and draw floor-plan DNA layouts.')
console = Console()


@app.command()
def validate(path: Path) -> None:
    try:
        layout = load_layout(path)
    except LayoutParseError as exc:
        console.print(f'[red]invalid[/red] {exc}')
        raise typer.Exit(code=1) from exc
    console.print(f'[green]valid[/green] solutionId={layout.solutionId} rooms={len(layout.roomList)}')


@app.command()
def summarize(path: Path, json_output: bool = typer.Option(False, '--json')) -> None:
    summary = layout_summary(load_layout(path))
    if json_output:
        console.print(json.dumps(summary, ensure_ascii=False, indent=2))
        return
    table = Table(title='Layout summary')
    table.add_column('metric')
    table.add_column('value')
    for key, value in summary.items():
        table.add_row(str(key), str(value))
    console.print(table)


@app.command()
def draw(path: Path, output: Path = typer.Option(..., '--output', '-o'), show_objects: bool = False) -> None:
    layout = load_layout(path)
    target = save_layout_plot(layout, output, show_objects=show_objects)
    console.print(f'[green]saved[/green] {target}')


@app.command('batch-summary')
def batch_summary(path: Path, output: Optional[Path] = typer.Option(None, '--output', '-o')) -> None:
    rows = summarize_paths(path)
    if output:
        target = write_summary_csv(rows, output)
        console.print(f'[green]wrote[/green] {target}')
        return
    console.print(json.dumps(rows, ensure_ascii=False, indent=2))

# "PlanDNA/src/plandna/server.py"
'''Optional FastAPI service for layout validation, summaries, and plotting.'''

from __future__ import annotations

import base64
import io
from typing import Any

from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse

from plandna.drawing import render_layout
from plandna.geometry import layout_summary
from plandna.parser import LayoutParseError, parse_layout

app = FastAPI(title='PlanDNA API', version='0.1.0')


@app.get('/health')
def health() -> dict[str, str]:
    return {'status': 'ok'}


@app.post('/summarize')
def summarize(payload: dict[str, Any]) -> dict[str, Any]:
    try:
        layout = parse_layout(payload)
    except LayoutParseError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return layout_summary(layout)


@app.post('/render')
def render(payload: dict[str, Any], show_objects: bool = False) -> JSONResponse:
    try:
        layout = parse_layout(payload)
    except LayoutParseError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    fig, _ = render_layout(layout, show_objects=show_objects)
    buffer = io.BytesIO()
    fig.savefig(buffer, format='png', bbox_inches='tight')
    encoded = base64.b64encode(buffer.getvalue()).decode('ascii')
    return JSONResponse({'media_type': 'image/png', 'data_base64': encoded})

