# "PlanDNA/src/plandna/models.py"
'''Typed models for floor-plan DNA records.'''

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, ConfigDict, Field, field_validator


class Point(BaseModel):
    x: float
    y: float

    @classmethod
    def from_any(cls, value: Any) -> 'Point':
        if isinstance(value, Point):
            return value
        if isinstance(value, dict):
            return cls(x=value.get('x', value.get('X')), y=value.get('y', value.get('Y')))
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return cls(x=value[0], y=value[1])
        raise TypeError(f'Cannot parse point from {value!r}')


class Segment(BaseModel):
    model_config = ConfigDict(extra='allow')

    points: list[Point] = Field(default_factory=list)
    kind: str = 'segment'

    @field_validator('points', mode='before')
    @classmethod
    def _coerce_points(cls, value: Any) -> list[Point]:
        if value is None:
            return []
        return [Point.from_any(v) for v in value]


class FurnitureObject(BaseModel):
    model_config = ConfigDict(extra='allow')

    objId: int | str | None = None
    objCategory: int | str | None = None
    objName: str | None = None
    center: Point | None = None
    size: Point | None = None
    points: list[Point] = Field(default_factory=list)

    @field_validator('center', 'size', mode='before')
    @classmethod
    def _coerce_optional_point(cls, value: Any) -> Point | None:
        if value in (None, ''):
            return None
        return Point.from_any(value)

    @field_validator('points', mode='before')
    @classmethod
    def _coerce_points(cls, value: Any) -> list[Point]:
        if value is None:
            return []
        return [Point.from_any(v) for v in value]


class Room(BaseModel):
    model_config = ConfigDict(extra='allow')

    roomId: int | str | None = None
    roomName: str | None = None
    roomUsageName: str | None = None
    points: list[Point] = Field(default_factory=list)
    objects: list[FurnitureObject] = Field(default_factory=list)

    @field_validator('points', mode='before')
    @classmethod
    def _coerce_points(cls, value: Any) -> list[Point]:
        if value is None:
            return []
        return [Point.from_any(v) for v in value]

    @field_validator('objects', mode='before')
    @classmethod
    def _coerce_objects(cls, value: Any) -> list[FurnitureObject]:
        if value is None:
            return []
        return [FurnitureObject.model_validate(v) for v in value]


class Layout(BaseModel):
    model_config = ConfigDict(extra='allow')

    solutionId: int | str | None = None
    roomList: list[Room] = Field(default_factory=list)
    walls: list[Segment] = Field(default_factory=list)
    windows: list[Segment] = Field(default_factory=list)
    doors: list[Segment] = Field(default_factory=list)

    @field_validator('roomList', mode='before')
    @classmethod
    def _coerce_rooms(cls, value: Any) -> list[Room]:
        if value is None:
            return []
        return [Room.model_validate(v) for v in value]

    @field_validator('walls', 'windows', 'doors', mode='before')
    @classmethod
    def _coerce_segments(cls, value: Any) -> list[Segment]:
        if value is None:
            return []
        return [Segment.model_validate(v) for v in value]

# "PlanDNA/src/plandna/parser.py"
'''Parsing and normalization for direct, request, and feedback layout payloads.'''

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from plandna.models import Layout


class LayoutParseError(ValueError):
    '''Raised when a layout payload cannot be normalized.'''


def normalize_layout_payload(payload: dict[str, Any]) -> dict[str, Any]:
    if 'roomList' in payload:
        return payload
    for field in ('feedback', 'request'):
        raw = payload.get(field)
        if isinstance(raw, str) and raw.strip():
            try:
                decoded = json.loads(raw)
            except json.JSONDecodeError as exc:
                raise LayoutParseError(f'Invalid JSON in {field}: {exc}') from exc
            if not isinstance(decoded, dict):
                raise LayoutParseError(f'{field} must decode to an object')
            if 'roomList' in decoded:
                return decoded
    raise LayoutParseError('Layout payload does not contain roomList, request, or feedback layout data')


def parse_layout(payload: dict[str, Any]) -> Layout:
    return Layout.model_validate(normalize_layout_payload(payload))


def load_layout(path: str | Path) -> Layout:
    source = Path(path)
    try:
        payload = json.loads(source.read_text(encoding='utf-8'))
    except OSError as exc:
        raise LayoutParseError(f'Cannot read layout file {source}: {exc}') from exc
    except json.JSONDecodeError as exc:
        raise LayoutParseError(f'Invalid JSON file {source}: {exc}') from exc
    if not isinstance(payload, dict):
        raise LayoutParseError('Top-level layout JSON must be an object')
    return parse_layout(payload)


def dump_layout(layout: Layout, path: str | Path) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(layout.model_dump_json(indent=2), encoding='utf-8')

# "PlanDNA/src/plandna/geometry.py"
'''Geometry calculations used by plotting, summaries, and compatibility APIs.'''

from __future__ import annotations

from collections.abc import Iterable
from math import fabs

from plandna.models import FurnitureObject, Layout, Point, Room, Segment


def close_polygon(points: Iterable[Point]) -> list[Point]:
    pts = list(points)
    if not pts:
        return []
    if pts[0].x != pts[-1].x or pts[0].y != pts[-1].y:
        pts.append(Point(x=pts[0].x, y=pts[0].y))
    return pts


def polygon_area(points: Iterable[Point]) -> float:
    pts = close_polygon(points)
    if len(pts) < 4:
        return 0.0
    total = 0.0
    for left, right in zip(pts, pts[1:]):
        total += left.x * right.y - right.x * left.y
    return fabs(total) / 2.0


def centroid(points: Iterable[Point]) -> Point:
    pts = list(points)
    if not pts:
        return Point(x=0.0, y=0.0)
    area_twice = 0.0
    cx = 0.0
    cy = 0.0
    closed = close_polygon(pts)
    for left, right in zip(closed, closed[1:]):
        cross = left.x * right.y - right.x * left.y
        area_twice += cross
        cx += (left.x + right.x) * cross
        cy += (left.y + right.y) * cross
    if abs(area_twice) < 1e-9:
        return Point(x=sum(p.x for p in pts) / len(pts), y=sum(p.y for p in pts) / len(pts))
    return Point(x=cx / (3.0 * area_twice), y=cy / (3.0 * area_twice))


def bounds(points: Iterable[Point]) -> tuple[float, float, float, float]:
    pts = list(points)
    if not pts:
        return (0.0, 0.0, 0.0, 0.0)
    xs = [p.x for p in pts]
    ys = [p.y for p in pts]
    return (min(xs), min(ys), max(xs), max(ys))


def segment_coordinates(segments: list[Segment]) -> tuple[int, dict[str, list[list[float]]]]:
    xs: list[list[float]] = []
    ys: list[list[float]] = []
    for segment in segments:
        xs.append([p.x for p in segment.points])
        ys.append([p.y for p in segment.points])
    return len(segments), {'x': xs, 'y': ys}


def room_area_coordinates(room: Room) -> tuple[tuple[float, float], dict[str, list[float]]]:
    pts = close_polygon(room.points)
    center = centroid(room.points)
    return (center.x, center.y), {'x': [p.x for p in pts], 'y': [p.y for p in pts]}


def object_box(obj: FurnitureObject) -> list[Point]:
    if obj.points:
        return close_polygon(obj.points)
    if obj.center and obj.size:
        half_x = obj.size.x / 2.0
        half_y = obj.size.y / 2.0
        return close_polygon([
            Point(x=obj.center.x - half_x, y=obj.center.y - half_y),
            Point(x=obj.center.x + half_x, y=obj.center.y - half_y),
            Point(x=obj.center.x + half_x, y=obj.center.y + half_y),
            Point(x=obj.center.x - half_x, y=obj.center.y + half_y),
        ])
    return []


def layout_summary(layout: Layout) -> dict[str, float | int | str | None]:
    room_areas = [polygon_area(room.points) for room in layout.roomList]
    all_points = [point for room in layout.roomList for point in room.points]
    minx, miny, maxx, maxy = bounds(all_points)
    return {
        'solutionId': layout.solutionId,
        'room_count': len(layout.roomList),
        'wall_count': len(layout.walls),
        'door_count': len(layout.doors),
        'window_count': len(layout.windows),
        'object_count': sum(len(room.objects) for room in layout.roomList),
        'total_room_area': sum(room_areas),
        'minx': minx,
        'miny': miny,
        'maxx': maxx,
        'maxy': maxy,
    }

# "PlanDNA/src/plandna/drawing.py"
'''Matplotlib rendering functions and legacy-compatible drawing helpers.'''

from __future__ import annotations

from pathlib import Path
from typing import Any

import matplotlib.pyplot as plt
from matplotlib.axes import Axes
from matplotlib.figure import Figure

from plandna.config import PlotSettings
from plandna.geometry import object_box, room_area_coordinates, segment_coordinates
from plandna.models import Layout, Room
from plandna.parser import parse_layout


def _layout_from_any(dna: Layout | dict[str, Any]) -> Layout:
    return dna if isinstance(dna, Layout) else parse_layout(dna)


def draw_area(layout: Layout | dict[str, Any], room: Room | dict[str, Any], ax: Axes | None = None) -> Axes:
    resolved_layout = _layout_from_any(layout)
    resolved_room = room if isinstance(room, Room) else Room.model_validate(room)
    axis = ax or plt.gca()
    _, area = room_area_coordinates(resolved_room)
    axis.plot(area['x'], area['y'], linewidth=0.5, color='black')
    axis.set_title(f'Id{resolved_layout.solutionId}')
    return axis


def draw_bounds(minx: float, miny: float, maxx: float, maxy: float, ax: Axes | None = None) -> Axes:
    axis = ax or plt.gca()
    axis.plot([minx, maxx, maxx, minx, minx], [miny, miny, maxy, maxy, miny], linewidth=0.8, color='red')
    return axis


def draw_house_area(dna: Layout | dict[str, Any], ax: Axes | None = None) -> bool:
    layout = _layout_from_any(dna)
    axis = ax or plt.gca()
    for room in layout.roomList:
        draw_area(layout, room, axis)
    return bool(layout.roomList)


def draw_room_area(dna: Layout | dict[str, Any], room_name: str, ax: Axes | None = None) -> bool:
    layout = _layout_from_any(dna)
    axis = ax or plt.gca()
    matched = False
    for room in layout.roomList:
        if room.roomName == room_name:
            draw_area(layout, room, axis)
            matched = True
    return matched


def _draw_segments(segments: Any, color: str, linewidth: float, ax: Axes) -> bool:
    count, pos = segment_coordinates(segments)
    for i in range(count):
        ax.plot(pos['x'][i], pos['y'][i], alpha=0.7, color=color, linewidth=linewidth, solid_capstyle='round', zorder=2)
    return count > 0


def draw_house_wall(dna: Layout | dict[str, Any], ax: Axes | None = None) -> bool:
    layout = _layout_from_any(dna)
    return _draw_segments(layout.walls, 'tab:blue', 1.0, ax or plt.gca())


def draw_house_window(dna: Layout | dict[str, Any], ax: Axes | None = None) -> bool:
    layout = _layout_from_any(dna)
    return _draw_segments(layout.windows, 'tab:cyan', 0.8, ax or plt.gca())


def draw_house_door(dna: Layout | dict[str, Any], ax: Axes | None = None) -> bool:
    layout = _layout_from_any(dna)
    return _draw_segments(layout.doors, 'tab:red', 0.8, ax or plt.gca())


def draw_room_obj(room: Room | dict[str, Any], obj_category: int | str, ax: Axes | None = None) -> bool:
    resolved_room = room if isinstance(room, Room) else Room.model_validate(room)
    axis = ax or plt.gca()
    count = 0
    for obj in resolved_room.objects:
        if str(obj.objCategory) != str(obj_category):
            continue
        pts = object_box(obj)
        if pts:
            axis.plot([p.x for p in pts], [p.y for p in pts], linewidth=0.5, color='tab:orange')
        if obj.center:
            axis.plot(obj.center.x, obj.center.y, 'o', color='tab:orange')
        count += 1
    return count > 0


def draw_house_obj(dna: Layout | dict[str, Any], obj_category: int | str, close_flag: bool = False, ax: Axes | None = None) -> bool:
    layout = _layout_from_any(dna)
    axis = ax or plt.gca()
    count = 0
    for room in layout.roomList:
        if draw_room_obj(room, obj_category, axis):
            count += 1
    if count == 0 and close_flag:
        plt.close(axis.figure)
    return count > 0


def render_layout(layout: Layout, settings: PlotSettings | None = None, show_objects: bool = False) -> tuple[Figure, Axes]:
    cfg = settings or PlotSettings()
    fig, ax = plt.subplots(figsize=(cfg.width, cfg.height), dpi=cfg.dpi)
    draw_house_area(layout, ax)
    draw_house_wall(layout, ax)
    draw_house_window(layout, ax)
    draw_house_door(layout, ax)
    if show_objects:
        for room in layout.roomList:
            for obj in room.objects:
                pts = object_box(obj)
                if pts:
                    ax.plot([p.x for p in pts], [p.y for p in pts], color=cfg.object_color, linewidth=0.6)
                if obj.center:
                    ax.plot(obj.center.x, obj.center.y, 'o', color=cfg.object_color, markersize=3)
    ax.set_aspect('equal', adjustable='box')
    if cfg.xlim:
        ax.set_xlim(cfg.xlim)
    if cfg.ylim:
        ax.set_ylim(cfg.ylim)
    ax.grid(True, linestyle=':', linewidth=0.3)
    ax.set_xlabel('x millimeters')
    ax.set_ylabel('y millimeters')
    return fig, ax


def save_layout_plot(layout: Layout, output: str | Path, show_objects: bool = False, settings: PlotSettings | None = None) -> Path:
    fig, _ = render_layout(layout, settings=settings, show_objects=show_objects)
    target = Path(output)
    target.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(target, bbox_inches='tight')
    plt.close(fig)
    return target

# "PlanDNA/src/plandna/dna_object.py"
'''Compatibility helpers that mirror the legacy DNA_Object module API.'''

from __future__ import annotations

from typing import Any

from plandna.geometry import object_box, room_area_coordinates, segment_coordinates
from plandna.models import Room
from plandna.parser import parse_layout


def get_room_area(room: dict[str, Any] | Room):
    resolved = room if isinstance(room, Room) else Room.model_validate(room)
    return room_area_coordinates(resolved)


def get_room_list_from_dna(dna: dict[str, Any]):
    layout = parse_layout(dna)
    return len(layout.roomList), layout.roomList


def get_wall_from_dna(dna: dict[str, Any]):
    return segment_coordinates(parse_layout(dna).walls)


def get_window_info_from_dna(dna: dict[str, Any]):
    return segment_coordinates(parse_layout(dna).windows)


def get_door_from_dna(dna: dict[str, Any]):
    return segment_coordinates(parse_layout(dna).doors)


def get_obj_info_from_room(room: dict[str, Any] | Room, obj_category: int | str):
    resolved = room if isinstance(room, Room) else Room.model_validate(room)
    centers = []
    sizes = []
    points_x = []
    points_y = []
    for obj in resolved.objects:
        if str(obj.objCategory) != str(obj_category):
            continue
        if obj.center:
            centers.append((obj.center.x, obj.center.y))
        if obj.size:
            sizes.append((obj.size.x, obj.size.y))
        for point in object_box(obj):
            points_x.append(point.x)
            points_y.append(point.y)
    center = centers[0] if centers else (0.0, 0.0)
    size = sizes[0] if sizes else (0.0, 0.0)
    return len(centers), center, size, {'x': points_x, 'y': points_y}

