# "MatrixLang_Compiler/src/matrixlang/lexer.py"
from __future__ import annotations

from dataclasses import dataclass
from matrixlang.diagnostics import LexError, SourceLocation


KEYWORDS = {'if', 'else', 'while', 'for', 'print', 'return'}
TWO_CHAR = {'+=', '-=', '*=', '/=', '==', '!=', '<=', '>=', '.+', '.-', '.*', './'}
SINGLE_CHAR = set('+-*/=<>;:,(){}[]\'')


@dataclass(frozen=True, slots=True)
class Token:
    kind: str
    value: str
    location: SourceLocation


class Lexer:
    def __init__(self, source: str) -> None:
        self.source = source
        self.index = 0
        self.line = 1
        self.column = 1

    def tokenize(self) -> list[Token]:
        tokens: list[Token] = []
        while not self._eof():
            char = self._peek()
            if char in ' \t\r':
                self._advance()
                continue
            if char == '\n':
                self._advance_line()
                continue
            if char == '#':
                self._skip_comment()
                continue
            loc = self._loc()
            pair = self.source[self.index:self.index + 2]
            if pair in TWO_CHAR:
                self._advance(); self._advance()
                tokens.append(Token('OP', pair, loc))
                continue
            if char.isdigit():
                tokens.append(self._number())
                continue
            if char.isalpha() or char == '_':
                tokens.append(self._identifier())
                continue
            if char == '"':
                tokens.append(self._string())
                continue
            if char in SINGLE_CHAR:
                self._advance()
                tokens.append(Token('SYMBOL' if char not in '+-*/=<>' else 'OP', char, loc))
                continue
            raise LexError(f'unexpected character {char!r}', loc)
        tokens.append(Token('EOF', '', self._loc()))
        return tokens

    def _number(self) -> Token:
        loc = self._loc()
        start = self.index
        while not self._eof() and self._peek().isdigit():
            self._advance()
        if not self._eof() and self._peek() == '.':
            self._advance()
            while not self._eof() and self._peek().isdigit():
                self._advance()
        return Token('NUMBER', self.source[start:self.index], loc)

    def _identifier(self) -> Token:
        loc = self._loc()
        start = self.index
        while not self._eof() and (self._peek().isalnum() or self._peek() == '_'):
            self._advance()
        value = self.source[start:self.index]
        return Token('KEYWORD' if value in KEYWORDS else 'IDENT', value, loc)

    def _string(self) -> Token:
        loc = self._loc()
        self._advance()
        chars: list[str] = []
        while not self._eof() and self._peek() != '"':
            if self._peek() == '\n':
                raise LexError('unterminated string literal', loc)
            chars.append(self._peek())
            self._advance()
        if self._eof():
            raise LexError('unterminated string literal', loc)
        self._advance()
        return Token('STRING', ''.join(chars), loc)

    def _skip_comment(self) -> None:
        while not self._eof() and self._peek() != '\n':
            self._advance()

    def _peek(self) -> str:
        return self.source[self.index]

    def _advance(self) -> None:
        self.index += 1
        self.column += 1

    def _advance_line(self) -> None:
        self.index += 1
        self.line += 1
        self.column = 1

    def _loc(self) -> SourceLocation:
        return SourceLocation(self.line, self.column)

    def _eof(self) -> bool:
        return self.index >= len(self.source)

# "MatrixLang_Compiler/src/matrixlang/parser.py"
from __future__ import annotations

from matrixlang.ast import Array, ArrayElement, Assignment, BinaryExpression, Block, Expression, For, Identifier, If, MatrixFunction, Print, Program, Range, Return, Transpose, UnaryMinus, Value, While
from matrixlang.diagnostics import ParseError
from matrixlang.lexer import Lexer, Token


ASSIGN_OPS = {'=', '+=', '-=', '*=', '/='}
MATRIX_FUNCTIONS = {'zeros', 'ones', 'eye'}


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> Program:
        instructions = []
        while not self._match('EOF'):
            instructions.append(self._statement())
        return Program(instructions)

    def _statement(self):
        if self._keyword('print'):
            args = [self._expression()]
            while self._accept_value(','):
                args.append(self._expression())
            self._optional_semicolon()
            return Print(args)
        if self._keyword('return'):
            if self._value(';'):
                self._advance()
                return Return(None)
            value = self._expression()
            self._optional_semicolon()
            return Return(value)
        if self._keyword('if'):
            condition = self._expression()
            if_block = self._block()
            else_block = self._block() if self._keyword('else') else None
            return If(condition, if_block, else_block)
        if self._keyword('while'):
            condition = self._expression()
            return While(condition, self._block())
        if self._keyword('for'):
            name = self._expect('IDENT').value
            self._expect_value('=')
            start = self._expression()
            self._expect_value(':')
            end = self._expression()
            return For(name, Range(start, end), self._block())
        if self._match('IDENT') and self._peek(1).value in ASSIGN_OPS:
            name = self._advance().value
            op = self._advance().value
            value = self._expression()
            self._optional_semicolon()
            return Assignment(name, value, op)
        raise ParseError(f'unexpected token {self._current().value!r}', self._current().location)

    def _block(self) -> Block:
        self._expect_value('{')
        instructions = []
        while not self._value('}'):
            if self._match('EOF'):
                raise ParseError('unterminated block', self._current().location)
            instructions.append(self._statement())
        self._expect_value('}')
        return Block(instructions)

    def _expression(self) -> Expression:
        return self._comparison()

    def _comparison(self) -> Expression:
        expr = self._term()
        while self._current().value in {'==', '!=', '<', '<=', '>', '>='}:
            op = self._advance().value
            expr = BinaryExpression(op, expr, self._term())
        return expr

    def _term(self) -> Expression:
        expr = self._factor()
        while self._current().value in {'+', '-', '.+', '.-'}:
            op = self._advance().value
            expr = BinaryExpression(op, expr, self._factor())
        return expr

    def _factor(self) -> Expression:
        expr = self._unary()
        while self._current().value in {'*', '/', '.*', './'}:
            op = self._advance().value
            expr = BinaryExpression(op, expr, self._unary())
        return expr

    def _unary(self) -> Expression:
        if self._accept_value('-'):
            return UnaryMinus(self._unary())
        return self._postfix()

    def _postfix(self) -> Expression:
        expr = self._primary()
        while True:
            if self._accept_value('\''):
                expr = Transpose(expr)
            elif self._accept_value('['):
                indices = [self._expression()]
                while self._accept_value(','):
                    indices.append(self._expression())
                self._expect_value(']')
                expr = ArrayElement(expr, indices)
            else:
                return expr

    def _primary(self) -> Expression:
        if self._match('NUMBER'):
            raw = self._advance().value
            return Value(float(raw) if '.' in raw else int(raw))
        if self._match('STRING'):
            return Value(self._advance().value)
        if self._match('IDENT'):
            name = self._advance().value
            if self._accept_value('('):
                params = [] if self._value(')') else [self._expression()]
                while self._accept_value(','):
                    params.append(self._expression())
                self._expect_value(')')
                return MatrixFunction(name, params)
            return Identifier(name)
        if self._accept_value('('):
            expr = self._expression()
            self._expect_value(')')
            return expr
        if self._accept_value('['):
            return self._array_literal()
        raise ParseError(f'expected expression, got {self._current().value!r}', self._current().location)

    def _array_literal(self) -> Array:
        rows = [[]]
        if self._accept_value(']'):
            return Array([])
        rows[-1].append(self._expression())
        while not self._value(']'):
            if self._accept_value(','):
                rows[-1].append(self._expression())
            elif self._accept_value(';'):
                rows.append([self._expression()])
            else:
                raise ParseError('expected comma, semicolon, or closing bracket', self._current().location)
        self._expect_value(']')
        return Array(rows)

    def _optional_semicolon(self) -> None:
        self._accept_value(';')

    def _keyword(self, value: str) -> bool:
        if self._current().kind == 'KEYWORD' and self._current().value == value:
            self._advance()
            return True
        return False

    def _match(self, kind: str) -> bool:
        return self._current().kind == kind

    def _value(self, value: str) -> bool:
        return self._current().value == value

    def _accept_value(self, value: str) -> bool:
        if self._value(value):
            self._advance()
            return True
        return False

    def _expect(self, kind: str) -> Token:
        if not self._match(kind):
            raise ParseError(f'expected {kind}', self._current().location)
        return self._advance()

    def _expect_value(self, value: str) -> Token:
        if not self._value(value):
            raise ParseError(f'expected {value!r}', self._current().location)
        return self._advance()

    def _advance(self) -> Token:
        token = self._current()
        self.pos += 1
        return token

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _peek(self, offset: int) -> Token:
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]


def parse_source(source: str) -> Program:
    return Parser(Lexer(source).tokenize()).parse()

# "MatrixLang_Compiler/src/matrixlang/printer.py"
from __future__ import annotations

from io import StringIO
from typing import Callable, TypeVar

from matrixlang.ast import Array, ArrayElement, Assignment, BinaryExpression, Block, For, Identifier, If, MatrixFunction, Node, Print, Program, Range, Return, Transpose, UnaryMinus, Value, While

T = TypeVar('T', bound=type)


def add_to_class(cls: T) -> Callable[[Callable], Callable]:
    def decorator(func: Callable) -> Callable:
        setattr(cls, func.__name__, func)
        return func
    return decorator


def _line(buffer: StringIO, text: str, indent: int) -> None:
    buffer.write(indent * '|  ' + text + '\n')


class TreePrinter:
    def __init__(self) -> None:
        self.buffer = StringIO()

    def print(self, node: Node) -> str:
        node.print_tree(self.buffer, 0)  # type: ignore[attr-defined]
        return self.buffer.getvalue()


@add_to_class(Node)
def print_tree(self: Node, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.type, indent)


@add_to_class(Program)
def print_tree(self: Program, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.type, indent)
    for instruction in self.instructions:
        instruction.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(Block)
def print_tree(self: Block, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.type, indent)
    for instruction in self.instructions:
        instruction.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(Assignment)
def print_tree(self: Assignment, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.operator + ' ' + self.name, indent)
    self.value.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(Print)
def print_tree(self: Print, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.type, indent)
    for arg in self.args:
        arg.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(Return)
def print_tree(self: Return, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.type, indent)
    if self.value is not None:
        self.value.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(If)
def print_tree(self: If, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.type, indent)
    self.condition.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]
    _line(buffer, 'then', indent + 1)
    self.if_block.print_tree(buffer, indent + 2)  # type: ignore[attr-defined]
    if self.else_block is not None:
        _line(buffer, 'else', indent + 1)
        self.else_block.print_tree(buffer, indent + 2)  # type: ignore[attr-defined]


@add_to_class(While)
def print_tree(self: While, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.type, indent)
    self.condition.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]
    self.instruction.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(For)
def print_tree(self: For, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.type + ' ' + self.variable, indent)
    self.range.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]
    self.instruction.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(Value)
def print_tree(self: Value, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, repr(self.value), indent)


@add_to_class(Identifier)
def print_tree(self: Identifier, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.name, indent)


@add_to_class(BinaryExpression)
def print_tree(self: BinaryExpression, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.operator, indent)
    self.left.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]
    self.right.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(UnaryMinus)
def print_tree(self: UnaryMinus, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, '-', indent)
    self.value.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(Transpose)
def print_tree(self: Transpose, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, 'transpose', indent)
    self.value.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(Array)
def print_tree(self: Array, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, 'array' if self.rows else 'empty_array', indent)
    for row in self.rows:
        _line(buffer, 'row', indent + 1)
        for item in row:
            item.print_tree(buffer, indent + 2)  # type: ignore[attr-defined]


@add_to_class(ArrayElement)
def print_tree(self: ArrayElement, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, 'get_element', indent)
    self.array.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]
    for index in self.indices:
        index.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(MatrixFunction)
def print_tree(self: MatrixFunction, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, self.function, indent)
    for parameter in self.parameters:
        parameter.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


@add_to_class(Range)
def print_tree(self: Range, buffer: StringIO, indent: int = 0) -> None:
    _line(buffer, 'range', indent)
    self.start_value.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]
    self.end_value.print_tree(buffer, indent + 1)  # type: ignore[attr-defined]


def format_tree(node: Node) -> str:
    return TreePrinter().print(node)

# "MatrixLang_Compiler/src/matrixlang/semantic.py"
from __future__ import annotations

from dataclasses import dataclass, field

from matrixlang.ast import Array, ArrayElement, Assignment, BinaryExpression, Block, Expression, For, Identifier, If, MatrixFunction, Print, Program, Return, Transpose, UnaryMinus, Value, While
from matrixlang.diagnostics import SemanticError


@dataclass
class SymbolTable:
    defined: set[str] = field(default_factory=set)

    def define(self, name: str) -> None:
        self.defined.add(name)

    def require(self, name: str) -> None:
        if name not in self.defined:
            raise SemanticError(f'undefined variable {name!r}')


class SemanticAnalyzer:
    def __init__(self) -> None:
        self.symbols = SymbolTable()

    def analyze(self, program: Program) -> None:
        for instruction in program.instructions:
            self._instruction(instruction)

    def _instruction(self, node) -> None:
        if isinstance(node, Assignment):
            if node.operator != '=':
                self.symbols.require(node.name)
            self._expr(node.value)
            self.symbols.define(node.name)
        elif isinstance(node, Print):
            for arg in node.args:
                self._expr(arg)
        elif isinstance(node, Return):
            if node.value is not None:
                self._expr(node.value)
        elif isinstance(node, If):
            self._expr(node.condition)
            self._block(node.if_block)
            if node.else_block is not None:
                self._block(node.else_block)
        elif isinstance(node, While):
            self._expr(node.condition)
            self._block(node.instruction)
        elif isinstance(node, For):
            self._expr(node.range.start_value)
            self._expr(node.range.end_value)
            self.symbols.define(node.variable)
            self._block(node.instruction)
        elif isinstance(node, Block):
            self._block(node)
        else:
            raise SemanticError(f'unsupported instruction {node!r}')

    def _block(self, block: Block) -> None:
        for instruction in block.instructions:
            self._instruction(instruction)

    def _expr(self, node: Expression) -> None:
        if isinstance(node, Identifier):
            self.symbols.require(node.name)
        elif isinstance(node, Value):
            return
        elif isinstance(node, BinaryExpression):
            self._expr(node.left); self._expr(node.right)
        elif isinstance(node, UnaryMinus):
            self._expr(node.value)
        elif isinstance(node, Transpose):
            self._expr(node.value)
        elif isinstance(node, Array):
            widths = {len(row) for row in node.rows}
            if len(widths) > 1:
                raise SemanticError('array rows must have equal length')
            for row in node.rows:
                for item in row:
                    self._expr(item)
        elif isinstance(node, ArrayElement):
            self._expr(node.array)
            for index in node.indices:
                self._expr(index)
        elif isinstance(node, MatrixFunction):
            if node.function not in {'zeros', 'ones', 'eye'}:
                raise SemanticError(f'unknown matrix function {node.function!r}')
            for parameter in node.parameters:
                self._expr(parameter)

# "MatrixLang_Compiler/src/matrixlang/interpreter.py"
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from matrixlang.ast import Array, ArrayElement, Assignment, BinaryExpression, Block, Expression, For, Identifier, If, MatrixFunction, Print, Program, Return, Transpose, UnaryMinus, Value, While
from matrixlang.config import RuntimeConfig
from matrixlang.diagnostics import RuntimeMatrixError
from matrixlang.parser import parse_source
from matrixlang.semantic import SemanticAnalyzer

Matrix = list[list[float | int]]


@dataclass
class RunResult:
    output: list[str] = field(default_factory=list)
    variables: dict[str, Any] = field(default_factory=dict)
    return_value: Any = None


class _ReturnSignal(Exception):
    def __init__(self, value: Any) -> None:
        self.value = value


class Interpreter:
    def __init__(self, config: RuntimeConfig | None = None) -> None:
        self.config = config or RuntimeConfig()
        self.env: dict[str, Any] = {}
        self.output: list[str] = []
        self.loop_steps = 0

    def run_source(self, source: str, analyze: bool = True) -> RunResult:
        program = parse_source(source)
        if analyze and self.config.strict_semantics:
            SemanticAnalyzer().analyze(program)
        return self.run(program)

    def run(self, program: Program) -> RunResult:
        try:
            for instruction in program.instructions:
                self._instruction(instruction)
        except _ReturnSignal as signal:
            return RunResult(self.output, dict(self.env), signal.value)
        return RunResult(self.output, dict(self.env), None)

    def _instruction(self, node) -> None:
        if isinstance(node, Assignment):
            value = self._expr(node.value)
            if node.operator != '=':
                current = self.env.get(node.name)
                if current is None:
                    raise RuntimeMatrixError(f'undefined variable {node.name!r}')
                value = self._binary(node.operator[0], current, value)
            self.env[node.name] = value
        elif isinstance(node, Print):
            values = [self._format(self._expr(arg)) for arg in node.args]
            self.output.append(' '.join(values))
        elif isinstance(node, Return):
            raise _ReturnSignal(None if node.value is None else self._expr(node.value))
        elif isinstance(node, If):
            self._block(node.if_block if self._truthy(self._expr(node.condition)) else node.else_block)
        elif isinstance(node, While):
            while self._truthy(self._expr(node.condition)):
                self._tick_loop()
                self._block(node.instruction)
        elif isinstance(node, For):
            start = int(self._expr(node.range.start_value))
            end = int(self._expr(node.range.end_value))
            step = 1 if end >= start else -1
            for value in range(start, end + step, step):
                self._tick_loop()
                self.env[node.variable] = value
                self._block(node.instruction)
        elif isinstance(node, Block):
            self._block(node)
        else:
            raise RuntimeMatrixError(f'unsupported instruction {node!r}')

    def _block(self, block: Block | None) -> None:
        if block is None:
            return
        for instruction in block.instructions:
            self._instruction(instruction)

    def _expr(self, node: Expression) -> Any:
        if isinstance(node, Value):
            return node.value
        if isinstance(node, Identifier):
            if node.name not in self.env:
                raise RuntimeMatrixError(f'undefined variable {node.name!r}')
            return self.env[node.name]
        if isinstance(node, UnaryMinus):
            return self._neg(self._expr(node.value))
        if isinstance(node, BinaryExpression):
            return self._binary(node.operator, self._expr(node.left), self._expr(node.right))
        if isinstance(node, Array):
            return [[self._expr(item) for item in row] for row in node.rows]
        if isinstance(node, Transpose):
            return self._transpose(self._expr(node.value))
        if isinstance(node, ArrayElement):
            target = self._expr(node.array)
            indices = [int(self._expr(index)) for index in node.indices]
            try:
                value = target
                for index in indices:
                    value = value[index]
                return value
            except (IndexError, TypeError) as exc:
                raise RuntimeMatrixError('array index out of bounds') from exc
        if isinstance(node, MatrixFunction):
            return self._matrix_function(node.function, [self._expr(p) for p in node.parameters])
        raise RuntimeMatrixError(f'unsupported expression {node!r}')

    def _binary(self, op: str, left: Any, right: Any) -> Any:
        if op in {'==', '!=', '<', '<=', '>', '>='}:
            return self._compare(op, left, right)
        if self._is_matrix(left) or self._is_matrix(right):
            return self._matrix_binary(op, left, right)
        if op in {'+', '.+'}: return left + right
        if op in {'-', '.-'}: return left - right
        if op in {'*', '.*'}: return left * right
        if op in {'/', './'}: return left / right
        raise RuntimeMatrixError(f'unknown operator {op!r}')

    def _matrix_binary(self, op: str, left: Any, right: Any) -> Any:
        if self._is_matrix(left) and self._is_matrix(right):
            self._same_shape(left, right)
            if op in {'+', '.+'}: return [[a + b for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
            if op in {'-', '.-'}: return [[a - b for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
            if op in {'.*', '*'}: return [[a * b for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
            if op in {'./', '/'}: return [[a / b for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
        if self._is_matrix(left):
            return [[self._binary(op, item, right) for item in row] for row in left]
        return [[self._binary(op, left, item) for item in row] for row in right]

    def _matrix_function(self, name: str, params: list[Any]) -> Matrix:
        if name == 'eye':
            n = int(params[0])
            return [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        if len(params) == 1:
            rows = cols = int(params[0])
        else:
            rows, cols = int(params[0]), int(params[1])
        fill = 0 if name == 'zeros' else 1
        return [[fill for _ in range(cols)] for _ in range(rows)]

    def _compare(self, op: str, left: Any, right: Any) -> bool:
        return {'==': left == right, '!=': left != right, '<': left < right, '<=': left <= right, '>': left > right, '>=': left >= right}[op]

    def _transpose(self, value: Any) -> Any:
        if not self._is_matrix(value):
            return value
        if not value:
            return []
        return [list(row) for row in zip(*value)]

    def _neg(self, value: Any) -> Any:
        if self._is_matrix(value):
            return [[-item for item in row] for row in value]
        return -value

    def _truthy(self, value: Any) -> bool:
        if self._is_matrix(value):
            return any(any(row) for row in value)
        return bool(value)

    def _is_matrix(self, value: Any) -> bool:
        return isinstance(value, list) and (not value or isinstance(value[0], list))

    def _same_shape(self, left: Matrix, right: Matrix) -> None:
        if len(left) != len(right) or any(len(a) != len(b) for a, b in zip(left, right)):
            raise RuntimeMatrixError('matrix shape mismatch')

    def _tick_loop(self) -> None:
        self.loop_steps += 1
        if self.loop_steps > self.config.max_loop_iterations:
            raise RuntimeMatrixError('loop iteration limit exceeded')

    def _format(self, value: Any) -> str:
        return str(value)

# "MatrixLang_Compiler/src/matrixlang/cli.py"
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from matrixlang.config import CliConfig, read_text
from matrixlang.diagnostics import MatrixLangError
from matrixlang.interpreter import Interpreter
from matrixlang.parser import parse_source
from matrixlang.printer import format_tree
from matrixlang.semantic import SemanticAnalyzer


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog='mlang', description='MatrixLang compiler toolkit')
    sub = parser.add_subparsers(dest='command', required=True)
    for name in ['run', 'ast', 'check']:
        cmd = sub.add_parser(name)
        cmd.add_argument('file', type=Path)
    run = sub.add_parser('eval')
    run.add_argument('source')
    run.add_argument('--json', action='store_true')
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    cfg = CliConfig()
    try:
        if args.command == 'eval':
            return _run_source(args.source, args.json)
        source = read_text(args.file, cfg.encoding)
        if args.command == 'ast':
            print(format_tree(parse_source(source)), end='')
            return 0
        if args.command == 'check':
            SemanticAnalyzer().analyze(parse_source(source))
            print('ok')
            return 0
        if args.command == 'run':
            result = Interpreter(cfg.runtime).run_source(source)
            for line in result.output:
                print(line)
            return 0
    except MatrixLangError as exc:
        print(f'error: {exc}', file=sys.stderr)
        return 2
    return 1


def _run_source(source: str, as_json: bool) -> int:
    result = Interpreter().run_source(source)
    if as_json:
        print(json.dumps({'output': result.output, 'variables': result.variables, 'return_value': result.return_value}))
    else:
        for line in result.output:
            print(line)
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

# "MatrixLang_Compiler/src/matrixlang/server.py"
from __future__ import annotations

import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any

from matrixlang.diagnostics import MatrixLangError
from matrixlang.interpreter import Interpreter


class MatrixLangHandler(BaseHTTPRequestHandler):
    server_version = 'MatrixLangHTTP/0.1'

    def do_POST(self) -> None:
        if self.path != '/run':
            self._write(404, {'error': 'not found'})
            return
        try:
            length = int(self.headers.get('content-length', '0'))
            payload = json.loads(self.rfile.read(length).decode('utf-8'))
            source = payload.get('source')
            if not isinstance(source, str):
                self._write(400, {'error': 'source must be a string'})
                return
            result = Interpreter().run_source(source)
            self._write(200, {'output': result.output, 'variables': result.variables, 'return_value': result.return_value})
        except MatrixLangError as exc:
            self._write(422, {'error': str(exc)})
        except json.JSONDecodeError as exc:
            self._write(400, {'error': f'invalid json: {exc}'})

    def do_GET(self) -> None:
        if self.path == '/healthz':
            self._write(200, {'status': 'ok'})
        else:
            self._write(404, {'error': 'not found'})

    def log_message(self, format: str, *args: Any) -> None:
        return

    def _write(self, status: int, payload: dict[str, Any]) -> None:
        body = json.dumps(payload).encode('utf-8')
        self.send_response(status)
        self.send_header('content-type', 'application/json')
        self.send_header('content-length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog='mlang-server')
    parser.add_argument('--host', default='127.0.0.1')
    parser.add_argument('--port', default=8080, type=int)
    args = parser.parse_args(argv)
    httpd = ThreadingHTTPServer((args.host, args.port), MatrixLangHandler)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        return 0
    finally:
        httpd.server_close()
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

