from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class SourceLocation:
    line: int
    column: int

    def render(self) -> str:
        return f'{self.line}:{self.column}'


class MatrixLangError(Exception):
    def __init__(self, message: str, location: SourceLocation | None = None) -> None:
        self.message = message
        self.location = location
        prefix = f'{location.render()}: ' if location else ''
        super().__init__(prefix + message)


class LexError(MatrixLangError):
    pass


class ParseError(MatrixLangError):
    pass


class SemanticError(MatrixLangError):
    pass


class RuntimeMatrixError(MatrixLangError):
    pass

