# "MatrixLang_Compiler/src/matrixlang/lexer.py"
from __future__ import annotations

from dataclasses import dataclass
from matrixlang.diagnostics import LexError, SourceLocation


KEYWORDS = {'if', 'else', 'while', 'for', 'print', 'return'}
TWO_CHAR = {'+=', '-=', '*=', '/=', '==', '!=', '<=', '>=', '.+', '.-', '.*', './'}
SINGLE_CHAR = set('+-*/=<>;:,(){}[]\'')


@dataclass(frozen=True, slots=True)
class Token:
    kind: str
    value: str
    location: SourceLocation


class Lexer:
    def __init__(self, source: str) -> None:
        self.source = source
        self.index = 0
        self.line = 1
        self.column = 1

    def tokenize(self) -> list[Token]:
        tokens: list[Token] = []
        while not self._eof():
            char = self._peek()
            if char in ' \t\r':
                self._advance()
                continue
            if char == '\n':
                self._advance_line()
                continue
            if char == '#':
                self._skip_comment()
                continue
            loc = self._loc()
            pair = self.source[self.index:self.index + 2]
            if pair in TWO_CHAR:
                self._advance(); self._advance()
                tokens.append(Token('OP', pair, loc))
                continue
            if char.isdigit():
                tokens.append(self._number())
                continue
            if char.isalpha() or char == '_':
                tokens.append(self._identifier())
                continue
            if char == '"':
                tokens.append(self._string())
                continue
            if char in SINGLE_CHAR:
                self._advance()
                tokens.append(Token('SYMBOL' if char not in '+-*/=<>' else 'OP', char, loc))
                continue
            raise LexError(f'unexpected character {char!r}', loc)
        tokens.append(Token('EOF', '', self._loc()))
        return tokens

    def _number(self) -> Token:
        loc = self._loc()
        start = self.index
        while not self._eof() and self._peek().isdigit():
            self._advance()
        if not self._eof() and self._peek() == '.':
            self._advance()
            while not self._eof() and self._peek().isdigit():
                self._advance()
        return Token('NUMBER', self.source[start:self.index], loc)

    def _identifier(self) -> Token:
        loc = self._loc()
        start = self.index
        while not self._eof() and (self._peek().isalnum() or self._peek() == '_'):
            self._advance()
        value = self.source[start:self.index]
        return Token('KEYWORD' if value in KEYWORDS else 'IDENT', value, loc)

    def _string(self) -> Token:
        loc = self._loc()
        self._advance()
        chars: list[str] = []
        while not self._eof() and self._peek() != '"':
            if self._peek() == '\n':
                raise LexError('unterminated string literal', loc)
            chars.append(self._peek())
            self._advance()
        if self._eof():
            raise LexError('unterminated string literal', loc)
        self._advance()
        return Token('STRING', ''.join(chars), loc)

    def _skip_comment(self) -> None:
        while not self._eof() and self._peek() != '\n':
            self._advance()

    def _peek(self) -> str:
        return self.source[self.index]

    def _advance(self) -> None:
        self.index += 1
        self.column += 1

    def _advance_line(self) -> None:
        self.index += 1
        self.line += 1
        self.column = 1

    def _loc(self) -> SourceLocation:
        return SourceLocation(self.line, self.column)

    def _eof(self) -> bool:
        return self.index >= len(self.source)

# "MatrixLang_Compiler/src/matrixlang/parser.py"
from __future__ import annotations

from matrixlang.ast import Array, ArrayElement, Assignment, BinaryExpression, Block, Expression, For, Identifier, If, MatrixFunction, Print, Program, Range, Return, Transpose, UnaryMinus, Value, While
from matrixlang.diagnostics import ParseError
from matrixlang.lexer import Lexer, Token


ASSIGN_OPS = {'=', '+=', '-=', '*=', '/='}
MATRIX_FUNCTIONS = {'zeros', 'ones', 'eye'}


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> Program:
        instructions = []
        while not self._match('EOF'):
            instructions.append(self._statement())
        return Program(instructions)

    def _statement(self):
        if self._keyword('print'):
            args = [self._expression()]
            while self._accept_value(','):
                args.append(self._expression())
            self._optional_semicolon()
            return Print(args)
        if self._keyword('return'):
            if self._value(';'):
                self._advance()
                return Return(None)
            value = self._expression()
            self._optional_semicolon()
            return Return(value)
        if self._keyword('if'):
            condition = self._expression()
            if_block = self._block()
            else_block = self._block() if self._keyword('else') else None
            return If(condition, if_block, else_block)
        if self._keyword('while'):
            condition = self._expression()
            return While(condition, self._block())
        if self._keyword('for'):
            name = self._expect('IDENT').value
            self._expect_value('=')
            start = self._expression()
            self._expect_value(':')
            end = self._expression()
            return For(name, Range(start, end), self._block())
        if self._match('IDENT') and self._peek(1).value in ASSIGN_OPS:
            name = self._advance().value
            op = self._advance().value
            value = self._expression()
            self._optional_semicolon()
            return Assignment(name, value, op)
        raise ParseError(f'unexpected token {self._current().value!r}', self._current().location)

    def _block(self) -> Block:
        self._expect_value('{')
        instructions = []
        while not self._value('}'):
            if self._match('EOF'):
                raise ParseError('unterminated block', self._current().location)
            instructions.append(self._statement())
        self._expect_value('}')
        return Block(instructions)

    def _expression(self) -> Expression:
        return self._comparison()

    def _comparison(self) -> Expression:
        expr = self._term()
        while self._current().value in {'==', '!=', '<', '<=', '>', '>='}:
            op = self._advance().value
            expr = BinaryExpression(op, expr, self._term())
        return expr

    def _term(self) -> Expression:
        expr = self._factor()
        while self._current().value in {'+', '-', '.+', '.-'}:
            op = self._advance().value
            expr = BinaryExpression(op, expr, self._factor())
        return expr

    def _factor(self) -> Expression:
        expr = self._unary()
        while self._current().value in {'*', '/', '.*', './'}:
            op = self._advance().value
            expr = BinaryExpression(op, expr, self._unary())
        return expr

    def _unary(self) -> Expression:
        if self._accept_value('-'):
            return UnaryMinus(self._unary())
        return self._postfix()

    def _postfix(self) -> Expression:
        expr = self._primary()
        while True:
            if self._accept_value('\''):
                expr = Transpose(expr)
            elif self._accept_value('['):
                indices = [self._expression()]
                while self._accept_value(','):
                    indices.append(self._expression())
                self._expect_value(']')
                expr = ArrayElement(expr, indices)
            else:
                return expr

    def _primary(self) -> Expression:
        if self._match('NUMBER'):
            raw = self._advance().value
            return Value(float(raw) if '.' in raw else int(raw))
        if self._match('STRING'):
            return Value(self._advance().value)
        if self._match('IDENT'):
            name = self._advance().value
            if self._accept_value('('):
                params = [] if self._value(')') else [self._expression()]
                while self._accept_value(','):
                    params.append(self._expression())
                self._expect_value(')')
                return MatrixFunction(name, params)
            return Identifier(name)
        if self._accept_value('('):
            expr = self._expression()
            self._expect_value(')')
            return expr
        if self._accept_value('['):
            return self._array_literal()
        raise ParseError(f'expected expression, got {self._current().value!r}', self._current().location)

    def _array_literal(self) -> Array:
        rows = [[]]
        if self._accept_value(']'):
            return Array([])
        rows[-1].append(self._expression())
        while not self._value(']'):
            if self._accept_value(','):
                rows[-1].append(self._expression())
            elif self._accept_value(';'):
                rows.append([self._expression()])
            else:
                raise ParseError('expected comma, semicolon, or closing bracket', self._current().location)
        self._expect_value(']')
        return Array(rows)

    def _optional_semicolon(self) -> None:
        self._accept_value(';')

    def _keyword(self, value: str) -> bool:
        if self._current().kind == 'KEYWORD' and self._current().value == value:
            self._advance()
            return True
        return False

    def _match(self, kind: str) -> bool:
        return self._current().kind == kind

    def _value(self, value: str) -> bool:
        return self._current().value == value

    def _accept_value(self, value: str) -> bool:
        if self._value(value):
            self._advance()
            return True
        return False

    def _expect(self, kind: str) -> Token:
        if not self._match(kind):
            raise ParseError(f'expected {kind}', self._current().location)
        return self._advance()

    def _expect_value(self, value: str) -> Token:
        if not self._value(value):
            raise ParseError(f'expected {value!r}', self._current().location)
        return self._advance()

    def _advance(self) -> Token:
        token = self._current()
        self.pos += 1
        return token

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _peek(self, offset: int) -> Token:
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]


def parse_source(source: str) -> Program:
    return Parser(Lexer(source).tokenize()).parse()

