def test_determinize_preserves_language() -> None:
    q0 = Node('q0')
    q1 = Node('q1')
    q2 = Node('q2')
    nfa = NFA(charset={'a', 'b'}, nodes={q0, q1, q2}, start=q0, terminals={q2})
    nfa.add_delta(q0, 'a', {q0, q1})
    nfa.add_delta(q1, 'b', q2)
    dfa = determinize(nfa)
    minimized = minimize_dfa(dfa)
    for text in ['ab', 'aab', 'aaab']:
        assert nfa.accepts(text)
        assert dfa.accepts(text)
        assert minimized.accepts(text)
