from automata_regex.parser import regex_to_nfa
from automata_regex.regex import nfa_to_regex

app = typer.Typer(help='Finite automata and regular expression utilities.')


@app.command()
def accepts(pattern: str, text: str) -> None:
    '''Return whether PATTERN accepts TEXT.'''
    nfa = regex_to_nfa(pattern)
    typer.echo('yes' if nfa.accepts(text) else 'no')


@app.command('normalize-regex')
def normalize_regex(pattern: str) -> None:
    '''Parse PATTERN as an NFA and convert it back to a regular expression.'''
    typer.echo(nfa_to_regex(regex_to_nfa(pattern)))


@app.command('regex-to-json')
def regex_to_json(pattern: str, output: Path) -> None:
    '''Serialize the Thompson NFA for PATTERN.'''
    save_nfa(regex_to_nfa(pattern), output)


@app.command('json-to-regex')
def json_to_regex(input_path: Path) -> None:
    '''Convert a serialized NFA to an equivalent regular expression.'''
    typer.echo(nfa_to_regex(load_nfa(input_path)))


@app.command('determinize')
def determinize_file(input_path: Path, output: Path, minimize: bool = False) -> None:
    '''Determinize a serialized NFA and optionally minimize it.'''
    dfa = determinize(load_nfa(input_path))
