if __name__ == '__main__':
    app()

# "AutomataRegexLab/src/automata_regex/server.py"
'''Optional FastAPI application for automata conversion services.'''
from __future__ import annotations

from pydantic import BaseModel, Field

from automata_regex.algorithms import determinize, minimize_dfa
from automata_regex.nfa import NFA
from automata_regex.parser import regex_to_nfa
from automata_regex.regex import nfa_to_regex


class RegexRequest(BaseModel):
    pattern: str = Field(min_length=0)


class AcceptsRequest(BaseModel):
    pattern: str
    text: str


class AutomatonResponse(BaseModel):
    automaton: dict[str, object]


class RegexResponse(BaseModel):
    regex: str


class AcceptsResponse(BaseModel):
    accepts: bool


def create_app():
    from fastapi import FastAPI, HTTPException

    app = FastAPI(title='AutomataRegexLab', version='0.1.0')

    @app.post('/regex/to-nfa', response_model=AutomatonResponse)
    def regex_to_nfa_endpoint(request: RegexRequest) -> AutomatonResponse:
        try:
            return AutomatonResponse(automaton=regex_to_nfa(request.pattern).to_mapping())
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    @app.post('/regex/normalize', response_model=RegexResponse)
    def normalize_endpoint(request: RegexRequest) -> RegexResponse:
        try:
            return RegexResponse(regex=nfa_to_regex(regex_to_nfa(request.pattern)))
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    @app.post('/regex/accepts', response_model=AcceptsResponse)
    def accepts_endpoint(request: AcceptsRequest) -> AcceptsResponse:
        try:
            return AcceptsResponse(accepts=regex_to_nfa(request.pattern).accepts(request.text))
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    @app.post('/nfa/to-regex', response_model=RegexResponse)
    def nfa_to_regex_endpoint(payload: dict[str, object]) -> RegexResponse:
        try:
            return RegexResponse(regex=nfa_to_regex(NFA.from_mapping(payload)))
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    @app.post('/nfa/determinize', response_model=AutomatonResponse)
    def determinize_endpoint(payload: dict[str, object], minimize: bool = False) -> AutomatonResponse:
        try:
            dfa = determinize(NFA.from_mapping(payload))
            if minimize:
                dfa = minimize_dfa(dfa)
            return AutomatonResponse(automaton=dfa.to_mapping())
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    return app

# "AutomataRegexLab/scripts/bench_regex_conversion.py"
from __future__ import annotations

import random
import time

from automata_regex.parser import regex_to_nfa
from automata_regex.regex import nfa_to_regex

ALPHABET = 'abc'


def random_pattern(depth: int = 3) -> str:
    if depth <= 0:
        return random.choice(ALPHABET)
    op = random.choice(['concat', 'union', 'star', 'literal'])
    if op == 'concat':
        return random_pattern(depth - 1) + random_pattern(depth - 1)
    if op == 'union':
        return '(' + random_pattern(depth - 1) + '+' + random_pattern(depth - 1) + ')'
    if op == 'star':
        return '(' + random_pattern(depth - 1) + ')*'
    return random.choice(ALPHABET)


def main(samples: int = 100) -> None:
    start = time.perf_counter()
    sizes = []
    for _ in range(samples):
        pattern = random_pattern()
        regex = nfa_to_regex(regex_to_nfa(pattern))
        sizes.append(len(regex))
    elapsed = time.perf_counter() - start
    print({'samples': samples, 'seconds': round(elapsed, 4), 'mean_output_len': sum(sizes) / samples})


if __name__ == '__main__':
    main()

