from automata_regex import NFA, Node, determinize, minimize_dfa


def test_nfa_accepts_with_epsilon_transition() -> None:
    q0 = Node('q0')
    q1 = Node('q1')
    q2 = Node('q2')
    nfa = NFA(charset={'a'}, nodes={q0, q1, q2}, start=q0, terminals={q2})
    nfa.add_delta(q0, '', q1)
    nfa.add_delta(q1, 'a', q2)
    assert nfa.accepts('a')
    assert not nfa.accepts('')


def test_determinize_preserves_language() -> None:
    q0 = Node('q0')
    q1 = Node('q1')
    q2 = Node('q2')
    nfa = NFA(charset={'a', 'b'}, nodes={q0, q1, q2}, start=q0, terminals={q2})
    nfa.add_delta(q0, 'a', {q0, q1})
    nfa.add_delta(q1, 'b', q2)
    dfa = determinize(nfa)
    minimized = minimize_dfa(dfa)
    for text in ['ab', 'aab', 'aaab']:
        assert nfa.accepts(text)
        assert dfa.accepts(text)
        assert minimized.accepts(text)
    assert not minimized.accepts('aba')

