from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True, order=True)
class Node:
    '''A hashable automaton state.

    Labels are intentionally stable and human-readable because they are used by
    JSON serialization, debug output, and Graphviz export.
    '''

    label: str

    def __post_init__(self) -> None:
