'''Domain exceptions used by the automata package.'''

class AutomataError(Exception):
    '''Base exception for automata construction and transformation errors.'''


class ValidationError(AutomataError):
    '''Raised when an automaton violates structural invariants.'''


class ParseError(AutomataError):
    '''Raised when a regular expression cannot be parsed.'''

# "AutomataRegexLab/src/automata_regex/node.py"
'''Node model for finite automata.'''
from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True, order=True)
class Node:
    '''A hashable automaton state.

    Labels are intentionally stable and human-readable because they are used by
    JSON serialization, debug output, and Graphviz export.
    '''

    label: str

    def __post_init__(self) -> None:
        if not isinstance(self.label, str) or not self.label:
            raise ValueError('node label must be a non-empty string')

    def __str__(self) -> str:
        return self.label

# "AutomataRegexLab/src/automata_regex/nfa.py"
'''Finite automata data structures.'''
from __future__ import annotations

from collections import deque
from collections.abc import Iterable, Mapping
from dataclasses import dataclass, field
from typing import TypeAlias

from automata_regex.exceptions import ValidationError
from automata_regex.node import Node

Symbol: TypeAlias = str
DeltaMap: TypeAlias = dict[Node, dict[Symbol, set[Node]]]


@dataclass
class NFA:
    '''Nondeterministic finite automaton with epsilon transitions.

    The empty string is used as epsilon. Symbols are represented as strings so
    callers can also model token-level alphabets, not only single characters.
    '''

    charset: set[Symbol] = field(default_factory=set)
    nodes: set[Node] = field(default_factory=set)
    start: Node | None = None
    terminals: set[Node] = field(default_factory=set)
    deltas: DeltaMap = field(default_factory=dict)

    def __post_init__(self) -> None:
        if self.start is not None:
            self.nodes.add(self.start)
        self.nodes.update(self.terminals)
        self.validate(raise_on_error=True)

    def add_node(self, node: Node) -> None:
        self.nodes.add(node)

    def remove_node(self, node: Node) -> None:
        if node == self.start:
            raise ValidationError('cannot remove start node')
        self.nodes.discard(node)
        self.terminals.discard(node)
        self.deltas.pop(node, None)
        for transitions in self.deltas.values():
            empty_inputs: list[str] = []
            for symbol, dests in transitions.items():
                dests.discard(node)
                if not dests:
                    empty_inputs.append(symbol)
            for symbol in empty_inputs:
                del transitions[symbol]

    def add_terminal(self, node: Node) -> None:
        self.nodes.add(node)
        self.terminals.add(node)

    def remove_terminal(self, node: Node) -> None:
        self.terminals.discard(node)

    def set_start(self, node: Node) -> None:
        self.nodes.add(node)
        self.start = node

    def add_delta(self, source: Node, symbol: Symbol, destinations: Node | Iterable[Node]) -> None:
        if symbol and symbol not in self.charset:
            self.charset.add(symbol)
        if source not in self.nodes:
            self.nodes.add(source)
        if isinstance(destinations, Node):
            dest_set = {destinations}
        else:
            dest_set = set(destinations)
        if not dest_set:
            return
        self.nodes.update(dest_set)
        self.deltas.setdefault(source, {}).setdefault(symbol, set()).update(dest_set)

    def remove_delta(self, source: Node, symbol: Symbol, destination: Node | None = None) -> None:
        transitions = self.deltas.get(source)
        if not transitions or symbol not in transitions:
            return
        if destination is None:
            del transitions[symbol]
        else:
            transitions[symbol].discard(destination)
            if not transitions[symbol]:
                del transitions[symbol]
        if not transitions:
            self.deltas.pop(source, None)

    def get_delta(self, source: Node) -> dict[Symbol, set[Node]]:
        return self.deltas.setdefault(source, {})

    def epsilon_closure(self, seeds: Iterable[Node]) -> set[Node]:
        closure = set(seeds)
        queue = deque(closure)
        while queue:
            node = queue.popleft()
            for dest in self.deltas.get(node, {}).get('', set()):
                if dest not in closure:
                    closure.add(dest)
                    queue.append(dest)
        return closure

    def step(self, states: Iterable[Node], symbol: Symbol) -> set[Node]:
        reached: set[Node] = set()
        for state in self.epsilon_closure(states):
            reached.update(self.deltas.get(state, {}).get(symbol, set()))
        return self.epsilon_closure(reached)

    def accepts(self, text: str | Iterable[Symbol]) -> bool:
        if self.start is None:
            return False
        states = self.epsilon_closure({self.start})
        for symbol in text:
            states = self.step(states, symbol)
            if not states:
                return False
        return bool(states & self.terminals)

    def validate(self, raise_on_error: bool = False) -> bool:
        problems: list[str] = []
        if self.start is not None and self.start not in self.nodes:
            problems.append('start node is not in node set')
        if not self.terminals.issubset(self.nodes):
            problems.append('terminal nodes must be a subset of nodes')
        if not set(self.deltas).issubset(self.nodes):
            problems.append('delta sources must be a subset of nodes')
        for source, transitions in self.deltas.items():
            for symbol, dests in transitions.items():
                if symbol and symbol not in self.charset:
                    problems.append(f'symbol {symbol!r} is not in charset')
                if source not in self.nodes or not dests.issubset(self.nodes):
                    problems.append('delta references unknown node')
        if problems and raise_on_error:
            raise ValidationError('; '.join(sorted(set(problems))))
        return not problems

    def copy(self) -> NFA:
        return NFA(
            charset=set(self.charset),
            nodes=set(self.nodes),
            start=self.start,
            terminals=set(self.terminals),
            deltas={s: {a: set(ds) for a, ds in trans.items()} for s, trans in self.deltas.items()},
        )

    @classmethod
    def from_mapping(cls, payload: Mapping[str, object]) -> NFA:
        labels = {label: Node(label) for label in payload.get('nodes', [])}  # type: ignore[arg-type]
        start_label = payload.get('start')
        terminals = {labels[label] for label in payload.get('terminals', [])}  # type: ignore[arg-type]
        nfa = cls(
            charset=set(payload.get('charset', [])),  # type: ignore[arg-type]
            nodes=set(labels.values()),
            start=labels.get(start_label) if isinstance(start_label, str) else None,
            terminals=terminals,
        )
        for item in payload.get('deltas', []):  # type: ignore[assignment]
            source = labels[item['source']]
            dests = {labels[label] for label in item['destinations']}
            nfa.add_delta(source, item['symbol'], dests)
        return nfa

    def to_mapping(self) -> dict[str, object]:
        return {
            'charset': sorted(self.charset),
            'nodes': sorted(node.label for node in self.nodes),
            'start': self.start.label if self.start else None,
            'terminals': sorted(node.label for node in self.terminals),
            'deltas': [
                {'source': src.label, 'symbol': symbol, 'destinations': sorted(d.label for d in dests)}
                for src, trans in sorted(self.deltas.items(), key=lambda item: item[0].label)
                for symbol, dests in sorted(trans.items())
            ],
        }


class DFA(NFA):
    '''Deterministic finite automaton specialization.'''

    def add_delta(self, source: Node, symbol: Symbol, destinations: Node | Iterable[Node]) -> None:
        if symbol == '':
            raise ValidationError('DFA transitions cannot be epsilon transitions')
        if isinstance(destinations, Node):
            dest_set = {destinations}
        else:
            dest_set = set(destinations)
        if len(dest_set) != 1:
            raise ValidationError('DFA transition must have exactly one destination')
        super().add_delta(source, symbol, dest_set)

# "AutomataRegexLab/src/automata_regex/algorithms.py"
'''Core automata algorithms.'''
from __future__ import annotations

from collections import deque

from automata_regex.nfa import DFA, NFA
from automata_regex.node import Node


def reachable_nodes(nfa: NFA) -> set[Node]:
    if nfa.start is None:
        return set()
    seen = {nfa.start}
    queue = deque([nfa.start])
    while queue:
        node = queue.popleft()
        for dests in nfa.deltas.get(node, {}).values():
            for dest in dests:
                if dest not in seen:
                    seen.add(dest)
                    queue.append(dest)
    return seen


def trim_unreachable(nfa: NFA) -> NFA:
    keep = reachable_nodes(nfa)
    out = nfa.copy()
    for node in list(out.nodes - keep):
        if node != out.start:
            out.remove_node(node)
    return out


def determinize(nfa: NFA) -> DFA:
    if nfa.start is None:
        return DFA(charset=set(nfa.charset))
    charset = set(nfa.charset)
    start_set = frozenset(nfa.epsilon_closure({nfa.start}))
    labels: dict[frozenset[Node], Node] = {start_set: Node(_set_label(start_set))}
    dfa = DFA(charset=charset, nodes={labels[start_set]}, start=labels[start_set])
    if start_set & nfa.terminals:
        dfa.add_terminal(labels[start_set])
    queue = deque([start_set])
    while queue:
        state_set = queue.popleft()
        source = labels[state_set]
        for symbol in sorted(charset):
            dest_set = frozenset(nfa.step(state_set, symbol))
            if not dest_set:
                continue
            if dest_set not in labels:
                labels[dest_set] = Node(_set_label(dest_set))
                dfa.add_node(labels[dest_set])
                if dest_set & nfa.terminals:
                    dfa.add_terminal(labels[dest_set])
                queue.append(dest_set)
            dfa.add_delta(source, symbol, labels[dest_set])
    return dfa


def minimize_dfa(dfa: DFA) -> DFA:
    dfa = trim_unreachable(dfa)  # type: ignore[assignment]
    if dfa.start is None:
        return DFA(charset=set(dfa.charset))
    accepting = frozenset(dfa.terminals)
    non_accepting = frozenset(dfa.nodes - dfa.terminals)
    partitions: set[frozenset[Node]] = {p for p in (accepting, non_accepting) if p}
    changed = True
    while changed:
        changed = False
        new_partitions: set[frozenset[Node]] = set()
        for group in partitions:
            buckets: dict[tuple[int | None, ...], set[Node]] = {}
            for node in group:
                signature = []
                for symbol in sorted(dfa.charset):
                    dests = dfa.deltas.get(node, {}).get(symbol, set())
                    dest = next(iter(dests), None)
                    signature.append(_partition_index(dest, partitions))
                buckets.setdefault(tuple(signature), set()).add(node)
            new_partitions.update(frozenset(v) for v in buckets.values())
            changed = changed or len(buckets) > 1
        partitions = new_partitions
    label_for: dict[Node, Node] = {}
    minimized = DFA(charset=set(dfa.charset))
    for group in sorted(partitions, key=lambda g: sorted(n.label for n in g)[0]):
        node = Node('/'.join(sorted(n.label for n in group)))
        minimized.add_node(node)
        if dfa.start in group:
            minimized.set_start(node)
        if group & dfa.terminals:
            minimized.add_terminal(node)
        for old in group:
            label_for[old] = node
    for src, trans in dfa.deltas.items():
        for symbol, dests in trans.items():
            dest = next(iter(dests))
            minimized.add_delta(label_for[src], symbol, label_for[dest])
    return minimized


def _set_label(nodes: frozenset[Node]) -> str:
    return '{' + ','.join(sorted(n.label for n in nodes)) + '}'


def _partition_index(node: Node | None, partitions: set[frozenset[Node]]) -> int | None:
    if node is None:
        return None
    for index, group in enumerate(sorted(partitions, key=lambda g: sorted(n.label for n in g)[0])):
        if node in group:
            return index
    return None

# "AutomataRegexLab/src/automata_regex/regex.py"
'''NFA to regular expression conversion.'''
from __future__ import annotations

from os.path import commonprefix

from automata_regex.exceptions import AutomataError
from automata_regex.nfa import NFA
from automata_regex.node import Node

EPSILON = 'λ'
EMPTY_SET = 'Ø'


def nfa_to_regex(nfa: NFA) -> str:
    '''Convert an NFA to a regular expression using state elimination.'''
    if not nfa.validate():
        raise AutomataError('NFA must be valid before conversion')
    if nfa.start is None or not nfa.terminals:
        return EMPTY_SET

    states = set(nfa.nodes)
    start = _fresh_node('qs', states)
    final = _fresh_node('qf', states | {start})
    states.update({start, final})

    labels: dict[tuple[Node, Node], str] = {}

    def add_expr(src: Node, dest: Node, expr: str) -> None:
        key = (src, dest)
        labels[key] = _union(labels.get(key), expr)

    add_expr(start, nfa.start, '')
    for terminal in nfa.terminals:
        add_expr(terminal, final, '')
    for src, trans in nfa.deltas.items():
        for symbol, dests in trans.items():
            expr = symbol
            for dest in dests:
                add_expr(src, dest, expr)

    removable = sorted(states - {start, final}, key=lambda node: node.label)
    for rip in removable:
        loop = labels.get((rip, rip))
        loop_star = _star(loop) if loop is not None else ''
        incoming = [(i, e) for (i, j), e in list(labels.items()) if j == rip and i != rip]
        outgoing = [(j, e) for (i, j), e in list(labels.items()) if i == rip and j != rip]
        for src, in_expr in incoming:
            for dest, out_expr in outgoing:
                add_expr(src, dest, _concat(in_expr, loop_star, out_expr))
        for key in [key for key in labels if rip in key]:
            del labels[key]

    regex = labels.get((start, final), EMPTY_SET)
    return _polish(regex)


def _fresh_node(prefix: str, existing: set[Node]) -> Node:
    if Node(prefix) not in existing:
        return Node(prefix)
    index = 0
    while Node(f'{prefix}{index}') in existing:
        index += 1
    return Node(f'{prefix}{index}')


def _union(left: str | None, right: str | None) -> str:
    if left is None:
        return right if right is not None else EMPTY_SET
    if right is None or right == left:
        return left
    parts = _split_union(left) + _split_union(right)
    dedup = []
    for part in parts:
        if part not in dedup:
            dedup.append(part)
    dedup.sort(key=lambda value: (len(value), value))
    return '+'.join(dedup)


def _concat(*parts: str | None) -> str:
    out = ''
    for part in parts:
        if part is None or part == EMPTY_SET:
            return EMPTY_SET
        if part == '':
            continue
        out += _parenthesize_for_concat(part)
    return out


def _star(expr: str | None) -> str:
    if expr is None or expr == EMPTY_SET or expr == '':
        return ''
    if len(expr) == 1 or (expr.startswith('(') and expr.endswith(')')):
        return f'{expr}*'
    return f'({expr})*'


def _parenthesize_for_concat(expr: str) -> str:
    if '+' in expr and not (expr.startswith('(') and expr.endswith(')')):
        return f'({expr})'
    return expr


def _split_union(expr: str) -> list[str]:
    depth = 0
    current = []
    parts: list[str] = []
    for char in expr:
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
        if char == '+' and depth == 0:
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    parts.append(''.join(current))
    return parts


def _polish(expr: str) -> str:
    if expr == '':
        return EPSILON
    if expr == EMPTY_SET:
        return EMPTY_SET
    branches = _split_union(expr)
    if len(branches) <= 1:
        return expr
    prefix = commonprefix(branches)
    suffix = _common_suffix(branches)
    if prefix or suffix:
        middle = [b[len(prefix): len(b) - len(suffix) if suffix else len(b)] or EPSILON for b in branches]
        return prefix + '(' + '+'.join(middle) + ')' + suffix
    return expr


def _common_suffix(values: list[str]) -> str:
    reversed_values = [value[::-1] for value in values]
    return commonprefix(reversed_values)[::-1]

# "AutomataRegexLab/src/automata_regex/parser.py"
'''Regular expression parser using Thompson construction.

Supported syntax:
- concatenation by adjacency
- union with + or |
- Kleene star with *
- grouping with parentheses
- λ or empty expression inside a group for epsilon
'''
from __future__ import annotations

from dataclasses import dataclass

from automata_regex.exceptions import ParseError
from automata_regex.nfa import NFA
from automata_regex.node import Node
from automata_regex.regex import EPSILON


@dataclass
class Fragment:
    start: Node
    end: Node
    nfa: NFA


class RegexParser:
    def __init__(self, pattern: str) -> None:
        self.pattern = pattern
        self.pos = 0
        self.counter = 0

    def parse(self) -> NFA:
        if not self.pattern:
            return self._epsilon().nfa
        fragment = self._parse_union()
        if self.pos != len(self.pattern):
            raise ParseError(f'unexpected token {self.pattern[self.pos]!r} at position {self.pos}')
        fragment.nfa.start = fragment.start
        fragment.nfa.terminals = {fragment.end}
        fragment.nfa.validate(raise_on_error=True)
        return fragment.nfa

    def _parse_union(self) -> Fragment:
        left = self._parse_concat()
        while self._peek() in {'+', '|'}:
            self.pos += 1
            right = self._parse_concat()
            left = self._union(left, right)
        return left

    def _parse_concat(self) -> Fragment:
        fragments: list[Fragment] = []
        while self.pos < len(self.pattern) and self._peek() not in {')', '+', '|'}:
            fragments.append(self._parse_star())
        if not fragments:
            return self._epsilon()
        out = fragments[0]
        for fragment in fragments[1:]:
            out = self._concat(out, fragment)
        return out

    def _parse_star(self) -> Fragment:
        base = self._parse_atom()
        while self._peek() == '*':
            self.pos += 1
            base = self._star(base)
        return base

    def _parse_atom(self) -> Fragment:
        char = self._peek()
        if char is None:
            raise ParseError('unexpected end of pattern')
        if char == '(':
            self.pos += 1
            fragment = self._parse_union()
            if self._peek() != ')':
                raise ParseError('missing closing parenthesis')
            self.pos += 1
            return fragment
        if char in {')', '+', '|', '*'}:
            raise ParseError(f'unexpected token {char!r} at position {self.pos}')
        self.pos += 1
        if char == EPSILON:
            return self._epsilon()
        return self._literal(char)

    def _literal(self, symbol: str) -> Fragment:
        start, end = self._node(), self._node()
        nfa = NFA(charset={symbol}, nodes={start, end}, start=start, terminals={end})
        nfa.add_delta(start, symbol, end)
        return Fragment(start, end, nfa)

    def _epsilon(self) -> Fragment:
        start, end = self._node(), self._node()
        nfa = NFA(nodes={start, end}, start=start, terminals={end})
        nfa.add_delta(start, '', end)
        return Fragment(start, end, nfa)

    def _concat(self, left: Fragment, right: Fragment) -> Fragment:
        nfa = _merge(left.nfa, right.nfa)
        nfa.add_delta(left.end, '', right.start)
        nfa.start = left.start
        nfa.terminals = {right.end}
        return Fragment(left.start, right.end, nfa)

    def _union(self, left: Fragment, right: Fragment) -> Fragment:
        start, end = self._node(), self._node()
        nfa = _merge(left.nfa, right.nfa)
        nfa.add_node(start)
        nfa.add_node(end)
        nfa.add_delta(start, '', {left.start, right.start})
        nfa.add_delta(left.end, '', end)
        nfa.add_delta(right.end, '', end)
        nfa.start = start
        nfa.terminals = {end}
        return Fragment(start, end, nfa)

    def _star(self, fragment: Fragment) -> Fragment:
        start, end = self._node(), self._node()
        nfa = fragment.nfa.copy()
        nfa.add_node(start)
        nfa.add_node(end)
        nfa.add_delta(start, '', {fragment.start, end})
        nfa.add_delta(fragment.end, '', {fragment.start, end})
        nfa.start = start
        nfa.terminals = {end}
        return Fragment(start, end, nfa)

    def _node(self) -> Node:
        node = Node(f'q{self.counter}')
        self.counter += 1
        return node

    def _peek(self) -> str | None:
        if self.pos >= len(self.pattern):
            return None
        return self.pattern[self.pos]


def _merge(left: NFA, right: NFA) -> NFA:
    nfa = left.copy()
    nfa.charset.update(right.charset)
    nfa.nodes.update(right.nodes)
    nfa.terminals.update(right.terminals)
    for src, trans in right.deltas.items():
        for symbol, dests in trans.items():
            nfa.add_delta(src, symbol, dests)
    return nfa


def regex_to_nfa(pattern: str) -> NFA:
    return RegexParser(pattern).parse()

