from __future__ import annotations

from dataclasses import dataclass, field
from typing import Protocol

from cloud_migration_orchestrator.exceptions import AdapterError
from cloud_migration_orchestrator.models import Action, ActionType


class OpenStackAdapter(Protocol):
    def live_migrate_server(self, server_id: str, dst_hostname: str) -> str: ...
    def cold_migrate_server(self, server_id: str) -> str: ...
    def retype_volume(self, volume_id: str, dst_type: str) -> str: ...
    def update_attached_volume_type(self, volume_id: str, dst_type: str) -> str: ...


@dataclass
class DryRunOpenStackAdapter:
    operations: list[str] = field(default_factory=list)

    def live_migrate_server(self, server_id: str, dst_hostname: str) -> str:
        message = f'dry-run live migrate server {server_id} to {dst_hostname}'
        self.operations.append(message)
        return message

    def cold_migrate_server(self, server_id: str) -> str:
        message = f'dry-run cold migrate server {server_id}'
        self.operations.append(message)
        return message

    def retype_volume(self, volume_id: str, dst_type: str) -> str:
        message = f'dry-run retype volume {volume_id} to {dst_type}'
        self.operations.append(message)
        return message

    def update_attached_volume_type(self, volume_id: str, dst_type: str) -> str:
        message = f'dry-run update attached volume {volume_id} to {dst_type}'
        self.operations.append(message)
        return message


class ActionDispatcher:
    def __init__(self, adapter: OpenStackAdapter) -> None:
        self.adapter = adapter

    def dispatch(self, action: Action) -> str:
        params = action.input_parameters
        if action.action_type is ActionType.LIVE_MIGRATION:
            return self.adapter.live_migrate_server(action.resource_id, str(params['dst_hostname']))
        if action.action_type is ActionType.COLD_MIGRATION:
            return self.adapter.cold_migrate_server(action.resource_id)
        if action.action_type is ActionType.VOLUME_RETYPE:
            return self.adapter.retype_volume(action.resource_id, str(params['dst_type']))
        if action.action_type is ActionType.VOLUME_UPDATE:
            return self.adapter.update_attached_volume_type(action.resource_id, str(params['dst_type']))
        raise AdapterError(f'Unsupported action type for dispatch: {action.action_type}')

