from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import yaml

from cloud_migration_orchestrator.models import MigrationRequest


def load_mapping(path: str | Path) -> dict[str, Any]:
    request_path = Path(path)
    if not request_path.exists():
        raise FileNotFoundError(f'Request file not found: {request_path}')
    text = request_path.read_text(encoding='utf-8')
    if request_path.suffix.lower() == '.json':
        data = json.loads(text)
    else:
        data = yaml.safe_load(text)
    if not isinstance(data, dict):
        raise ValueError('Request file root must be a mapping')
    return data


def load_request(path: str | Path) -> MigrationRequest:
    return MigrationRequest.from_mapping(load_mapping(path))


def dump_json(data: object) -> str:
    return json.dumps(data, indent=2, sort_keys=True)

