from __future__ import annotations

from typing import Any

from cloud_migration_orchestrator.config import OrchestratorConfig
from cloud_migration_orchestrator.executor import MigrationExecutor
from cloud_migration_orchestrator.models import MigrationRequest
from cloud_migration_orchestrator.planner import MigrationPlanner


def create_app(config: OrchestratorConfig | None = None):
    from fastapi import FastAPI, HTTPException

    cfg = config or OrchestratorConfig.load()
    planner = MigrationPlanner(cfg)
    executor = MigrationExecutor(cfg)
    app = FastAPI(title='OpenStack Parallel Migration Orchestrator', version='0.1.0')

    @app.get('/healthz')
    def healthz() -> dict[str, str]:
        return {'status': 'ok'}

    @app.post('/v1/plan')
    def plan(payload: dict[str, Any]) -> dict[str, Any]:
        try:
            request = MigrationRequest.from_mapping(payload)
            return planner.plan(request).as_dict()
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    @app.post('/v1/execute')
    def execute(payload: dict[str, Any]) -> dict[str, Any]:
        try:
            request = MigrationRequest.from_mapping(payload)
            solution = planner.plan(request)
            results = executor.execute(solution)
            return {'solution': solution.as_dict(), 'results': [result.as_dict() for result in results]}
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    return app

