from __future__ import annotations

import argparse
from typing import Sequence

from rich.console import Console

from cloud_migration_orchestrator.api import create_app
from cloud_migration_orchestrator.config import OrchestratorConfig
from cloud_migration_orchestrator.executor import MigrationExecutor
from cloud_migration_orchestrator.io import dump_json, load_request
from cloud_migration_orchestrator.logging import configure_logging
from cloud_migration_orchestrator.planner import MigrationPlanner

console = Console()


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog='cloud-migrate')
    parser.add_argument('--config', default=None, help='Path to orchestrator YAML configuration')
    subparsers = parser.add_subparsers(dest='command', required=True)

    plan = subparsers.add_parser('plan', help='Validate a request and print planned actions')
    plan.add_argument('--request', required=True, help='Path to request JSON or YAML')

    execute = subparsers.add_parser('execute', help='Plan and execute actions')
    execute.add_argument('--request', required=True, help='Path to request JSON or YAML')
    execute.add_argument('--dry-run', action='store_true', default=True, help='Use dry-run adapter')

    serve = subparsers.add_parser('serve', help='Run the FastAPI service')
    serve.add_argument('--host', default='0.0.0.0')
    serve.add_argument('--port', type=int, default=8080)

    return parser


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    config = OrchestratorConfig.load(args.config)
    configure_logging(config.log_level)

    if args.command == 'plan':
        request = load_request(args.request)
        solution = MigrationPlanner(config).plan(request)
        console.print(dump_json(solution.as_dict()))
        return 0

    if args.command == 'execute':
        request = load_request(args.request)
        solution = MigrationPlanner(config).plan(request)
        results = MigrationExecutor(config).execute(solution)
        console.print(dump_json({'solution': solution.as_dict(), 'results': [r.as_dict() for r in results]}))
        return 0

    if args.command == 'serve':
        import uvicorn

        app = create_app(config)
        uvicorn.run(app, host=args.host, port=args.port)
        return 0

    parser.error(f'Unsupported command: {args.command}')
    return 2


if __name__ == '__main__':
    raise SystemExit(main())

