import logging
import sys


def configure_logging(level: str = 'INFO') -> None:
    numeric_level = getattr(logging, level.upper(), logging.INFO)
    logging.basicConfig(
        level=numeric_level,
        stream=sys.stdout,
        format='%(asctime)s %(levelname)s %(name)s %(message)s',
    )

# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/models.py"
from __future__ import annotations

from dataclasses import dataclass, field
from enum import StrEnum
from typing import Any
from uuid import uuid4


class ResourceKind(StrEnum):
    VM = 'vm'
    VOLUME = 'volume'


class VMStatus(StrEnum):
    ACTIVE = 'active'
    SHUTOFF = 'shutoff'


class VolumeStatus(StrEnum):
    AVAILABLE = 'available'
    IN_USE = 'in-use'


class ActionType(StrEnum):
    LIVE_MIGRATION = 'live_migration'
    COLD_MIGRATION = 'cold_migration'
    VOLUME_MIGRATION = 'volume_migration'
    VOLUME_RETYPE = 'volume_retype'
    VOLUME_UPDATE = 'volume_update'


@dataclass(frozen=True)
class ResourceSpec:
    kind: ResourceKind
    resource_id: str
    status: str
    dst_hostname: str | None = None
    dst_type: str | None = None


@dataclass(frozen=True)
class MigrationRequest:
    params: dict[str, dict[str, dict[str, Any]]]

    @classmethod
    def from_mapping(cls, data: dict[str, Any]) -> 'MigrationRequest':
        params = data.get('params', data)
        if not isinstance(params, dict):
            raise TypeError('Migration request must contain a params mapping')
        return cls(params=params)


@dataclass(frozen=True)
class Action:
    action_type: ActionType
    resource_id: str
    input_parameters: dict[str, Any] = field(default_factory=dict)

    def as_dict(self) -> dict[str, Any]:
        return {
            'action_type': self.action_type.value,
            'resource_id': self.resource_id,
            'input_parameters': self.input_parameters,
        }


@dataclass
class Solution:
    goal_name: str
    strategy_name: str
    solution_id: str = field(default_factory=lambda: str(uuid4()))
    actions: list[Action] = field(default_factory=list)

    def add_action(
        self,
        action_type: ActionType,
        resource_id: str,
        input_parameters: dict[str, Any] | None = None,
    ) -> None:
        self.actions.append(
            Action(
                action_type=action_type,
                resource_id=resource_id,
                input_parameters=input_parameters or {},
            )
        )

    def as_dict(self) -> dict[str, Any]:
        return {
            'solution_id': self.solution_id,
            'goal_name': self.goal_name,
            'strategy_name': self.strategy_name,
            'actions': [action.as_dict() for action in self.actions],
        }


@dataclass(frozen=True)
class ExecutionResult:
    action: Action
    success: bool
    message: str

    def as_dict(self) -> dict[str, Any]:
        return {
            'action': self.action.as_dict(),
            'success': self.success,
            'message': self.message,
        }

# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/validation.py"
from __future__ import annotations

from collections.abc import Iterator
from typing import Any

from cloud_migration_orchestrator.exceptions import ValidationError
from cloud_migration_orchestrator.models import ResourceKind, ResourceSpec, VMStatus, VolumeStatus

STATUS = 'status'
DST_HOSTNAME = 'dst_hostname'
DST_TYPE = 'dst_type'


def iter_resource_specs(params: dict[str, dict[str, dict[str, Any]]]) -> Iterator[ResourceSpec]:
    for raw_kind, resources in params.items():
        try:
            kind = ResourceKind(raw_kind)
        except ValueError as exc:
            raise ValidationError(f'Unsupported resource kind: {raw_kind}') from exc
        if not isinstance(resources, dict):
            raise ValidationError(f'Resources for {raw_kind} must be a mapping')
        for resource_id, payload in resources.items():
            if not isinstance(payload, dict):
                raise ValidationError(f'Resource {resource_id} payload must be a mapping')
            status = payload.get(STATUS)
            if not isinstance(status, str) or not status:
                raise ValidationError(f'Resource {resource_id} requires a non-empty status')
            yield ResourceSpec(
                kind=kind,
                resource_id=str(resource_id),
                status=status,
                dst_hostname=payload.get(DST_HOSTNAME),
                dst_type=payload.get(DST_TYPE),
            )


def validate_resource_spec(spec: ResourceSpec) -> None:
    if spec.kind is ResourceKind.VM:
        _validate_vm(spec)
    elif spec.kind is ResourceKind.VOLUME:
        _validate_volume(spec)
    else:
        raise ValidationError(f'Unsupported resource kind: {spec.kind}')


def validate_params(params: dict[str, dict[str, dict[str, Any]]]) -> list[ResourceSpec]:
    specs = list(iter_resource_specs(params))
    for spec in specs:
        validate_resource_spec(spec)
    return specs


def _validate_vm(spec: ResourceSpec) -> None:
    try:
        status = VMStatus(spec.status)
    except ValueError as exc:
        allowed = ', '.join(item.value for item in VMStatus)
        raise ValidationError(f'VM {spec.resource_id} has invalid status {spec.status}; allowed: {allowed}') from exc
    if status is VMStatus.ACTIVE and not spec.dst_hostname:
        raise ValidationError(f'Active VM {spec.resource_id} requires dst_hostname for live migration')
    if status is VMStatus.SHUTOFF and spec.dst_type:
        raise ValidationError(f'Shutoff VM {spec.resource_id} must not specify dst_type')


def _validate_volume(spec: ResourceSpec) -> None:
    try:
        status = VolumeStatus(spec.status)
    except ValueError as exc:
        allowed = ', '.join(item.value for item in VolumeStatus)
        raise ValidationError(
            f'Volume {spec.resource_id} has invalid status {spec.status}; allowed: {allowed}'
        ) from exc
    if status in {VolumeStatus.AVAILABLE, VolumeStatus.IN_USE} and not spec.dst_type:
        raise ValidationError(f'Volume {spec.resource_id} requires dst_type')

# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/strategy/base.py"
from __future__ import annotations

from abc import ABC, abstractmethod

from cloud_migration_orchestrator.config import OrchestratorConfig
from cloud_migration_orchestrator.models import MigrationRequest, Solution


class BaseStrategy(ABC):
    def __init__(self, config: OrchestratorConfig) -> None:
        self.config = config

    def pre_execute(self, request: MigrationRequest) -> None:
        return None

    @abstractmethod
    def do_execute(self, request: MigrationRequest, solution: Solution) -> Solution:
        raise NotImplementedError

    def post_execute(self, request: MigrationRequest, solution: Solution) -> None:
        return None

    def execute(self, request: MigrationRequest) -> Solution:
        solution = Solution(goal_name=self.get_goal_name(), strategy_name=self.get_name())
        self.pre_execute(request)
        solution = self.do_execute(request, solution)
        self.post_execute(request, solution)
        return solution

    @classmethod
    @abstractmethod
    def get_goal_name(cls) -> str:
        raise NotImplementedError

    @classmethod
    @abstractmethod
    def get_name(cls) -> str:
        raise NotImplementedError

# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/strategy/parallel_migration.py"
from __future__ import annotations

import logging

from cloud_migration_orchestrator.models import (
    ActionType,
    MigrationRequest,
    ResourceSpec,
    Solution,
    VMStatus,
    VolumeStatus,
)
from cloud_migration_orchestrator.strategy.base import BaseStrategy
from cloud_migration_orchestrator.validation import validate_params

LOG = logging.getLogger(__name__)


class ParallelMigrationStrategy(BaseStrategy):
    VM = 'vm'
    VOLUME = 'volume'
    ACTIVE = 'active'
    SHUTOFF = 'shutoff'
    AVAILABLE = 'available'
    IN_USE = 'in-use'
    LIVE_MIGRATION = 'live_migration'
    COLD_MIGRATION = 'cold_migration'
    VOLUME_MIGRATION = 'volume_migration'
    VOLUME_RETYPE = 'volume_retype'
    VOLUME_UPDATE = 'volume_update'
    STATUS = 'status'
    DST_HOSTNAME = 'dst_hostname'
    DST_TYPE = 'dst_type'

    def do_execute(self, request: MigrationRequest, solution: Solution) -> Solution:
        specs = validate_params(request.params)
        for spec in specs:
            self._add_action(spec, solution)
        LOG.info('planned %d migration actions', len(solution.actions))
        return solution

    def _add_action(self, spec: ResourceSpec, solution: Solution) -> None:
        if spec.kind.value == self.VM:
            if spec.status == VMStatus.ACTIVE.value:
                self._live_migration(solution, spec.resource_id, spec.dst_hostname or '')
            elif spec.status == VMStatus.SHUTOFF.value:
                self._cold_migration(solution, spec.resource_id)
        elif spec.kind.value == self.VOLUME:
            if spec.status == VolumeStatus.IN_USE.value:
                self._volume_update(solution, spec.resource_id, spec.dst_type or '')
            elif spec.status == VolumeStatus.AVAILABLE.value:
                self._volume_retype(solution, spec.resource_id, spec.dst_type or '')

    def _live_migration(self, solution: Solution, resource_id: str, dst_hostname: str) -> None:
        solution.add_action(
            action_type=ActionType.LIVE_MIGRATION,
            resource_id=resource_id,
            input_parameters={self.DST_HOSTNAME: dst_hostname},
        )

    def _cold_migration(self, solution: Solution, resource_id: str) -> None:
        solution.add_action(
            action_type=ActionType.COLD_MIGRATION,
            resource_id=resource_id,
            input_parameters={},
        )

    def _volume_update(self, solution: Solution, resource_id: str, dst_type: str) -> None:
        solution.add_action(
            action_type=ActionType.VOLUME_UPDATE,
            resource_id=resource_id,
            input_parameters={self.DST_TYPE: dst_type},
        )

    def _volume_migrate(self, solution: Solution, resource_id: str, dst_hostname: str) -> None:
        solution.add_action(
            action_type=ActionType.VOLUME_MIGRATION,
            resource_id=resource_id,
            input_parameters={self.DST_HOSTNAME: dst_hostname},
        )

    def _volume_retype(self, solution: Solution, resource_id: str, dst_type: str) -> None:
        solution.add_action(
            action_type=ActionType.VOLUME_RETYPE,
            resource_id=resource_id,
            input_parameters={self.DST_TYPE: dst_type},
        )

    @classmethod
    def get_goal_name(cls) -> str:
        return 'zone_migration'

    @classmethod
    def get_name(cls) -> str:
        return 'parallel_migration'

    @classmethod
    def get_display_name(cls) -> str:
        return 'Parallel migration strategy'

    @classmethod
    def get_schema(cls) -> dict[str, object]:
        return {
            'properties': {
                'params': {
                    'type': 'object',
                    'default': {
                        'vm': {
                            'instance_id1': {'status': 'active', 'dst_hostname': 'compute-01'},
                            'instance_id2': {'status': 'shutoff'},
                        },
                        'volume': {
                            'cinder_id1': {'status': 'available', 'dst_type': 'fast'},
                            'cinder_id2': {'status': 'in-use', 'dst_type': 'balanced'},
                        },
                    },
                }
            }
        }

