# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/openstack/client.py"
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Protocol

from cloud_migration_orchestrator.exceptions import AdapterError
from cloud_migration_orchestrator.models import Action, ActionType


class OpenStackAdapter(Protocol):
    def live_migrate_server(self, server_id: str, dst_hostname: str) -> str: ...
    def cold_migrate_server(self, server_id: str) -> str: ...
    def retype_volume(self, volume_id: str, dst_type: str) -> str: ...
    def update_attached_volume_type(self, volume_id: str, dst_type: str) -> str: ...


@dataclass
class DryRunOpenStackAdapter:
    operations: list[str] = field(default_factory=list)

    def live_migrate_server(self, server_id: str, dst_hostname: str) -> str:
        message = f'dry-run live migrate server {server_id} to {dst_hostname}'
        self.operations.append(message)
        return message

    def cold_migrate_server(self, server_id: str) -> str:
        message = f'dry-run cold migrate server {server_id}'
        self.operations.append(message)
        return message

    def retype_volume(self, volume_id: str, dst_type: str) -> str:
        message = f'dry-run retype volume {volume_id} to {dst_type}'
        self.operations.append(message)
        return message

    def update_attached_volume_type(self, volume_id: str, dst_type: str) -> str:
        message = f'dry-run update attached volume {volume_id} to {dst_type}'
        self.operations.append(message)
        return message


class ActionDispatcher:
    def __init__(self, adapter: OpenStackAdapter) -> None:
        self.adapter = adapter

    def dispatch(self, action: Action) -> str:
        params = action.input_parameters
        if action.action_type is ActionType.LIVE_MIGRATION:
            return self.adapter.live_migrate_server(action.resource_id, str(params['dst_hostname']))
        if action.action_type is ActionType.COLD_MIGRATION:
            return self.adapter.cold_migrate_server(action.resource_id)
        if action.action_type is ActionType.VOLUME_RETYPE:
            return self.adapter.retype_volume(action.resource_id, str(params['dst_type']))
        if action.action_type is ActionType.VOLUME_UPDATE:
            return self.adapter.update_attached_volume_type(action.resource_id, str(params['dst_type']))
        raise AdapterError(f'Unsupported action type for dispatch: {action.action_type}')

# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/storage.py"
from __future__ import annotations

import json
from pathlib import Path

from cloud_migration_orchestrator.models import ExecutionResult, Solution


class AuditLog:
    def __init__(self, path: Path) -> None:
        self.path = path

    def write_solution(self, solution: Solution) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.open('a', encoding='utf-8') as handle:
            handle.write(json.dumps({'event': 'solution_planned', **solution.as_dict()}, sort_keys=True))
            handle.write('\n')

    def write_result(self, result: ExecutionResult) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.open('a', encoding='utf-8') as handle:
            handle.write(json.dumps({'event': 'action_executed', **result.as_dict()}, sort_keys=True))
            handle.write('\n')

# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/executor.py"
from __future__ import annotations

import logging
from concurrent.futures import ThreadPoolExecutor, as_completed

from cloud_migration_orchestrator.config import OrchestratorConfig
from cloud_migration_orchestrator.exceptions import ExecutionError
from cloud_migration_orchestrator.models import Action, ExecutionResult, Solution
from cloud_migration_orchestrator.openstack.client import ActionDispatcher, DryRunOpenStackAdapter, OpenStackAdapter
from cloud_migration_orchestrator.storage import AuditLog

LOG = logging.getLogger(__name__)


class MigrationExecutor:
    def __init__(
        self,
        config: OrchestratorConfig,
        adapter: OpenStackAdapter | None = None,
        audit_log: AuditLog | None = None,
    ) -> None:
        self.config = config
        self.adapter = adapter or DryRunOpenStackAdapter()
        self.dispatcher = ActionDispatcher(self.adapter)
        self.audit_log = audit_log or AuditLog(config.audit_log_path)

    def execute(self, solution: Solution) -> list[ExecutionResult]:
        self.audit_log.write_solution(solution)
        if not solution.actions:
            return []
        results: list[ExecutionResult] = []
        max_workers = max(1, self.config.execution_concurrency)
        with ThreadPoolExecutor(max_workers=max_workers) as pool:
            future_to_action = {pool.submit(self._execute_action, action): action for action in solution.actions}
            for future in as_completed(future_to_action):
                result = future.result()
                self.audit_log.write_result(result)
                results.append(result)
        failures = [result for result in results if not result.success]
        if failures:
            raise ExecutionError(f'{len(failures)} migration actions failed')
        return results

    def _execute_action(self, action: Action) -> ExecutionResult:
        try:
            message = self.dispatcher.dispatch(action)
            LOG.info('action completed: %s', message)
            return ExecutionResult(action=action, success=True, message=message)
        except Exception as exc:
            LOG.exception('action failed: %s', action.as_dict())
            return ExecutionResult(action=action, success=False, message=str(exc))

# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/io.py"
from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import yaml

from cloud_migration_orchestrator.models import MigrationRequest


def load_mapping(path: str | Path) -> dict[str, Any]:
    request_path = Path(path)
    if not request_path.exists():
        raise FileNotFoundError(f'Request file not found: {request_path}')
    text = request_path.read_text(encoding='utf-8')
    if request_path.suffix.lower() == '.json':
        data = json.loads(text)
    else:
        data = yaml.safe_load(text)
    if not isinstance(data, dict):
        raise ValueError('Request file root must be a mapping')
    return data


def load_request(path: str | Path) -> MigrationRequest:
    return MigrationRequest.from_mapping(load_mapping(path))


def dump_json(data: object) -> str:
    return json.dumps(data, indent=2, sort_keys=True)

# "OpenStack_Parallel_Migration_Orchestrator/src/cloud_migration_orchestrator/api.py"
from __future__ import annotations

from typing import Any

from cloud_migration_orchestrator.config import OrchestratorConfig
from cloud_migration_orchestrator.executor import MigrationExecutor
from cloud_migration_orchestrator.models import MigrationRequest
from cloud_migration_orchestrator.planner import MigrationPlanner


def create_app(config: OrchestratorConfig | None = None):
    from fastapi import FastAPI, HTTPException

    cfg = config or OrchestratorConfig.load()
    planner = MigrationPlanner(cfg)
    executor = MigrationExecutor(cfg)
    app = FastAPI(title='OpenStack Parallel Migration Orchestrator', version='0.1.0')

    @app.get('/healthz')
    def healthz() -> dict[str, str]:
        return {'status': 'ok'}

    @app.post('/v1/plan')
    def plan(payload: dict[str, Any]) -> dict[str, Any]:
        try:
            request = MigrationRequest.from_mapping(payload)
            return planner.plan(request).as_dict()
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    @app.post('/v1/execute')
    def execute(payload: dict[str, Any]) -> dict[str, Any]:
        try:
            request = MigrationRequest.from_mapping(payload)
            solution = planner.plan(request)
            results = executor.execute(solution)
            return {'solution': solution.as_dict(), 'results': [result.as_dict() for result in results]}
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    return app

