from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any
import os

import yaml


@dataclass(frozen=True)
class OpenStackConfig:
    region_name: str = 'RegionOne'
    interface: str = 'public'
    timeout_seconds: int = 60


@dataclass(frozen=True)
class OrchestratorConfig:
    log_level: str = 'INFO'
    audit_log_path: Path = Path('var/audit/migration-actions.jsonl')
    allow_cold_migration_destination: bool = False
    execution_concurrency: int = 8
    openstack: OpenStackConfig = field(default_factory=OpenStackConfig)

    @classmethod
    def from_mapping(cls, data: dict[str, Any]) -> 'OrchestratorConfig':
        openstack_data = data.get('openstack') or {}
        return cls(
            log_level=str(data.get('log_level', 'INFO')),
            audit_log_path=Path(data.get('audit_log_path', 'var/audit/migration-actions.jsonl')),
            allow_cold_migration_destination=bool(
                data.get('allow_cold_migration_destination', False)
            ),
            execution_concurrency=int(data.get('execution_concurrency', 8)),
            openstack=OpenStackConfig(
                region_name=str(openstack_data.get('region_name', 'RegionOne')),
                interface=str(openstack_data.get('interface', 'public')),
                timeout_seconds=int(openstack_data.get('timeout_seconds', 60)),
            ),
        )

    @classmethod
    def load(cls, path: str | Path | None = None) -> 'OrchestratorConfig':
        if path is None:
            env_path = os.getenv('CMO_CONFIG')
            if env_path:
                path = env_path
        if path is None:
            return cls()
        config_path = Path(path)
        if not config_path.exists():
            raise FileNotFoundError(f'Configuration file not found: {config_path}')
        data = yaml.safe_load(config_path.read_text()) or {}
        if not isinstance(data, dict):
            raise ValueError('Configuration root must be a mapping')
        return cls.from_mapping(data)

