from __future__ import annotations

from collections.abc import Iterator
from typing import Any

from cloud_migration_orchestrator.exceptions import ValidationError
from cloud_migration_orchestrator.models import ResourceKind, ResourceSpec, VMStatus, VolumeStatus

STATUS = 'status'
DST_HOSTNAME = 'dst_hostname'
DST_TYPE = 'dst_type'


def iter_resource_specs(params: dict[str, dict[str, dict[str, Any]]]) -> Iterator[ResourceSpec]:
    for raw_kind, resources in params.items():
        try:
            kind = ResourceKind(raw_kind)
        except ValueError as exc:
            raise ValidationError(f'Unsupported resource kind: {raw_kind}') from exc
        if not isinstance(resources, dict):
            raise ValidationError(f'Resources for {raw_kind} must be a mapping')
        for resource_id, payload in resources.items():
            if not isinstance(payload, dict):
                raise ValidationError(f'Resource {resource_id} payload must be a mapping')
            status = payload.get(STATUS)
            if not isinstance(status, str) or not status:
                raise ValidationError(f'Resource {resource_id} requires a non-empty status')
            yield ResourceSpec(
                kind=kind,
                resource_id=str(resource_id),
                status=status,
                dst_hostname=payload.get(DST_HOSTNAME),
                dst_type=payload.get(DST_TYPE),
            )


def validate_resource_spec(spec: ResourceSpec) -> None:
    if spec.kind is ResourceKind.VM:
        _validate_vm(spec)
    elif spec.kind is ResourceKind.VOLUME:
        _validate_volume(spec)
    else:
        raise ValidationError(f'Unsupported resource kind: {spec.kind}')


def validate_params(params: dict[str, dict[str, dict[str, Any]]]) -> list[ResourceSpec]:
    specs = list(iter_resource_specs(params))
    for spec in specs:
        validate_resource_spec(spec)
    return specs


def _validate_vm(spec: ResourceSpec) -> None:
    try:
        status = VMStatus(spec.status)
    except ValueError as exc:
        allowed = ', '.join(item.value for item in VMStatus)
        raise ValidationError(f'VM {spec.resource_id} has invalid status {spec.status}; allowed: {allowed}') from exc
    if status is VMStatus.ACTIVE and not spec.dst_hostname:
        raise ValidationError(f'Active VM {spec.resource_id} requires dst_hostname for live migration')
    if status is VMStatus.SHUTOFF and spec.dst_type:
        raise ValidationError(f'Shutoff VM {spec.resource_id} must not specify dst_type')


def _validate_volume(spec: ResourceSpec) -> None:
    try:
        status = VolumeStatus(spec.status)
    except ValueError as exc:
        allowed = ', '.join(item.value for item in VolumeStatus)
        raise ValidationError(
            f'Volume {spec.resource_id} has invalid status {spec.status}; allowed: {allowed}'
        ) from exc
    if status in {VolumeStatus.AVAILABLE, VolumeStatus.IN_USE} and not spec.dst_type:
        raise ValidationError(f'Volume {spec.resource_id} requires dst_type')

