        self,
        config: OrchestratorConfig,
        adapter: OpenStackAdapter | None = None,
        audit_log: AuditLog | None = None,
    ) -> None:
        self.config = config
        self.adapter = adapter or DryRunOpenStackAdapter()
        self.dispatcher = ActionDispatcher(self.adapter)
        self.audit_log = audit_log or AuditLog(config.audit_log_path)

    def execute(self, solution: Solution) -> list[ExecutionResult]:
        self.audit_log.write_solution(solution)
        if not solution.actions:
            return []
        results: list[ExecutionResult] = []
        max_workers = max(1, self.config.execution_concurrency)
        with ThreadPoolExecutor(max_workers=max_workers) as pool:
            future_to_action = {pool.submit(self._execute_action, action): action for action in solution.actions}
            for future in as_completed(future_to_action):
                result = future.result()
                self.audit_log.write_result(result)
                results.append(result)
        failures = [result for result in results if not result.success]
        if failures:
            raise ExecutionError(f'{len(failures)} migration actions failed')
        return results

    def _execute_action(self, action: Action) -> ExecutionResult:
        try:
            message = self.dispatcher.dispatch(action)
            LOG.info('action completed: %s', message)
            return ExecutionResult(action=action, success=True, message=message)
        except Exception as exc:
            LOG.exception('action failed: %s', action.as_dict())
            return ExecutionResult(action=action, success=False, message=str(exc))

