'''Block ids and lookup helpers.

The numeric defaults follow the classic Minecraft Pi ids closely enough for simulation.
'''

from dataclasses import dataclass

AIR = 0
STONE = 1
GRASS = 2
DIRT = 3
COBBLESTONE = 4
WOOD_PLANKS = 5
WATER = 8
LAVA = 10
SAND = 12
GRAVEL = 13
GOLD_ORE = 14
IRON_ORE = 15
COAL_ORE = 16
WOOD = 17
LEAVES = 18
BEDROCK = 7
IRON_BLOCK = 42
DIAMOND_ORE = 56

NON_SOLID = {AIR, WATER, LAVA}
SAFE_EMPTY = {AIR, WATER}
UNMINEABLE = {AIR, WATER, LAVA, BEDROCK}


@dataclass(frozen=True, slots=True)
class BlockInfo:
    id: int
    name: str
    solid: bool = True
    mineable: bool = True


REGISTRY: dict[str, BlockInfo] = {
    'AIR': BlockInfo(AIR, 'AIR', solid=False, mineable=False),
    'STONE': BlockInfo(STONE, 'STONE'),
    'GRASS': BlockInfo(GRASS, 'GRASS'),
    'DIRT': BlockInfo(DIRT, 'DIRT'),
    'COBBLESTONE': BlockInfo(COBBLESTONE, 'COBBLESTONE'),
    'WOOD_PLANKS': BlockInfo(WOOD_PLANKS, 'WOOD_PLANKS'),
    'WATER': BlockInfo(WATER, 'WATER', solid=False, mineable=False),
    'LAVA': BlockInfo(LAVA, 'LAVA', solid=False, mineable=False),
    'SAND': BlockInfo(SAND, 'SAND'),
    'GRAVEL': BlockInfo(GRAVEL, 'GRAVEL'),
    'GOLD_ORE': BlockInfo(GOLD_ORE, 'GOLD_ORE'),
    'IRON_ORE': BlockInfo(IRON_ORE, 'IRON_ORE'),
    'COAL_ORE': BlockInfo(COAL_ORE, 'COAL_ORE'),
    'WOOD': BlockInfo(WOOD, 'WOOD'),
    'LEAVES': BlockInfo(LEAVES, 'LEAVES'),
    'BEDROCK': BlockInfo(BEDROCK, 'BEDROCK', mineable=False),
    'IRON_BLOCK': BlockInfo(IRON_BLOCK, 'IRON_BLOCK'),
    'DIAMOND_ORE': BlockInfo(DIAMOND_ORE, 'DIAMOND_ORE'),
}

ID_TO_NAME = {info.id: name for name, info in REGISTRY.items()}


def block_id(name: str) -> int:
    normalized = name.strip().upper()
    if normalized not in REGISTRY:
        known = ', '.join(sorted(REGISTRY))
        raise ValueError(f'Unknown block {name!r}. Known blocks: {known}')
    return REGISTRY[normalized].id


def block_name(block: int) -> str:
    return ID_TO_NAME.get(block, f'UNKNOWN_{block}')

# "MineBot_Pathfinder/src/minebot/world.py"
'''World adapters for Minecraft Pi and deterministic simulation.'''

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Protocol

from minebot import blocks
from minebot.vectors import Vec3


class World(Protocol):
    def get_block(self, pos: Vec3) -> int: ...
    def set_block(self, pos: Vec3, block_id: int) -> None: ...
    def get_height(self, x: int, z: int) -> int: ...
    def get_player_pos(self) -> Vec3: ...


@dataclass(slots=True)
class InMemoryWorld:
    '''Sparse voxel world for tests, planning, and offline demos.'''

    blocks_by_pos: dict[Vec3, int] = field(default_factory=dict)
    player_pos: Vec3 = Vec3(0, 1, 0)
    default_block: int = blocks.AIR
    floor_y: int = 0
    floor_block: int = blocks.GRASS

    def get_block(self, pos: Vec3) -> int:
        if pos in self.blocks_by_pos:
            return self.blocks_by_pos[pos]
        if pos.y == self.floor_y:
            return self.floor_block
        if pos.y < self.floor_y:
            return blocks.BEDROCK
        return self.default_block

    def set_block(self, pos: Vec3, block_id: int) -> None:
        if block_id == self.default_block and pos.y != self.floor_y:
            self.blocks_by_pos.pop(pos, None)
        else:
            self.blocks_by_pos[pos] = block_id

    def get_height(self, x: int, z: int) -> int:
        max_y = self.floor_y
        for pos, block_id in self.blocks_by_pos.items():
            if pos.x == x and pos.z == z and block_id != blocks.AIR and pos.y > max_y:
                max_y = pos.y
        return max_y

    def get_player_pos(self) -> Vec3:
        return self.player_pos

    @classmethod
    def demo(cls) -> 'InMemoryWorld':
        world = cls(player_pos=Vec3(0, 1, 0))
        world.set_block(Vec3(4, 1, 0), blocks.STONE)
        world.set_block(Vec3(5, 1, 0), blocks.COAL_ORE)
        world.set_block(Vec3(6, 1, 0), blocks.IRON_ORE)
        return world


class MinecraftPiWorld:
    '''Adapter over mcpi.minecraft.Minecraft.

    Importing mcpi is deferred so simulation and tests do not need Minecraft Pi installed.
    '''

    def __init__(self) -> None:
        try:
            import mcpi.minecraft as minecraft
        except ImportError as exc:
            raise RuntimeError('mcpi is not installed. Install minebot-pathfinder[minecraft].') from exc
        self._mc = minecraft.Minecraft.create()

    def get_block(self, pos: Vec3) -> int:
        return int(self._mc.getBlock(pos.x, pos.y, pos.z))

    def set_block(self, pos: Vec3, block_id: int) -> None:
        self._mc.setBlock(pos.x, pos.y, pos.z, int(block_id))

    def get_height(self, x: int, z: int) -> int:
        return int(self._mc.getHeight(x, z))

    def get_player_pos(self) -> Vec3:
        raw = self._mc.player.getTilePos()
        return Vec3(int(raw.x), int(raw.y), int(raw.z))

# "MineBot_Pathfinder/src/minebot/search.py"
'''Generic graph search utilities used by bot planners.'''

from __future__ import annotations

from collections import deque
from dataclasses import dataclass, field
import heapq
from itertools import count
from typing import Callable, Generic, Hashable, Iterable, Protocol, TypeVar

State = TypeVar('State', bound=Hashable)
Action = TypeVar('Action')


class SearchProblem(Protocol[State, Action]):
    def start_state(self) -> State: ...
    def is_goal(self, state: State) -> bool: ...
    def successors(self, state: State) -> Iterable[tuple[State, Action, float]]: ...


@dataclass(order=True)
class _Prioritized(Generic[State]):
    priority: float
    sequence: int
    state: State = field(compare=False)


class SearchExhausted(RuntimeError):
    pass


def bfs(problem: SearchProblem[State, Action], limit: int = 10000) -> list[Action]:
    start = problem.start_state()
    frontier: deque[State] = deque([start])
    parents: dict[State, tuple[State | None, Action | None]] = {start: (None, None)}
    expansions = 0
    while frontier:
        state = frontier.popleft()
        if problem.is_goal(state):
            return _reconstruct(state, parents)
        expansions += 1
        if expansions > limit:
            raise SearchExhausted(f'BFS exceeded expansion limit {limit}')
        for successor, action, _cost in problem.successors(state):
            if successor not in parents:
                parents[successor] = (state, action)
                frontier.append(successor)
    raise SearchExhausted('BFS frontier emptied before reaching a goal')


def astar(
    problem: SearchProblem[State, Action],
    heuristic: Callable[[State, SearchProblem[State, Action]], float],
    limit: int = 10000,
) -> list[Action]:
    start = problem.start_state()
    seq = count()
    frontier: list[_Prioritized[State]] = [_Prioritized(heuristic(start, problem), next(seq), start)]
    parents: dict[State, tuple[State | None, Action | None]] = {start: (None, None)}
    costs: dict[State, float] = {start: 0.0}
    expansions = 0
    while frontier:
        item = heapq.heappop(frontier)
        state = item.state
        if problem.is_goal(state):
            return _reconstruct(state, parents)
        expansions += 1
        if expansions > limit:
            raise SearchExhausted(f'A* exceeded expansion limit {limit}')
        for successor, action, step_cost in problem.successors(state):
            new_cost = costs[state] + step_cost
            if successor not in costs or new_cost < costs[successor]:
                costs[successor] = new_cost
                parents[successor] = (state, action)
                priority = new_cost + heuristic(successor, problem)
                heapq.heappush(frontier, _Prioritized(priority, next(seq), successor))
    raise SearchExhausted('A* frontier emptied before reaching a goal')


def _reconstruct(goal: State, parents: dict[State, tuple[State | None, Action | None]]) -> list[Action]:
    actions: list[Action] = []
    current: State | None = goal
    while current is not None:
        parent, action = parents[current]
        if action is not None:
            actions.append(action)
        current = parent
    actions.reverse()
    return actions

