# "MineBot_Pathfinder/src/minebot/bot.py"
'''Bot domain model with simulated and real-world execution modes.'''

from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass, field
from time import sleep

from minebot import blocks
from minebot.actions import Action, ActionType
from minebot.config import Settings
from minebot.vectors import Vec3, adjacent_dirs
from minebot.world import World


@dataclass
class GenericBot:
    world: World
    pos: Vec3
    settings: Settings = field(default_factory=Settings)
    inventory: dict[int, int] = field(default_factory=dict)

    def get_pos(self) -> Vec3:
        return self.pos

    def contains(self, block_id: int) -> bool:
        return self.inventory.get(block_id, 0) > 0

    def take_action(self, action: Action) -> None:
        if action.type == ActionType.MOVE:
            if action.target is None:
                raise ValueError('MOVE action requires target')
            self._move(action.target)
        elif action.type == ActionType.MOVE_UP:
            self._move_up(action.exclude_block)
        elif action.type == ActionType.MOVE_DOWN:
            self._move_down()
        elif action.type == ActionType.MINE:
            if action.target is None:
                raise ValueError('MINE action requires target')
            self._mine(action.target)
        elif action.type == ActionType.PLACE:
            if action.target is None:
                raise ValueError('PLACE action requires target')
            self._place(action.target, exclude=action.exclude_block, block_id=action.block_id)
        else:
            raise ValueError(f'Unsupported action {action.type}')

    def take_actions(self, actions: list[Action], delay: float | None = None) -> None:
        for index, action in enumerate(actions):
            if index and delay is not None and delay > 0:
                sleep(delay)
            self.take_action(action)

    def get_legal_actions(self, exclude_block: int | None = None) -> list[Action]:
        return (
            self._get_move_actions(exclude_block)
            + self._get_mine_actions()
            + self._get_placement_actions(exclude_block)
        )

    def _get_block(self, pos: Vec3) -> int:
        return self.world.get_block(pos)

    def _set_block(self, pos: Vec3, block_id: int) -> None:
        self.world.set_block(pos, block_id)

    def _move(self, pos: Vec3) -> None:
        self.pos = pos

    def _move_down(self) -> None:
        new_pos = self.pos + Vec3(0, -1, 0)
        mined = self._get_block(new_pos)
        if mined not in (blocks.WATER, blocks.AIR):
            self._add_to_inventory(mined)
            self._set_block(new_pos, blocks.AIR)
        self._move(new_pos)

    def _move_up(self, exclude: int | None = None) -> None:
        self._move(self.pos + Vec3(0, 1, 0))
        self._place(self.pos + Vec3(0, -1, 0), exclude=exclude)

    def _mine(self, loc: Vec3) -> None:
        block_id = self._get_block(loc)
        if block_id in blocks.UNMINEABLE:
            raise ValueError(f'Cannot mine block {blocks.block_name(block_id)} at {loc}')
        self._add_to_inventory(block_id)
        self._set_block(loc, blocks.AIR)

    def _place(self, loc: Vec3, exclude: int | None = None, block_id: int | None = None) -> None:
        selected = block_id
        if selected is None:
            for candidate, count in sorted(self.inventory.items()):
                if count > 0 and candidate != exclude:
                    selected = candidate
                    break
        if selected is None:
            raise ValueError('Inventory has no suitable block to place')
        if self.inventory.get(selected, 0) <= 0:
            raise ValueError(f'Block {selected} is not in inventory')
        self.inventory[selected] -= 1
        if self.inventory[selected] == 0:
            del self.inventory[selected]
        self._set_block(loc, selected)

    def _add_to_inventory(self, block_id: int) -> None:
        self.inventory[block_id] = self.inventory.get(block_id, 0) + 1

    def _get_move_actions(self, exclude: int | None = None) -> list[Action]:
        actions: list[Action] = []
        can_move_up = self._get_block(self.pos + Vec3(0, 2, 0)) in blocks.SAFE_EMPTY
        if can_move_up and self._has_blocks_to_place(exclude):
            actions.append(Action(ActionType.MOVE_UP, exclude_block=exclude))

        hidden = self._get_block(self.pos + Vec3(0, -2, 0))
        if hidden == blocks.WATER or hidden not in (blocks.AIR, blocks.LAVA, blocks.BEDROCK):
            actions.append(Action(ActionType.MOVE_DOWN))

        for direction in adjacent_dirs():
            actions.extend(self._side_moves(direction, can_move_up))
        return actions

    def _side_moves(self, direction: Vec3, can_move_up: bool) -> list[Action]:
        actions: list[Action] = []
        base = self.pos + direction
        base_block = self._get_block(base)
        if can_move_up and base_block not in blocks.NON_SOLID:
            if all(self._get_block(base + Vec3(0, h, 0)) in blocks.SAFE_EMPTY for h in (1, 2)):
                actions.append(Action(ActionType.MOVE, base + Vec3(0, 1, 0)))

        if all(self._get_block(base + Vec3(0, h, 0)) in blocks.SAFE_EMPTY for h in (0, 1)):
            fall = base + Vec3(0, -1, 0)
            for _ in range(self.settings.max_drop + 1):
                floor = self._get_block(fall)
                if floor != blocks.AIR:
                    if floor != blocks.LAVA:
                        actions.append(Action(ActionType.MOVE, fall + Vec3(0, 1, 0)))
                    break
                fall = fall + Vec3(0, -1, 0)
        return actions

    def _get_mine_actions(self) -> list[Action]:
        actions: list[Action] = []
        candidates = [self.pos + Vec3(0, 2, 0)]
        for direction in adjacent_dirs():
            candidates.append(self.pos + direction)
            candidates.append(self.pos + direction + Vec3(0, 1, 0))
        for loc in candidates:
            if self._get_block(loc) not in blocks.UNMINEABLE:
                actions.append(Action(ActionType.MINE, loc))
        return actions

    def _get_placement_actions(self, exclude: int | None = None) -> list[Action]:
        if not self._has_blocks_to_place(exclude):
            return []
        offsets = [Vec3(0, 2, 0)]
        for direction in adjacent_dirs():
            offsets.extend([direction, direction + Vec3(0, 1, 0)])
            if self._get_block(self.pos + direction) in blocks.SAFE_EMPTY:
                offsets.append(direction + Vec3(0, -1, 0))
        actions: list[Action] = []
        for offset in offsets:
            loc = self.pos + offset
            if self._can_place(loc):
                actions.append(Action(ActionType.PLACE, loc, exclude_block=exclude))
        return actions

    def _can_place(self, loc: Vec3) -> bool:
        if self._get_block(loc) not in blocks.NON_SOLID:
            return False
        player_cells = {self.pos, self.pos + Vec3(0, 1, 0)}
        for direction in adjacent_dirs() + [Vec3(0, 1, 0), Vec3(0, -1, 0)]:
            neighbor = loc + direction
            if neighbor not in player_cells and self._get_block(neighbor) not in blocks.NON_SOLID:
                return True
        return False

    def _has_blocks_to_place(self, exclude: int | None = None) -> bool:
        return any(count > 0 and block_id != exclude for block_id, count in self.inventory.items())


@dataclass
class ImaginaryBot(GenericBot):
    '''Planning bot that records block changes instead of mutating the backing world.'''

    changes: dict[Vec3, int] = field(default_factory=dict)

    def _get_block(self, pos: Vec3) -> int:
        return self.changes.get(pos, self.world.get_block(pos))

    def _set_block(self, pos: Vec3, block_id: int) -> None:
        self.changes[pos] = block_id

    def clone(self) -> 'ImaginaryBot':
        return ImaginaryBot(
            world=self.world,
            pos=self.pos,
            settings=self.settings,
            inventory=deepcopy(self.inventory),
            changes=deepcopy(self.changes),
        )

    def __hash__(self) -> int:
        return hash((self.pos, frozenset(self.inventory.items()), frozenset(self.changes.items())))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ImaginaryBot):
            return False
        return self.pos == other.pos and self.inventory == other.inventory and self.changes == other.changes


class Bot(GenericBot):
    '''Real executable bot represented by two iron blocks in the world.'''

    BOT_BLOCK = blocks.IRON_BLOCK

    @classmethod
    def spawn_near_player(cls, world: World, settings: Settings | None = None) -> 'Bot':
        player = world.get_player_pos()
        bot = cls(world=world, pos=player + Vec3(2, 0, 0), settings=settings or Settings())
        bot._move(bot.pos)
        return bot

    def destroy(self) -> None:
        self._set_block(self.pos, blocks.AIR)
        self._set_block(self.pos + Vec3(0, 1, 0), blocks.AIR)

    def _move(self, pos: Vec3) -> None:
        self._set_block(self.pos, blocks.AIR)
        self._set_block(self.pos + Vec3(0, 1, 0), blocks.AIR)
        self._set_block(pos, self.BOT_BLOCK)
        self._set_block(pos + Vec3(0, 1, 0), self.BOT_BLOCK)
        self.pos = pos

# "MineBot_Pathfinder/src/minebot/planning.py"
'''Mission planning for finding, mining, and returning blocks.'''

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable

from minebot import blocks
from minebot.actions import Action, ActionType
from minebot.bot import Bot, ImaginaryBot
from minebot.search import SearchProblem, astar, bfs
from minebot.vectors import Vec3, all_dirs, adjacent_dirs
from minebot.world import World


@dataclass(frozen=True)
class FindBlockProblem(SearchProblem[Vec3, Vec3]):
    world: World
    start: Vec3
    target_block: int

    def start_state(self) -> Vec3:
        return self.start

    def is_goal(self, state: Vec3) -> bool:
        return self.world.get_block(state) == self.target_block

    def successors(self, state: Vec3) -> Iterable[tuple[Vec3, Vec3, float]]:
        for direction in all_dirs():
            successor = state + direction
            if successor.y <= self.world.get_height(successor.x, successor.z) + 3:
                if self.world.get_block(successor) != blocks.BEDROCK:
                    yield successor, direction, 1.0


@dataclass(frozen=True)
class MineProblem(SearchProblem[ImaginaryBot, Action]):
    start_bot: ImaginaryBot
    block_loc: Vec3
    target_block: int

    def start_state(self) -> ImaginaryBot:
        return self.start_bot

    def is_goal(self, state: ImaginaryBot) -> bool:
        return state.contains(self.target_block)

    def successors(self, state: ImaginaryBot) -> Iterable[tuple[ImaginaryBot, Action, float]]:
        for action in state.get_legal_actions():
            successor = state.clone()
            try:
                successor.take_action(action)
            except ValueError:
                continue
            yield successor, action, 1.0


@dataclass(frozen=True)
class ReturnProblem(SearchProblem[ImaginaryBot, Action]):
    start_bot: ImaginaryBot
    carried_block: int
    player_loc: Vec3

    def start_state(self) -> ImaginaryBot:
        return self.start_bot

    def is_goal(self, state: ImaginaryBot) -> bool:
        diff = state.get_pos() - self.player_loc
        beside = diff.y == 0 and abs(diff.x) + abs(diff.z) == 2 and (diff.x == 0 or diff.z == 0)
        if not beside:
            return False
        drop_loc = self.player_loc + (diff // 2) + Vec3(0, -1, 0)
        return state._get_block(drop_loc) not in blocks.NON_SOLID

    def successors(self, state: ImaginaryBot) -> Iterable[tuple[ImaginaryBot, Action, float]]:
        for action in state.get_legal_actions(exclude_block=self.carried_block):
            successor = state.clone()
            try:
                successor.take_action(action)
            except ValueError:
                continue
            yield successor, action, 1.0


def locate_block(world: World, start: Vec3, target_block: int, limit: int = 10000) -> Vec3:
    path = bfs(FindBlockProblem(world, start, target_block), limit=limit)
    current = start
    for step in path:
        current = current + step
    return current


def plan_fetch(bot: Bot, block_id: int, limit: int = 10000) -> list[Action]:
    block_loc = locate_block(bot.world, bot.get_pos(), block_id, limit=limit)
    imaginary = ImaginaryBot(bot.world, bot.get_pos(), bot.settings, dict(bot.inventory))
    mine_actions = astar(MineProblem(imaginary, block_loc, block_id), mine_heuristic, limit=limit)
    imaginary.take_actions(mine_actions)

    player_loc = bot.world.get_player_pos()
    return_actions = astar(ReturnProblem(imaginary, block_id, player_loc), return_heuristic, limit=limit)
    imaginary.take_actions(return_actions)
    diff = imaginary.get_pos() - player_loc
    drop_target = player_loc + (diff // 2)
    return mine_actions + return_actions + [Action(ActionType.PLACE, drop_target, block_id=block_id)]


def execute_fetch(bot: Bot, block_name: str, limit: int = 10000) -> list[Action]:
    target = blocks.block_id(block_name)
    actions = plan_fetch(bot, target, limit=limit)
    bot.take_actions(actions, delay=bot.settings.action_delay_seconds)
    return actions


def mine_heuristic(bot: ImaginaryBot, problem: SearchProblem[ImaginaryBot, Action]) -> float:
    mine_problem = problem
    if not isinstance(mine_problem, MineProblem):
        return 0.0
    if bot.contains(mine_problem.target_block):
        return 0.0
    return float(bot.get_pos().manhattan(mine_problem.block_loc))


def return_heuristic(bot: ImaginaryBot, problem: SearchProblem[ImaginaryBot, Action]) -> float:
    return_problem = problem
    if not isinstance(return_problem, ReturnProblem):
        return 0.0
    player = return_problem.player_loc
    return float(min(bot.get_pos().manhattan(player + 2 * direction) for direction in adjacent_dirs()))

# "MineBot_Pathfinder/src/minebot/cli.py"
'''Command-line interface for MineBot.'''

from __future__ import annotations

import json
import logging

import typer

from minebot.bot import Bot
from minebot.config import Settings
from minebot.planning import execute_fetch, plan_fetch
from minebot.server import run_server
from minebot.world import InMemoryWorld, MinecraftPiWorld
from minebot import blocks

app = typer.Typer(help='Autonomous Minecraft Pi block-fetching bot.')


def _configure_logging(settings: Settings) -> None:
    logging.basicConfig(level=getattr(logging, settings.log_level.upper(), logging.INFO))


def _world(settings: Settings):
    if settings.backend == 'minecraft':
        return MinecraftPiWorld()
    return InMemoryWorld.demo()


@app.command()
def simulate_fetch(block_name: str = 'STONE') -> None:
    settings = Settings.from_env()
    _configure_logging(settings)
    world = InMemoryWorld.demo()
    bot = Bot.spawn_near_player(world, settings)
    target = blocks.block_id(block_name)
    actions = plan_fetch(bot, target, limit=settings.search_limit)
    typer.echo(json.dumps([action.as_dict() for action in actions], indent=2))


@app.command()
def fetch(block_name: str = 'STONE') -> None:
    settings = Settings.from_env()
    _configure_logging(settings)
    world = _world(settings)
    bot = Bot.spawn_near_player(world, settings)
    actions = execute_fetch(bot, block_name, limit=settings.search_limit)
    typer.echo(f'Executed {len(actions)} actions to fetch {block_name.upper()}')


@app.command()
def serve(host: str = '127.0.0.1', port: int = 8080) -> None:
    run_server(host=host, port=port)


if __name__ == '__main__':
    app()

