# "MineBot_Pathfinder/src/minebot/server.py"
'''Tiny standard-library HTTP service for local MineBot demos.'''

from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

from minebot import blocks
from minebot.bot import Bot
from minebot.config import Settings
from minebot.planning import plan_fetch
from minebot.world import InMemoryWorld


class MineBotHandler(BaseHTTPRequestHandler):
    server_version = 'MineBotHTTP/0.1'

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        if parsed.path == '/health':
            self._json({'status': 'ok'})
            return
        if parsed.path == '/simulate-fetch':
            params = parse_qs(parsed.query)
            block_name = params.get('block', ['STONE'])[0]
            try:
                world = InMemoryWorld.demo()
                bot = Bot.spawn_near_player(world, Settings())
                target = blocks.block_id(block_name)
                actions = plan_fetch(bot, target)
                self._json({'block': block_name.upper(), 'actions': [a.as_dict() for a in actions]})
            except Exception as exc:
                self._json({'error': str(exc)}, status=400)
            return
        self._json({'error': 'not found'}, status=404)

    def log_message(self, format: str, *args: object) -> None:
        return

    def _json(self, payload: dict[str, object], status: int = 200) -> None:
        body = json.dumps(payload, indent=2).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)


def run_server(host: str = '127.0.0.1', port: int = 8080) -> None:
    httpd = ThreadingHTTPServer((host, port), MineBotHandler)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()

