# "MineBot_Pathfinder/tests/test_search.py"
from dataclasses import dataclass
from typing import Iterable

from minebot.search import SearchProblem, astar, bfs


@dataclass(frozen=True)
class LineProblem(SearchProblem[int, int]):
    start: int
    goal: int

    def start_state(self) -> int:
        return self.start

    def is_goal(self, state: int) -> bool:
        return state == self.goal

    def successors(self, state: int) -> Iterable[tuple[int, int, float]]:
        if state < self.goal:
            yield state + 1, 1, 1.0
        if state > 0:
            yield state - 1, -1, 1.0


def test_bfs_finds_shortest_line_path() -> None:
    assert bfs(LineProblem(0, 3)) == [1, 1, 1]


def test_astar_finds_shortest_line_path() -> None:
    problem = LineProblem(0, 4)
    actions = astar(problem, lambda state, p: abs(p.goal - state))
    assert actions == [1, 1, 1, 1]

