    assert actions[-1].block_id == blocks.STONE


def test_execute_fetch_places_block_near_player() -> None:
    world = InMemoryWorld.demo()
    bot = Bot.spawn_near_player(world, Settings(search_limit=2000))
    execute_fetch(bot, 'STONE', limit=2000)
    player = world.get_player_pos()
    nearby = [
        player + Vec3(1, 0, 0),
        player + Vec3(-1, 0, 0),
        player + Vec3(0, 0, 1),
        player + Vec3(0, 0, -1),
    ]
    assert any(world.get_block(pos) == blocks.STONE for pos in nearby)

