# "Heritage_Rentals/src/heritage_rentals/services/cart_service.py"
from __future__ import annotations

from decimal import Decimal

from heritage_rentals.domain.cart import RentalCart
from heritage_rentals.domain.models import CartDisplayLine
from heritage_rentals.repositories.memory import InMemoryRentalRepository


class RentalCartService:
    def __init__(self, repository: InMemoryRentalRepository) -> None:
        self._repository = repository

    def add_item(self, cart: RentalCart, item_id: int, days: int) -> RentalCart:
        item = self._repository.get(item_id)
        if not item.available:
            raise ValueError(f'Rental item {item_id} is not available')
        cart.add(item_id=item_id, days=days)
        return cart

    def set_days(self, cart: RentalCart, item_id: int, days: int) -> RentalCart:
        self._repository.get(item_id)
        cart.set_days(item_id=item_id, days=days)
        return cart

    def remove_item(self, cart: RentalCart, item_id: int) -> RentalCart:
        cart.remove(item_id)
        return cart

    def display_lines(self, cart: RentalCart) -> list[CartDisplayLine]:
        lines: list[CartDisplayLine] = []
        for line in cart.lines:
            item = self._repository.get(line.item_id)
            lines.append(CartDisplayLine(item=item, days=line.days, subtotal=item.price_per_day * line.days))
        return lines

    def total(self, cart: RentalCart) -> Decimal:
        return sum((line.subtotal for line in self.display_lines(cart)), Decimal('0.00'))

# "Heritage_Rentals/src/heritage_rentals/services/checkout.py"
from __future__ import annotations

from heritage_rentals.domain.cart import RentalCart
from heritage_rentals.domain.models import CheckoutResult
from heritage_rentals.services.cart_service import RentalCartService


class CheckoutError(ValueError):
    pass


class CheckoutService:
    def __init__(self, cart_service: RentalCartService) -> None:
        self._cart_service = cart_service

    def submit(self, user_id: str | None, cart: RentalCart) -> CheckoutResult:
        if not user_id:
            raise CheckoutError('A signed-in user is required for checkout')
        if cart.is_empty:
            raise CheckoutError('Cannot checkout an empty rental cart')
        total = self._cart_service.total(cart)
        return CheckoutResult.create(user_id=user_id, total=total)

