from decimal import Decimal

from heritage_rentals.domain.cart import RentalCart
from heritage_rentals.repositories.memory import InMemoryRentalRepository
from heritage_rentals.services.cart_service import RentalCartService


def test_cart_accumulates_days_and_round_trips_cookie() -> None:
    cart = RentalCart()
    cart.add(101, days=2)
    cart.add(101, days=3)

    restored = RentalCart.from_cookie(cart.to_cookie())

    assert restored.total_days == 5
    assert restored.lines[0].item_id == 101


def test_cart_service_computes_total() -> None:
    repository = InMemoryRentalRepository()
    service = RentalCartService(repository)
    cart = RentalCart()

    service.add_item(cart, item_id=101, days=2)
    service.add_item(cart, item_id=103, days=1)

    assert service.total(cart) == Decimal('48.00')

