from __future__ import annotations

import typer
import uvicorn

from heritage_rentals.config import get_settings
from heritage_rentals.repositories.memory import InMemoryRentalRepository

app = typer.Typer(help='Operate the Heritage Rentals application.')


@app.command()
def serve(host: str = '127.0.0.1', port: int = 8000, reload: bool = False) -> None:
    uvicorn.run('heritage_rentals.web.app:app', host=host, port=port, reload=reload)


@app.command('list-items')
def list_items() -> None:
    settings = get_settings()
    repository = InMemoryRentalRepository()
    typer.echo(settings.app_name)
    for item in repository.list_available():
        typer.echo(f'{item.id}  {item.name}  ${item.price_per_day}/day')

