    user_id: str
    total: Decimal
    submitted_at: datetime

    @classmethod
    def create(cls, user_id: str, total: Decimal) -> 'CheckoutResult':
        stamp = datetime.now(UTC)
        confirmation_id = f'HR-{stamp:%Y%m%d%H%M%S}-{abs(hash((user_id, str(total)))) % 10000:04d}'
        return cls(
            confirmation_id=confirmation_id,
            user_id=user_id,
            total=total,
            submitted_at=stamp,
        )

# "Heritage_Rentals/src/heritage_rentals/domain/cart.py"
from __future__ import annotations

import json
from dataclasses import dataclass, field

from heritage_rentals.domain.models import CartLine


class CartDecodeError(ValueError):
    pass


@dataclass(slots=True)
class RentalCart:
    _lines: dict[int, CartLine] = field(default_factory=dict)

    @classmethod
    def from_cookie(cls, raw: str | None) -> 'RentalCart':
        if not raw:
            return cls()
        try:
            payload = json.loads(raw)
            if not isinstance(payload, dict):
                raise CartDecodeError('Cart cookie payload must be an object')
            lines = payload.get('lines', {})
            if not isinstance(lines, dict):
                raise CartDecodeError('Cart lines must be an object')
            cart = cls()
            for item_id, days in lines.items():
                cart.set_days(int(item_id), int(days))
            return cart
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise CartDecodeError('Unable to decode rental cart cookie') from exc

    def to_cookie(self) -> str:
        return json.dumps({'lines': {str(item_id): line.days for item_id, line in self._lines.items()}}, separators=(',', ':'))

    def add(self, item_id: int, days: int = 1) -> None:
        if days < 1:
            raise ValueError('days must be at least one')
        existing = self._lines.get(item_id)
        new_days = days if existing is None else existing.days + days
        self._lines[item_id] = CartLine(item_id=item_id, days=new_days)

    def set_days(self, item_id: int, days: int) -> None:
        if days < 1:
            self.remove(item_id)
            return
        self._lines[item_id] = CartLine(item_id=item_id, days=days)

    def remove(self, item_id: int) -> None:
        self._lines.pop(item_id, None)

    def clear(self) -> None:
        self._lines.clear()

    @property
    def lines(self) -> tuple[CartLine, ...]:
        return tuple(self._lines.values())

    @property
    def is_empty(self) -> bool:
        return not self._lines

    @property
    def total_days(self) -> int:
        return sum(line.days for line in self._lines.values())

# "Heritage_Rentals/src/heritage_rentals/repositories/memory.py"
from __future__ import annotations

from decimal import Decimal

from heritage_rentals.domain.models import RentalItem


class RentalItemNotFound(KeyError):
    pass


class InMemoryRentalRepository:
    def __init__(self, seed_items: list[RentalItem] | None = None) -> None:
        items = seed_items if seed_items is not None else default_inventory()
        self._items = {item.id: item for item in items}

    def list_available(self) -> list[RentalItem]:
        return sorted((item for item in self._items.values() if item.available), key=lambda item: item.name)

    def get(self, item_id: int) -> RentalItem:
        try:
            return self._items[item_id]
        except KeyError as exc:
            raise RentalItemNotFound(f'Rental item {item_id} was not found') from exc

    def search(self, query: str) -> list[RentalItem]:
        normalized = query.casefold().strip()
        if not normalized:
            return self.list_available()
        return [
            item for item in self.list_available()
            if normalized in item.name.casefold()
            or normalized in item.category.casefold()
            or normalized in item.description.casefold()
        ]


