{% extends 'base.html' %}
{% block content %}
<section class='cart-panel'>
  <h2>Your rental cart</h2>
  {% if lines %}
  <table class='cart-table'>
    <thead>
      <tr>
        <th></th>
        <th>Item</th>
        <th>Name</th>
        <th>Price per day</th>
        <th>Days rented</th>
        <th>Subtotal</th>
      </tr>
    </thead>
    <tbody>
      {% for line in lines %}
      <tr>
        <td><button data-item-id='{{ line.item.id }}' class='danger'>Remove</button></td>
        <td><img class='shopping-cart-image' src='{{ static_url }}{{ line.item.photo_path }}' alt='{{ line.item.name }}'></td>
        <td>{{ line.item.name }}</td>
        <td>${{ '%.2f'|format(line.item.price_per_day) }}</td>
        <td>{{ line.days }}</td>
        <td>${{ '%.2f'|format(line.subtotal) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  <div class='cart-summary'>
    <span>{{ total_days }} rental days</span>
    <strong>Total: ${{ '%.2f'|format(total) }}</strong>
  </div>
  <a class='checkout-button' href='{{ checkout_url }}'>Checkout</a>
  {% if not authenticated %}
  <p class='notice'>Sign in before checkout so we can reserve your rental items.</p>
  {% endif %}
  {% else %}
  <p>Your cart is empty. Add rental items from the catalog API to begin.</p>
  {% endif %}
</section>
{% endblock %}

