from fastapi.testclient import TestClient

from heritage_rentals.config import Settings
from heritage_rentals.web.app import create_app


def client() -> TestClient:
    return TestClient(create_app(Settings(debug=True)))


def test_catalog_endpoint_lists_seed_inventory() -> None:
    response = client().get('/api/catalog')

    assert response.status_code == 200
    assert len(response.json()) >= 4


def test_add_cart_item_sets_cookie_and_returns_total() -> None:
    test_client = client()

    response = test_client.post('/api/cart/items/101?days=2')

    assert response.status_code == 200
    assert response.json()['total'] == '36.00'
    assert 'heritage_rental_cart' in response.cookies


def test_checkout_requires_authenticated_user() -> None:
    test_client = client()
    test_client.post('/api/cart/items/101?days=1')

    response = test_client.post('/api/checkout')

    assert response.status_code == 400
    assert 'signed-in user' in response.json()['detail']


def test_checkout_clears_cart_for_authenticated_user() -> None:
    test_client = client()
    test_client.post('/api/cart/items/101?days=1')

    response = test_client.post('/api/checkout', headers={'x-user-id': 'user-123'})

    assert response.status_code == 200
    assert response.json()['confirmation_id'].startswith('HR-')

