# "Heritage_Rentals/src/heritage_rentals/web/app.py"
from __future__ import annotations

from typing import Annotated

from fastapi import Cookie, FastAPI, Header, HTTPException, Query, Request, Response
from fastapi.responses import HTMLResponse, JSONResponse, RedirectResponse
from fastapi.staticfiles import StaticFiles
from fastapi.templating import Jinja2Templates

from heritage_rentals.config import Settings, get_settings
from heritage_rentals.domain.cart import CartDecodeError, RentalCart
from heritage_rentals.repositories.memory import InMemoryRentalRepository, RentalItemNotFound
from heritage_rentals.services.cart_service import RentalCartService
from heritage_rentals.services.catalog import CatalogService
from heritage_rentals.services.checkout import CheckoutError, CheckoutService
from heritage_rentals.web.schemas import CartResponse, CheckoutResponse, RentalItemSchema


def create_app(settings: Settings | None = None) -> FastAPI:
    settings = settings or get_settings()
    repository = InMemoryRentalRepository()
    catalog_service = CatalogService(repository)
    cart_service = RentalCartService(repository)
    checkout_service = CheckoutService(cart_service)

    api = FastAPI(title=settings.app_name, debug=settings.debug)
    templates = Jinja2Templates(directory=str(settings.template_dir))

    if settings.static_dir.exists():
        api.mount('/static', StaticFiles(directory=str(settings.static_dir)), name='static')

    def read_cart(raw_cookie: str | None) -> RentalCart:
        try:
            return RentalCart.from_cookie(raw_cookie)
        except CartDecodeError:
            return RentalCart()

    def serialize_cart(cart: RentalCart) -> CartResponse:
        return CartResponse(
            lines=[
                {'item': line.item, 'days': line.days, 'subtotal': line.subtotal}
                for line in cart_service.display_lines(cart)
            ],
            total_days=cart.total_days,
            total=cart_service.total(cart),
        )

    def persist_cart(response: Response, cart: RentalCart) -> None:
        if cart.is_empty:
            response.delete_cookie(settings.cart_cookie_name, path='/')
        else:
            response.set_cookie(
                settings.cart_cookie_name,
                cart.to_cookie(),
                httponly=True,
                samesite='lax',
                path='/',
            )

    @api.get('/', include_in_schema=False)
    def home() -> RedirectResponse:
        return RedirectResponse(url='/account/rentalcart')

    @api.get('/account/rentalcart', response_class=HTMLResponse)
    def rental_cart_page(
        request: Request,
        x_user_id: Annotated[str | None, Header(alias='x-user-id')] = None,
        cart_cookie: Annotated[str | None, Cookie(alias=settings.cart_cookie_name)] = None,
    ) -> HTMLResponse:
        cart = read_cart(cart_cookie)
        return templates.TemplateResponse(
            request=request,
            name='account/rentalcart.html',
            context={
                'app_name': settings.app_name,
                'static_url': settings.static_url,
                'lines': cart_service.display_lines(cart),
                'total': cart_service.total(cart),
                'total_days': cart.total_days,
                'authenticated': bool(x_user_id),
                'checkout_url': '/account/checkout' if x_user_id else '/login?next=/account/rentalcart',
            },
        )

    @api.get('/api/catalog', response_model=list[RentalItemSchema])
    def list_catalog(q: str | None = None) -> list[RentalItemSchema]:
        return [RentalItemSchema.model_validate(item, from_attributes=True) for item in catalog_service.list_items(q)]

    @api.get('/api/cart', response_model=CartResponse)
    def get_cart(cart_cookie: Annotated[str | None, Cookie(alias=settings.cart_cookie_name)] = None) -> CartResponse:
        return serialize_cart(read_cart(cart_cookie))

    @api.post('/api/cart/items/{item_id}', response_model=CartResponse)
    def add_cart_item(
        item_id: int,
        days: Annotated[int, Query(ge=1)] = 1,
        cart_cookie: Annotated[str | None, Cookie(alias=settings.cart_cookie_name)] = None,
    ) -> JSONResponse:
        cart = read_cart(cart_cookie)
        try:
            cart_service.add_item(cart, item_id=item_id, days=days)
        except (RentalItemNotFound, ValueError) as exc:
            raise HTTPException(status_code=404, detail=str(exc)) from exc
        body = serialize_cart(cart).model_dump(mode='json')
        response = JSONResponse(body)
        persist_cart(response, cart)
        return response

    @api.patch('/api/cart/items/{item_id}', response_model=CartResponse)
    def set_cart_item_days(
        item_id: int,
        days: Annotated[int, Query(ge=0)],
        cart_cookie: Annotated[str | None, Cookie(alias=settings.cart_cookie_name)] = None,
    ) -> JSONResponse:
        cart = read_cart(cart_cookie)
        try:
            cart_service.set_days(cart, item_id=item_id, days=days)
        except RentalItemNotFound as exc:
            raise HTTPException(status_code=404, detail=str(exc)) from exc
        body = serialize_cart(cart).model_dump(mode='json')
        response = JSONResponse(body)
        persist_cart(response, cart)
        return response

    @api.delete('/api/cart/items/{item_id}', response_model=CartResponse)
    def remove_cart_item(
        item_id: int,
        cart_cookie: Annotated[str | None, Cookie(alias=settings.cart_cookie_name)] = None,
    ) -> JSONResponse:
        cart = read_cart(cart_cookie)
        cart_service.remove_item(cart, item_id=item_id)
        body = serialize_cart(cart).model_dump(mode='json')
        response = JSONResponse(body)
        persist_cart(response, cart)
        return response

    @api.post('/api/checkout', response_model=CheckoutResponse)
    def checkout(
        x_user_id: Annotated[str | None, Header(alias='x-user-id')] = None,
        cart_cookie: Annotated[str | None, Cookie(alias=settings.cart_cookie_name)] = None,
    ) -> JSONResponse:
        cart = read_cart(cart_cookie)
        try:
            result = checkout_service.submit(user_id=x_user_id, cart=cart)
        except CheckoutError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        body = CheckoutResponse.model_validate(result, from_attributes=True).model_dump(mode='json')
        response = JSONResponse(body)
        cart.clear()
        persist_cart(response, cart)
        return response

    return api


