@api_bp.post('/projects')
def create_project_route():
    project = register_project(request.get_json(silent=True) or {})
    return created(project.to_dict())


@api_bp.get('/projects/<uid>')
def get_project_route(uid: str):
    project = get_project(uid)
    return ok(project.to_dict())


@api_bp.get('/projects')
def list_projects_route():
    projects = search_projects(status=request.args.get('status'))
    return ok([project.to_dict() for project in projects], count=len(projects))

