from __future__ import annotations

from dataclasses import dataclass
from os import environ
from pathlib import Path


@dataclass(frozen=True, slots=True)
class Settings:
    app_name: str = 'Atlas Service'
    env: str = 'development'
    debug: bool = False
    database_uri: str = 'sqlite:///atlas.db'
    testing: bool = False

    @classmethod
    def from_env(cls) -> 'Settings':
        root = Path.cwd()
        default_db = f'sqlite:///{root / 'atlas.db'}'
        env = environ.get('ATLAS_ENV', 'development')
        debug = environ.get('ATLAS_DEBUG', '0').lower() in {'1', 'true', 'yes'}
        testing = environ.get('ATLAS_TESTING', '0').lower() in {'1', 'true', 'yes'}
        return cls(
            app_name=environ.get('ATLAS_APP_NAME', 'Atlas Service'),
            env=env,
            debug=debug,
            database_uri=environ.get('ATLAS_DATABASE_URI', default_db),
            testing=testing,
        )

    def as_flask_config(self) -> dict[str, object]:
        return {
            'SQLALCHEMY_DATABASE_URI': self.database_uri,
            'SQLALCHEMY_TRACK_MODIFICATIONS': False,
            'TESTING': self.testing,
            'DEBUG': self.debug,
            'JSON_SORT_KEYS': False,
        }

