from __future__ import annotations

from sqlalchemy.exc import IntegrityError

from atlas_service.extensions import db
from atlas_service.response import ResponseError
from atlas_service.schemas import ProjectSchema, ProjectStatus, UserSchema


def commit_or_response_error() -> None:
    try:
        db.session.commit()
    except IntegrityError as exc:
        db.session.rollback()
        raise ResponseError(info='数据违反唯一性或外键约束', code='conflict', status_code=409) from exc


def create_user(email: str, display_name: str) -> UserSchema:
    user = UserSchema(email=email.strip().lower(), display_name=display_name.strip())
    db.session.add(user)
    commit_or_response_error()
    return user


def find_user_by_uid(uid: str) -> UserSchema | None:
    return UserSchema.query.filter_by(uid=uid).first()


def create_project(owner: UserSchema, name: str, description: str = '', status: ProjectStatus = ProjectStatus.DRAFT) -> ProjectSchema:
    project = ProjectSchema(owner=owner, name=name.strip(), description=description.strip(), status=status)
    db.session.add(project)
    commit_or_response_error()
    return project


def list_projects(status: ProjectStatus | None = None) -> list[ProjectSchema]:
    query = ProjectSchema.query.order_by(ProjectSchema.created_at.desc())
    if status is not None:
        query = query.filter_by(status=status)
    return list(query.all())

# "Atlas_Service/src/atlas_service/services/projects.py"
from __future__ import annotations

from atlas_service import repositories
from atlas_service.models.project import Project
from atlas_service.models.user import User
from atlas_service.response import ResponseError
from atlas_service.schemas import ProjectStatus


def register_user(payload: dict) -> User:
    email = str(payload.get('email', '')).strip()
    display_name = str(payload.get('display_name', '')).strip()
    if not email or '@' not in email:
        raise ResponseError(info='邮箱格式不正确', code='validation_error', status_code=422)
    if not display_name:
        raise ResponseError(info='显示名称不能为空', code='validation_error', status_code=422)
    return User(repositories.create_user(email=email, display_name=display_name))


def register_project(payload: dict) -> Project:
    owner_uid = str(payload.get('owner_uid', '')).strip()
    name = str(payload.get('name', '')).strip()
    description = str(payload.get('description', '')).strip()
    status_text = str(payload.get('status', ProjectStatus.DRAFT.value)).strip()
    if not owner_uid:
        raise ResponseError(info='owner_uid 不能为空', code='validation_error', status_code=422)
    if not name:
        raise ResponseError(info='项目名称不能为空', code='validation_error', status_code=422)
    owner = repositories.find_user_by_uid(owner_uid)
    if owner is None:
        raise ResponseError(info='项目所属用户不存在', code='not_found', status_code=404)
    try:
        status = ProjectStatus(status_text)
    except ValueError as exc:
        raise ResponseError(info='项目状态不合法', code='validation_error', status_code=422) from exc
    return Project(repositories.create_project(owner=owner, name=name, description=description, status=status))


def get_user(uid: str) -> User:
    return User.get_by_uid(uid)


def get_project(uid: str) -> Project:
    return Project.get_by_uid(uid)


def search_projects(status: str | None = None) -> list[Project]:
    parsed_status = None
    if status:
        try:
            parsed_status = ProjectStatus(status)
        except ValueError as exc:
            raise ResponseError(info='项目状态不合法', code='validation_error', status_code=422) from exc
    return [Project(schema) for schema in repositories.list_projects(parsed_status)]

