from __future__ import annotations

from flask import Flask, jsonify
from werkzeug.exceptions import HTTPException

from atlas_service.response import ResponseError, error_response


def register_error_handlers(app: Flask) -> None:
    @app.errorhandler(ResponseError)
    def handle_response_error(exc: ResponseError):
        return error_response(exc)

    @app.errorhandler(HTTPException)
    def handle_http_exception(exc: HTTPException):
        payload = {'error': {'code': exc.name.lower().replace(' ', '_'), 'message': exc.description}}
        return jsonify(payload), exc.code or 500

    @app.errorhandler(Exception)
    def handle_unexpected_exception(exc: Exception):
        app.logger.exception('Unhandled exception', exc_info=exc)
        payload = {'error': {'code': 'internal_server_error', 'message': '服务内部错误'}}
        return jsonify(payload), 500

