from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from flask import jsonify
from werkzeug import Response


@dataclass(slots=True)
class ResponseError(Exception):
    info: str
    code: str = 'bad_request'
    status_code: int = 400

    def to_dict(self) -> dict[str, Any]:
        return {'error': {'code': self.code, 'message': self.info}}


def ok(data: Any = None, status_code: int = 200, **meta: Any) -> tuple[Response, int]:
    payload: dict[str, Any] = {'ok': True, 'data': data}
    if meta:
        payload['meta'] = meta
    return jsonify(payload), status_code


def created(data: Any) -> tuple[Response, int]:
    return ok(data=data, status_code=201)


def error_response(exc: ResponseError) -> tuple[Response, int]:
    return jsonify(exc.to_dict()), exc.status_code

