import uuid
from datetime import datetime, timezone
from enum import Enum

from atlas_service.extensions import db


class ProjectStatus(Enum):
    DRAFT = 'draft'
    ACTIVE = 'active'
    ARCHIVED = 'archived'


class TimestampMixin:
    created_at = db.Column(db.DateTime(timezone=True), nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = db.Column(
        db.DateTime(timezone=True),
        nullable=False,
        default=lambda: datetime.now(timezone.utc),
        onupdate=lambda: datetime.now(timezone.utc),
    )


class UserSchema(TimestampMixin, db.Model):
    __tablename__ = 'users'

    id = db.Column(db.Integer, primary_key=True)
    uid = db.Column(db.String(36), unique=True, nullable=False, default=lambda: str(uuid.uuid4()))
    email = db.Column(db.String(255), unique=True, nullable=False, index=True)
    display_name = db.Column(db.String(120), nullable=False)
    is_active = db.Column(db.Boolean, nullable=False, default=True)

    projects = db.relationship('ProjectSchema', back_populates='owner', cascade='all, delete-orphan')

    def __repr__(self) -> str:
        return f'<User {self.uid} {self.email}>'


class ProjectSchema(TimestampMixin, db.Model):
    __tablename__ = 'projects'

    id = db.Column(db.Integer, primary_key=True)
    uid = db.Column(db.String(36), unique=True, nullable=False, default=lambda: str(uuid.uuid4()))
    name = db.Column(db.String(180), nullable=False, index=True)
    description = db.Column(db.Text, nullable=False, default='')
    status = db.Column(db.Enum(ProjectStatus), nullable=False, default=ProjectStatus.DRAFT)
    owner_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False, index=True)

    owner = db.relationship('UserSchema', back_populates='projects')

    def __repr__(self) -> str:
        return f'<Project {self.uid} {self.name}>'

