from __future__ import annotations

from abc import ABC, abstractmethod
from datetime import datetime
from enum import Enum
from typing import Any, ClassVar, Iterable

from atlas_service.response import ResponseError


class ModelBase(ABC):
    lite_exclude_keys: ClassVar[list[str]] = []

    @classmethod
    @abstractmethod
    def _get_cls_schema(cls):
        raise NotImplementedError

    def __new__(cls, schema):
        if schema is None:
            return None
        return object.__new__(cls)

    def __init__(self, schema):
        self.schema = schema

    @property
    def id(self) -> int:
        return self.schema.id

    @property
    def uid(self) -> str:
        return self.schema.uid

    def refresh(self) -> None:
        schema = self._get_cls_schema().query.get(self.schema.id)
        if schema is None:
            raise ResponseError(info='对应编号信息不存在', code='not_found', status_code=404)
        self.schema = schema

    def to_dict(
        self,
        include_keys: Iterable[str] | None = None,
        exclude_keys: Iterable[str] | None = None,
        depth: int = 0,
        lite: bool = False,
    ) -> dict[str, Any] | str:
        return_dict: dict[str, Any] = {}
        attrs = self.__class__.__dict__
        selected = list(include_keys or [name for name in attrs if not name.startswith('_')])
        excluded = list(exclude_keys or [])
        if lite:
            excluded.extend(getattr(self, 'lite_exclude_keys', []))
        selected = [name for name in selected if name not in excluded]
        if depth > 1:
            return self.uid
        for key, descriptor in attrs.items():
            if key not in selected or not isinstance(descriptor, property):
                continue
            value = getattr(self, key)
            return_dict[key] = self._serialize_value(value, depth)
        return return_dict

    @classmethod
    def _serialize_value(cls, value: Any, depth: int) -> Any:
        if isinstance(value, Enum):
            return value.value
        if isinstance(value, list):
            return [item.to_dict(depth=depth + 1, lite=True) if hasattr(item, 'to_dict') else item for item in value]
        if isinstance(value, dict):
            return {k: v.to_dict(depth=depth + 1, lite=True) if hasattr(v, 'to_dict') else v for k, v in value.items()}
        if isinstance(value, datetime):
            return value.isoformat()
        if hasattr(value, 'to_dict'):
            return value.to_dict(depth=depth + 1, lite=True)
        return value

    @classmethod
    def get_by_id(cls, id: int):
        schema = cls._get_cls_schema().query.get(id)
        if schema is None:
            raise ResponseError(info='对应编号信息不存在', code='not_found', status_code=404)
        return cls(schema)

    @classmethod
    def get_by_uid(cls, uid: str):
        schema = cls._get_cls_schema().query.filter_by(uid=uid).first()
        if schema is None:
            raise ResponseError(info='对应 UID 信息不存在', code='not_found', status_code=404)
        return cls(schema)

