from __future__ import annotations

from flask import Blueprint, request

from atlas_service.response import created, ok
from atlas_service.services.projects import get_project, get_user, register_project, register_user, search_projects

api_bp = Blueprint('api', __name__, url_prefix='/api')


@api_bp.post('/users')
