    db.drop_all()
    click.echo('Database schema dropped.')


@main.command('seed')
@with_appcontext
def seed_command() -> None:
    seed_database()
    click.echo('Seed data inserted.')


@main.command('run')
@click.option('--host', default='127.0.0.1')
@click.option('--port', default=5000, type=int)
def run_command(host: str, port: int) -> None:
    app = create_app()
    with app.app_context():
        db.create_all()
    app.run(host=host, port=port)


@main.command('shell')
def shell_command() -> None:
    app = create_app()
    with app.app_context():
        import code

        code.interact(local={'app': app, 'db': db})

