from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from othello.domain import Board, Move
from othello.engine import GameState


def state_to_dict(state: GameState) -> dict[str, Any]:
    return {
        'board': state.board.to_jsonable(),
        'player': state.player,
        'consecutive_passes': state.consecutive_passes,
        'ply': state.ply,
        'legal_moves': [move.to_algebraic() for move in state.legal_moves],
        'result': state.result.value,
    }


def state_from_dict(payload: dict[str, Any]) -> GameState:
    return GameState(
        board=Board.from_jsonable(payload['board']),
        player=int(payload['player']),
        consecutive_passes=int(payload.get('consecutive_passes', 0)),
        ply=int(payload.get('ply', 0)),
    )


def save_state(path: str | Path, state: GameState) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(state_to_dict(state), indent=2) + '\n', encoding='utf-8')


def load_state(path: str | Path) -> GameState:
    return state_from_dict(json.loads(Path(path).read_text(encoding='utf-8')))


def append_record(path: str | Path, record: dict[str, Any]) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('a', encoding='utf-8') as handle:
        handle.write(json.dumps(record, sort_keys=True) + '\n')

# "OthelloLab/src/othello/selfplay.py"
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from othello.agents import build_agent
from othello.domain import BLACK, WHITE
from othello.engine import GameEngine
from othello.persistence import append_record, state_to_dict


@dataclass(frozen=True)
class SelfPlayConfig:
    agent: str = 'mcts'
    games: int = 10
    depth: int = 3
    rollouts: int = 100
    seed: int = 7


def generate_self_play(config: SelfPlayConfig, output: str | Path) -> None:
    engine = GameEngine()
    for game_id in range(config.games):
        black = build_agent(config.agent, depth=config.depth, rollouts=config.rollouts, seed=config.seed + game_id * 2)
        white = build_agent(config.agent, depth=config.depth, rollouts=config.rollouts, seed=config.seed + game_id * 2 + 1)
        state = engine.initial_state()
        trajectory = []
        while not state.is_terminal:
            agent = black if state.player == BLACK else white
            move = agent.choose_move(state)
            trajectory.append({'state': state_to_dict(state), 'move': None if move is None else move.to_algebraic()})
            state = engine.step(state, move)
        append_record(output, {'game_id': game_id, 'result': state.result.value, 'black_score': state.board.count(BLACK), 'white_score': state.board.count(WHITE), 'trajectory': trajectory})

# "OthelloLab/src/othello/evaluation.py"
from __future__ import annotations

from dataclasses import dataclass

from othello.agents import build_agent
from othello.domain import BLACK, WHITE, GameResult
from othello.engine import GameEngine


@dataclass(frozen=True)
class MatchResult:
    black_wins: int
    white_wins: int
    draws: int
    games: int

    @property
    def black_score_rate(self) -> float:
        return (self.black_wins + 0.5 * self.draws) / self.games if self.games else 0.0


def evaluate_agents(black_kind: str, white_kind: str, games: int, depth: int = 3, rollouts: int = 100) -> MatchResult:
    if games < 1:
        raise ValueError('games must be positive')
    engine = GameEngine()
    black_wins = white_wins = draws = 0
    for idx in range(games):
        black = build_agent(black_kind, depth=depth, rollouts=rollouts, seed=idx * 2)
        white = build_agent(white_kind, depth=depth, rollouts=rollouts, seed=idx * 2 + 1)
        final = engine.play(black, white)
        if final.result == GameResult.BLACK_WIN:
            black_wins += 1
        elif final.result == GameResult.WHITE_WIN:
            white_wins += 1
        else:
            draws += 1
    return MatchResult(black_wins=black_wins, white_wins=white_wins, draws=draws, games=games)

# "OthelloLab/src/othello/cli.py"
from __future__ import annotations

import argparse
import sys

from othello.agents import build_agent
from othello.domain import BLACK, Move
from othello.engine import Agent, GameEngine, GameState
from othello.evaluation import evaluate_agents
from othello.selfplay import SelfPlayConfig, generate_self_play


class HumanAgent(Agent):
    name = 'human'

    def choose_move(self, state: GameState) -> Move | None:
        if not state.legal_moves:
            print('No legal moves; passing.')
            return None
        legal = {move.to_algebraic(): move for move in state.legal_moves}
        while True:
            text = input(f'Player {state.player} move {sorted(legal)}: ').strip().lower()
            if text in legal:
                return legal[text]
            print('Invalid move.')


def _agent(kind: str, depth: int, rollouts: int) -> Agent:
    if kind == 'human':
        return HumanAgent()
    return build_agent(kind, depth=depth, rollouts=rollouts)


def play(args: argparse.Namespace) -> int:
    engine = GameEngine()
    black = _agent(args.black, args.depth, args.mcts_rollouts)
    white = _agent(args.white, args.depth, args.mcts_rollouts)
    state = engine.initial_state()
    while not state.is_terminal:
        print(state.board.to_symbols())
        print(f'Black {state.board.count(1)} White {state.board.count(-1)}')
        agent = black if state.player == BLACK else white
        move = agent.choose_move(state)
        print(f'{agent.name} plays {None if move is None else move.to_algebraic()}')
        state = engine.step(state, move)
    print(state.board.to_symbols())
    print(f'Result: {state.result.value}')
    return 0


def evaluate(args: argparse.Namespace) -> int:
    result = evaluate_agents(args.black, args.white, args.games, args.depth, args.mcts_rollouts)
    print(f'black_wins={result.black_wins} white_wins={result.white_wins} draws={result.draws} black_score_rate={result.black_score_rate:.3f}')
    return 0


def self_play(args: argparse.Namespace) -> int:
    config = SelfPlayConfig(agent=args.agent, games=args.games, depth=args.depth, rollouts=args.mcts_rollouts)
    generate_self_play(config, args.output)
    print(f'wrote {args.games} games to {args.output}')
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog='othello')
    sub = parser.add_subparsers(dest='command', required=True)

    p_play = sub.add_parser('play')
    p_play.add_argument('--black', choices=['human', 'random', 'minimax', 'mcts'], default='human')
    p_play.add_argument('--white', choices=['human', 'random', 'minimax', 'mcts'], default='minimax')
    p_play.add_argument('--depth', type=int, default=3)
    p_play.add_argument('--mcts-rollouts', type=int, default=100)
    p_play.set_defaults(func=play)

    p_eval = sub.add_parser('evaluate')
    p_eval.add_argument('--black', choices=['random', 'minimax', 'mcts'], default='mcts')
    p_eval.add_argument('--white', choices=['random', 'minimax', 'mcts'], default='minimax')
    p_eval.add_argument('--games', type=int, default=10)
    p_eval.add_argument('--depth', type=int, default=3)
    p_eval.add_argument('--mcts-rollouts', type=int, default=100)
    p_eval.set_defaults(func=evaluate)

    p_self = sub.add_parser('self-play')
    p_self.add_argument('--agent', choices=['random', 'minimax', 'mcts'], default='mcts')
    p_self.add_argument('--games', type=int, default=10)
    p_self.add_argument('--output', default='data/selfplay.jsonl')
    p_self.add_argument('--depth', type=int, default=3)
    p_self.add_argument('--mcts-rollouts', type=int, default=100)
    p_self.set_defaults(func=self_play)
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    return int(args.func(args))


if __name__ == '__main__':
    raise SystemExit(main(sys.argv[1:]))

