from __future__ import annotations

from typing import Any

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

from othello.agents import build_agent
from othello.domain import Move
from othello.engine import GameEngine
from othello.persistence import state_from_dict, state_to_dict

app = FastAPI(title='OthelloLab API', version='0.1.0')
engine = GameEngine()


class StateRequest(BaseModel):
    state: dict[str, Any]


class MoveRequest(BaseModel):
    state: dict[str, Any]
    move: str | None = None


class AgentRequest(BaseModel):
    state: dict[str, Any]
    agent: str = Field(default='minimax', pattern='^(random|minimax|mcts)$')
    depth: int = 3
    rollouts: int = 100


@app.get('/health')
def health() -> dict[str, str]:
    return {'status': 'ok'}


@app.get('/new')
def new_game() -> dict[str, Any]:
    return state_to_dict(engine.initial_state())


@app.post('/legal-moves')
def legal_moves(request: StateRequest) -> dict[str, Any]:
    try:
        state = state_from_dict(request.state)
        return {'legal_moves': [move.to_algebraic() for move in state.legal_moves]}
    except Exception as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@app.post('/step')
def step(request: MoveRequest) -> dict[str, Any]:
    try:
        state = state_from_dict(request.state)
        move = None if request.move is None else Move.from_algebraic(request.move)
        return state_to_dict(engine.step(state, move))
    except Exception as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@app.post('/agent-move')
def agent_move(request: AgentRequest) -> dict[str, Any]:
    try:
        state = state_from_dict(request.state)
        agent = build_agent(request.agent, depth=request.depth, rollouts=request.rollouts)
        move = agent.choose_move(state)
        return {'move': None if move is None else move.to_algebraic()}
    except Exception as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc

