from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml
from jinja2 import ChoiceLoader, Environment, FileSystemLoader, StrictUndefined, Undefined
from jinja2.exceptions import TemplateError

from jiml.config import RenderConfig
from jiml.exceptions import DocumentParseError, TemplateRenderError
from jiml.filters import register_filters
from jiml.io import detect_format
from jiml.models import RenderedDocument


def create_environment(template_path: Path, config: RenderConfig) -> Environment:
    search_paths = [template_path.parent, *config.search_paths]
    loader = ChoiceLoader([FileSystemLoader(str(path)) for path in search_paths])
    environment = Environment(
        loader=loader,
        autoescape=False,
        undefined=StrictUndefined if config.strict else Undefined,
        keep_trailing_newline=config.keep_trailing_newline,
        trim_blocks=True,
        lstrip_blocks=True,
    )
    return register_filters(environment)


def render_template(template_text: str, context: dict[str, Any], config: RenderConfig | None = None) -> str:
    config = config or RenderConfig()
    environment = Environment(
        autoescape=False,
        undefined=StrictUndefined if config.strict else Undefined,
        keep_trailing_newline=config.keep_trailing_newline,
        trim_blocks=True,
        lstrip_blocks=True,
    )
    register_filters(environment)
    try:
        return environment.from_string(template_text).render(**context)
    except TemplateError as exc:
        raise TemplateRenderError(str(exc)) from exc


def parse_rendered_text(text: str, template_path: Path) -> Any:
    fmt = detect_format(template_path)
    if fmt == 'json':
        import json

        try:
            return json.loads(text)
        except json.JSONDecodeError as exc:
            raise DocumentParseError(f'Rendered JSON is invalid for {template_path}: {exc}') from exc
    if fmt == 'yaml':
        try:
            return yaml.safe_load(text) or {}
        except yaml.YAMLError as exc:
            raise DocumentParseError(f'Rendered YAML is invalid for {template_path}: {exc}') from exc
    return text


def render_file(template_path: Path, config: RenderConfig, context: dict[str, Any]) -> RenderedDocument:
    if not template_path.exists():
        raise TemplateRenderError(f'Template does not exist: {template_path}')
    environment = create_environment(template_path, config)
    try:
        template = environment.get_template(template_path.name)
        text = template.render(**context)
    except TemplateError as exc:
        raise TemplateRenderError(f'Failed to render {template_path}: {exc}') from exc
    if config.parse_rendered:
        data = parse_rendered_text(text, template_path)
        structured = not isinstance(data, str)
    else:
        data = text
        structured = False
    return RenderedDocument(template_path=template_path, text=text, data=data, structured=structured)

# "Jiml/src/jiml/cli.py"
from __future__ import annotations

import argparse
import sys
from pathlib import Path
from typing import Sequence

from jiml.config import RenderConfig
from jiml.exceptions import JimlError
from jiml.io import choose_output_format, load_context, write_output
from jiml.renderer import render_file


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog='jiml',
        description='Render JSON/YAML/TOML templates with structured input data.',
    )
    parser.add_argument('-t', '--template', type=Path, required=True, help='Template file to render.')
    parser.add_argument(
        '-i',
        '--input',
        type=Path,
        action='append',
        default=[],
        help='JSON, YAML, or TOML context file. May be specified multiple times.',
    )
    parser.add_argument('-o', '--output', type=Path, help='Output path. Defaults to stdout.')
    parser.add_argument(
        '-f',
        '--format',
        choices=['auto', 'json', 'yaml', 'text'],
        default='auto',
        help='Output format. Defaults to extension-based detection.',
    )
    parser.add_argument(
        '--set',
        dest='assignments',
        action='append',
        default=[],
        help='Override context using dotted key=value syntax. Values are parsed as JSON when possible.',
    )
    parser.add_argument(
        '--search-path',
        type=Path,
        action='append',
        default=[],
        help='Additional directory for template includes.',
    )
    strict_group = parser.add_mutually_exclusive_group()
    strict_group.add_argument('--strict', dest='strict', action='store_true', default=True)
    strict_group.add_argument('--no-strict', dest='strict', action='store_false')
    parser.add_argument('--text', action='store_true', help='Do not parse rendered output as structured data.')
    parser.add_argument('--strip-trailing-newline', action='store_true')
    return parser


def parse_args(*argv: str | Sequence[str]) -> argparse.Namespace:
    parser = build_parser()
    if not argv:
        return parser.parse_args()
    if len(argv) == 1 and isinstance(argv[0], Sequence) and not isinstance(argv[0], str):
        return parser.parse_args(list(argv[0]))
    return parser.parse_args([str(item) for item in argv])


def main(args: argparse.Namespace | Sequence[str] | None = None) -> int:
    if args is None:
        namespace = parse_args()
    elif isinstance(args, argparse.Namespace):
        namespace = args
    else:
        namespace = parse_args(args)

    try:
        context = load_context(namespace.input, namespace.assignments)
        config = RenderConfig.from_args(namespace)
        rendered = render_file(namespace.template, config=config, context=context)
        output_format = choose_output_format(namespace.output, config.output_format, rendered.structured)
        output_value = rendered.data if rendered.structured or output_format != 'text' else rendered.text
        text = write_output(namespace.output, output_value, output_format)
        if namespace.output is None:
            sys.stdout.write(text)
        return 0
    except JimlError as exc:
        print(f'jiml: {exc}', file=sys.stderr)
        return 2


def entrypoint() -> int:
    return main()

# "Jiml/src/jiml/watch.py"
from __future__ import annotations

import time
from collections.abc import Callable
from pathlib import Path


def newest_mtime(paths: list[Path]) -> float:
    mtimes: list[float] = []
    for path in paths:
        if path.exists():
            mtimes.append(path.stat().st_mtime)
    return max(mtimes, default=0.0)


def watch(paths: list[Path], callback: Callable[[], None], interval: float = 0.5, once: bool = False) -> None:
    previous = newest_mtime(paths)
    callback()
    if once:
        return
    while True:
        time.sleep(interval)
        current = newest_mtime(paths)
        if current > previous:
            previous = current
            callback()

