@dataclass(frozen=True, slots=True)
class RenderConfig:
    strict: bool = True
    output_format: OutputFormat = 'auto'
    search_paths: tuple[Path, ...] = field(default_factory=tuple)
    keep_trailing_newline: bool = True
    parse_rendered: bool = True

    @classmethod
    def from_args(cls, args: object) -> 'RenderConfig':
        search_paths: Sequence[Path] = getattr(args, 'search_path', ()) or ()
        return cls(
            strict=bool(getattr(args, 'strict', True)),
            output_format=getattr(args, 'format', 'auto'),
            search_paths=tuple(Path(p) for p in search_paths),
            keep_trailing_newline=not bool(getattr(args, 'strip_trailing_newline', False)),
            parse_rendered=not bool(getattr(args, 'text', False)),
        )

