import json

import jiml.cli


def write_file(path, text):
    path.write_text(text)
    return path


def test_argparse(tmp_path):
    tmpl = write_file(tmp_path / 't.yaml', 'key: {{ var }}')
    inp = write_file(tmp_path / 'i.json', '{"var": "Hello!"}')
    out = tmp_path / 'o.json'

    code = jiml.cli.main(jiml.cli.parse_args(
        '-t', str(tmpl),
        '-i', str(inp),
        '-o', str(out),
    ))

    assert code == 0
    assert json.loads(out.read_text()) == {'key': 'Hello!'}


def test_cli_set_override(tmp_path):
    tmpl = write_file(tmp_path / 'service.yaml', 'service:\n  port: {{ service.port }}\n')
    out = tmp_path / 'service.json'
    code = jiml.cli.main(jiml.cli.parse_args(
        '-t', str(tmpl),
        '--set', 'service.port=9090',
        '-o', str(out),
    ))
    assert code == 0
    assert json.loads(out.read_text()) == {'service': {'port': 9090}}

