# "QueryDNF/src/querydnf/validation.py"
'''Validation helpers for document filter expressions.'''

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

from querydnf.exceptions import QueryValidationError

LOGICAL_OPERATORS = {'$and', '$or', '$not'}
COMPARISON_OPERATORS = {'$eq', '$ne', '$gt', '$gte', '$lt', '$lte', '$in', '$nin', '$exists', '$regex'}


def ensure_query(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise QueryValidationError('query must be a mapping')
    return dict(value)


def validate_query(query: Mapping[str, Any], *, strict_unknown_operators: bool = True) -> None:
    '''Validate common structural issues without rejecting useful Mongo-like filters.'''
    if not isinstance(query, Mapping):
        raise QueryValidationError('query must be a mapping')
    for key, value in query.items():
        if key in {'$and', '$or'}:
            if not isinstance(value, list) or not value:
                raise QueryValidationError(f'{key} must be a non-empty list')
            for item in value:
                validate_query(ensure_query(item), strict_unknown_operators=strict_unknown_operators)
        elif key == '$not':
            validate_query(ensure_query(value), strict_unknown_operators=strict_unknown_operators)
        elif key.startswith('$'):
            raise QueryValidationError(f'unknown top-level operator: {key}')
        elif isinstance(value, Mapping):
            for op, operand in value.items():
                if isinstance(op, str) and op.startswith('$'):
                    if strict_unknown_operators and op not in COMPARISON_OPERATORS:
                        raise QueryValidationError(f'unknown comparison operator for {key}: {op}')
                    if op in {'$in', '$nin'} and not isinstance(operand, list):
                        raise QueryValidationError(f'{op} operand for {key} must be a list')
                    if op == '$exists' and not isinstance(operand, bool):
                        raise QueryValidationError(f'$exists operand for {key} must be boolean')

# "QueryDNF/src/querydnf/dnf_converter.py"
'''Conversion of Mongo-like query dictionaries to disjunctive normal form.'''

from __future__ import annotations

from copy import deepcopy
from typing import Any

from querydnf.config import Settings
from querydnf.exceptions import QueryTooComplexError
from querydnf.types import Clause, Query
from querydnf.validation import validate_query


def convert(query: Query, *, settings: Settings | None = None) -> Query:
    '''Return an equivalent query in canonical DNF: {'$or': [clause_or_and, ...]}.'''
    cfg = settings or Settings.from_env()
    validate_query(query, strict_unknown_operators=cfg.strict_unknown_operators)
    terms = _to_terms(deepcopy(query))
    if len(terms) > cfg.max_dnf_terms:
        raise QueryTooComplexError(f'DNF expansion produced {len(terms)} terms, limit is {cfg.max_dnf_terms}')
    return {'$or': [_term_to_query(term) for term in terms]}


def _to_terms(expr: Query) -> list[list[Clause]]:
    if not expr:
        return [[]]

    implicit_and: list[list[Clause]] = [[]]
    for key, value in expr.items():
        if key == '$and':
            part = [[]]
            for child in value:
                part = _cross_product(part, _to_terms(child))
        elif key == '$or':
            part = []
            for child in value:
                part.extend(_to_terms(child))
        elif key == '$not':
            part = _negate_to_terms(value)
        else:
            part = [[{key: value}]]
        implicit_and = _cross_product(implicit_and, part)
    return _dedupe_terms(implicit_and)


def _negate_to_terms(expr: Query) -> list[list[Clause]]:
    '''Apply a pragmatic subset of De Morgan conversion for common filters.'''
    if '$and' in expr and len(expr) == 1:
        return _to_terms({'$or': [{'$not': child} for child in expr['$and']]})
    if '$or' in expr and len(expr) == 1:
        return _to_terms({'$and': [{'$not': child} for child in expr['$or']]})
    if len(expr) == 1:
        field, condition = next(iter(expr.items()))
        if field.startswith('$'):
            return [[{'$not': expr}]]
        return [[{field: _negate_condition(condition)}]]
    return [[{'$not': expr}]]


def _negate_condition(condition: Any) -> Any:
    if not isinstance(condition, dict):
        return {'$ne': condition}
    negated: dict[str, Any] = {}
    inverse = {
        '$eq': '$ne',
        '$ne': '$eq',
        '$gt': '$lte',
        '$gte': '$lt',
        '$lt': '$gte',
        '$lte': '$gt',
        '$in': '$nin',
        '$nin': '$in',
        '$exists': '$exists',
    }
    for op, operand in condition.items():
        target = inverse.get(op)
        if target is None:
            return {'$not': condition}
        negated[target] = not operand if op == '$exists' else operand
    return negated


def _cross_product(left: list[list[Clause]], right: list[list[Clause]]) -> list[list[Clause]]:
    return [a + b for a in left for b in right]


def _term_to_query(term: list[Clause]) -> Query:
    if len(term) == 0:
        return {}
    if len(term) == 1:
        return term[0]
    return {'$and': term}


def _dedupe_terms(terms: list[list[Clause]]) -> list[list[Clause]]:
    seen: set[str] = set()
    result: list[list[Clause]] = []
    for term in terms:
        key = repr(term)
        if key not in seen:
            seen.add(key)
            result.append(term)
    return result

# "QueryDNF/src/querydnf/parser.py"
'''Parser utilities that expose conjunction products and flattened clauses.'''

from __future__ import annotations

from typing import Any

from querydnf import dnf_converter
from querydnf.types import Clause, ParsedConjunction, Query


def parse(query: Query) -> tuple[list[dict[str, Any]], list[Clause]]:
    '''Convert query to DNF and return candidate products plus all atomic clauses.

    This preserves the interface of the original source file: each product contains
    the DNF conjunction product under cp and its atomic clauses under clauses.
    '''
    query = dnf_converter.convert(query)
    cp_clause_list: list[dict[str, Any]] = []
    clause_list: list[Clause] = []
    for cp in query['$or']:
        clauses: list[Clause] = []
        if '$and' in cp:
            for clause in cp['$and']:
                clauses.append(clause)
                clause_list.append(clause)
        else:
            clause = cp
            clauses.append(clause)
            clause_list.append(clause)
        cp_clause_list.append({'cp': cp, 'clauses': clauses})
    return cp_clause_list, clause_list


def parse_models(query: Query) -> tuple[list[ParsedConjunction], list[Clause]]:
    products, clauses = parse(query)
    return [ParsedConjunction(cp=item['cp'], clauses=item['clauses']) for item in products], clauses


def extract_fields(clauses: list[Clause]) -> list[str]:
    fields: set[str] = set()
    for clause in clauses:
        for key in clause:
            if not key.startswith('$'):
                fields.add(key)
    return sorted(fields)

# "QueryDNF/src/querydnf/evaluator.py"
'''Evaluate Mongo-like filters against in-memory Python mappings.'''

from __future__ import annotations

import re
from collections.abc import Mapping
from typing import Any

from querydnf.types import Document, Query
from querydnf.validation import validate_query

MISSING = object()


def matches(query: Query, document: Document) -> bool:
    validate_query(query)
    return _matches_query(query, document)


def _matches_query(query: Mapping[str, Any], document: Document) -> bool:
    for key, value in query.items():
        if key == '$and':
            if not all(_matches_query(child, document) for child in value):
                return False
        elif key == '$or':
            if not any(_matches_query(child, document) for child in value):
                return False
        elif key == '$not':
            if _matches_query(value, document):
                return False
        else:
            if not _matches_field(document.get(key, MISSING), value):
                return False
    return True


def _matches_field(actual: Any, expected: Any) -> bool:
    if isinstance(expected, Mapping) and any(str(k).startswith('$') for k in expected):
        return all(_apply_operator(actual, op, operand) for op, operand in expected.items())
    return actual == expected


def _apply_operator(actual: Any, op: str, operand: Any) -> bool:
    if op == '$eq':
        return actual == operand
    if op == '$ne':
        return actual != operand
    if op == '$gt':
        return actual is not MISSING and actual > operand
    if op == '$gte':
        return actual is not MISSING and actual >= operand
    if op == '$lt':
        return actual is not MISSING and actual < operand
    if op == '$lte':
        return actual is not MISSING and actual <= operand
    if op == '$in':
        return actual in operand
    if op == '$nin':
        return actual not in operand
    if op == '$exists':
        return (actual is not MISSING) is operand
    if op == '$regex':
        return actual is not MISSING and re.search(str(operand), str(actual)) is not None
    if op == '$not':
        return not _matches_field(actual, operand)
    raise ValueError(f'unsupported operator: {op}')

# "QueryDNF/src/querydnf/optimizer.py"
'''Simple planning hints for downstream indexes and search backends.'''

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from querydnf.parser import extract_fields, parse
from querydnf.types import Clause, Query


@dataclass(frozen=True, slots=True)
class PlanHint:
    conjunction_index: int
    fields: tuple[str, ...]
    equality_fields: tuple[str, ...]
    range_fields: tuple[str, ...]
    score: float


def choose_plan(query: Query, available_indexes: list[tuple[str, ...]] | None = None) -> PlanHint:
    products, _ = parse(query)
    hints = [_score_product(i, item['clauses'], available_indexes or []) for i, item in enumerate(products)]
    return max(hints, key=lambda hint: hint.score)


def explain(query: Query) -> dict[str, Any]:
    products, clauses = parse(query)
    fields = extract_fields(clauses)
    plan = choose_plan(query)
    return {
        'dnf_conjunctions': len(products),
        'clause_count': len(clauses),
        'fields': fields,
        'recommended_plan': {
            'conjunction_index': plan.conjunction_index,
            'fields': list(plan.fields),
            'equality_fields': list(plan.equality_fields),
            'range_fields': list(plan.range_fields),
            'score': plan.score,
        },
    }


def _score_product(index: int, clauses: list[Clause], indexes: list[tuple[str, ...]]) -> PlanHint:
    fields: list[str] = []
    equality: list[str] = []
    ranges: list[str] = []
    for clause in clauses:
        for field, condition in clause.items():
            if field.startswith('$'):
                continue
            fields.append(field)
            if isinstance(condition, dict) and any(op in condition for op in ('$gt', '$gte', '$lt', '$lte')):
                ranges.append(field)
            else:
                equality.append(field)
    unique_fields = tuple(sorted(set(fields)))
    score = len(set(equality)) * 2.0 + len(set(ranges))
    for candidate in indexes:
        if all(field in unique_fields for field in candidate):
            score += 3.0 + len(candidate)
    return PlanHint(index, unique_fields, tuple(sorted(set(equality))), tuple(sorted(set(ranges))), score)

# "QueryDNF/src/querydnf/io.py"
'''JSON input and output helpers used by the CLI.'''

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def load_json_arg(value: str) -> Any:
    path = Path(value)
    if path.exists():
        return json.loads(path.read_text(encoding='utf-8'))
    return json.loads(value)


def dumps_json(value: Any, *, pretty: bool = True) -> str:
    if pretty:
        return json.dumps(value, indent=2, sort_keys=True)
    return json.dumps(value, separators=(',', ':'), sort_keys=True)

# "QueryDNF/src/querydnf/cli.py"
'''Command-line interface for QueryDNF.'''

from __future__ import annotations

import argparse
import sys
from typing import Sequence

from querydnf.config import Settings
from querydnf.dnf_converter import convert
from querydnf.evaluator import matches
from querydnf.io import dumps_json, load_json_arg
from querydnf.optimizer import explain
from querydnf.parser import parse


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog='querydnf', description='Work with Mongo-like filters in DNF.')
    sub = parser.add_subparsers(dest='command', required=True)

    p_convert = sub.add_parser('convert', help='convert a query to DNF')
    p_convert.add_argument('query')

    p_parse = sub.add_parser('parse', help='extract conjunction products and clauses')
    p_parse.add_argument('query')

    p_explain = sub.add_parser('explain', help='summarize fields, clauses, and plan hints')
    p_explain.add_argument('query')

    p_eval = sub.add_parser('eval', help='evaluate a query against one document')
    p_eval.add_argument('query')
    p_eval.add_argument('document')
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    settings = Settings.from_env()
    try:
        if args.command == 'convert':
            result = convert(load_json_arg(args.query), settings=settings)
        elif args.command == 'parse':
            products, clauses = parse(load_json_arg(args.query))
            result = {'products': products, 'clauses': clauses}
        elif args.command == 'explain':
            result = explain(load_json_arg(args.query))
        elif args.command == 'eval':
            result = {'matches': matches(load_json_arg(args.query), load_json_arg(args.document))}
        else:
            raise AssertionError(args.command)
    except Exception as exc:
        print(f'querydnf: {exc}', file=sys.stderr)
        return 2
    print(dumps_json(result, pretty=settings.pretty_json))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

# "QueryDNF/tests/test_dnf_converter.py"
from querydnf.dnf_converter import convert


def test_convert_distributes_and_over_or() -> None:
    query = {'$and': [{'status': 'open'}, {'$or': [{'priority': {'$gte': 3}}, {'owner': 'alice'}]}]}
    assert convert(query) == {
        '$or': [
            {'$and': [{'status': 'open'}, {'priority': {'$gte': 3}}]},
            {'$and': [{'status': 'open'}, {'owner': 'alice'}]},
        ]
    }


def test_convert_implicit_and_with_multiple_fields() -> None:
    assert convert({'a': 1, 'b': 2}) == {'$or': [{'$and': [{'a': 1}, {'b': 2}]}]}


def test_not_inverts_simple_comparison() -> None:
    assert convert({'$not': {'age': {'$lt': 18}}}) == {'$or': [{'age': {'$gte': 18}}]}

# "QueryDNF/tests/test_parser_eval.py"
from querydnf.evaluator import matches
from querydnf.optimizer import choose_plan, explain
from querydnf.parser import parse


def test_parse_returns_products_and_flat_clauses() -> None:
    products, clauses = parse({'$or': [{'a': 1}, {'$and': [{'b': 2}, {'c': {'$gt': 3}}]}]})
    assert len(products) == 2
    assert clauses == [{'a': 1}, {'b': 2}, {'c': {'$gt': 3}}]


def test_matches_comparison_and_or() -> None:
    query = {'$or': [{'status': 'open'}, {'priority': {'$gte': 5}}]}
    assert matches(query, {'status': 'closed', 'priority': 7}) is True
    assert matches(query, {'status': 'closed', 'priority': 2}) is False


def test_choose_plan_prefers_indexed_equality_fields() -> None:
    plan = choose_plan({'tenant': 't1', 'status': 'open', 'created_at': {'$gte': 10}}, [('tenant', 'status')])
    assert plan.conjunction_index == 0
    assert 'tenant' in plan.equality_fields
    assert plan.score >= 7.0


def test_explain_shape() -> None:
    info = explain({'owner': 'alice', 'score': {'$gt': 10}})
    assert info['dnf_conjunctions'] == 1
    assert info['fields'] == ['owner', 'score']

