    assert convert({'$not': {'age': {'$lt': 18}}}) == {'$or': [{'age': {'$gte': 18}}]}

# "QueryDNF/tests/test_parser_eval.py"
from querydnf.evaluator import matches
from querydnf.optimizer import choose_plan, explain
from querydnf.parser import parse


def test_parse_returns_products_and_flat_clauses() -> None:
    products, clauses = parse({'$or': [{'a': 1}, {'$and': [{'b': 2}, {'c': {'$gt': 3}}]}]})
    assert len(products) == 2
    assert clauses == [{'a': 1}, {'b': 2}, {'c': {'$gt': 3}}]


def test_matches_comparison_and_or() -> None:
    query = {'$or': [{'status': 'open'}, {'priority': {'$gte': 5}}]}
    assert matches(query, {'status': 'closed', 'priority': 7}) is True
    assert matches(query, {'status': 'closed', 'priority': 2}) is False


def test_choose_plan_prefers_indexed_equality_fields() -> None:
    plan = choose_plan({'tenant': 't1', 'status': 'open', 'created_at': {'$gte': 10}}, [('tenant', 'status')])
    assert plan.conjunction_index == 0
    assert 'tenant' in plan.equality_fields
    assert plan.score >= 7.0


