from __future__ import annotations

from dataclasses import dataclass
from enum import StrEnum
from typing import Any

from listing_custom_fields.exceptions import InvalidPropertySheetError


class FieldType(StrEnum):
    TEXT = 'Text'
    TEXTLINE = 'TextLine'
    STRING = 'String'
    BOOLEAN = 'Boolean'
    DATE = 'Date'
    DATETIME = 'DateTime'
    INTEGER = 'Integer'
    INT = 'Int'
    FLOAT = 'Float'
    CHOICE = 'Choice'
    LIST = 'List'


SOLR_SUFFIX_BY_TYPE: dict[str, str | None] = {
    FieldType.TEXT: None,
    FieldType.TEXTLINE: '_string',
    FieldType.STRING: '_string',
    FieldType.BOOLEAN: '_bool',
    FieldType.DATE: '_date',
    FieldType.DATETIME: '_dt',
    FieldType.INTEGER: '_int',
    FieldType.INT: '_int',
    FieldType.FLOAT: '_float',
    FieldType.CHOICE: '_string',
    FieldType.LIST: '_strings',
}


@dataclass(frozen=True, slots=True)
class PropertyField:
    name: str
    title: str
    field_type: str
    description: str = ''
    required: bool = False
    indexed: bool = True

    @classmethod
    def from_mapping(cls, value: dict[str, Any]) -> 'PropertyField':
        try:
            name = str(value['name']).strip()
            title = str(value.get('title') or name).strip()
            field_type = str(value['type']).strip()
        except KeyError as exc:
            raise InvalidPropertySheetError(f'missing field attribute: {exc.args[0]}') from exc
        if not name:
            raise InvalidPropertySheetError('field name must not be empty')
        return cls(
            name=name,
            title=title,
            field_type=field_type,
            description=str(value.get('description', '')),
            required=bool(value.get('required', False)),
            indexed=bool(value.get('indexed', True)),
        )

    @property
    def solr_dynamic_name(self) -> str | None:
        suffix = SOLR_SUFFIX_BY_TYPE.get(self.field_type)
        if suffix is None or not self.indexed:
            return None
        safe_name = self.name.replace('-', '_').replace('.', '_')
        return f'property_{safe_name}{suffix}'

    def to_solr_schema(self, sheet_name: str, slot_name: str) -> dict[str, Any] | None:
        dynamic_name = self.solr_dynamic_name
        if dynamic_name is None:
            return None
        return {
            'name': dynamic_name,
            'title': self.title,
            'description': self.description,
            'type': self.field_type,
            'sheet': sheet_name,
            'slot': slot_name,
            'required': self.required,
        }


@dataclass(frozen=True, slots=True)
class PropertySheetDefinition:
    name: str
    slot: str
    fields: tuple[PropertyField, ...]

    @classmethod
    def from_mapping(cls, value: dict[str, Any]) -> 'PropertySheetDefinition':
        try:
            name = str(value['name']).strip()
            slot = str(value['slot']).strip()
            fields_raw = value['fields']
        except KeyError as exc:
            raise InvalidPropertySheetError(f'missing sheet attribute: {exc.args[0]}') from exc
        if not isinstance(fields_raw, list):
            raise InvalidPropertySheetError('fields must be a list')
        fields = tuple(PropertyField.from_mapping(item) for item in fields_raw)
        return cls(name=name, slot=slot, fields=fields)

    def get_solr_dynamic_field_schema(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for field in self.fields:
            schema = field.to_solr_schema(sheet_name=self.name, slot_name=self.slot)
            if schema is not None:
                result[schema['name']] = schema
        return result

