    def iter_files(self) -> Iterable[Path]:
        if not self:
            raise StorageUnavailableError(f'schema directory does not exist: {self.schema_dir}')
        return sorted(self.schema_dir.glob('*.json'))

    def _load(self) -> dict[str, PropertySheetDefinition]:
