from __future__ import annotations

from dataclasses import dataclass
from time import monotonic
from typing import Callable, Generic, TypeVar

T = TypeVar('T')


@dataclass(slots=True)
class TTLCache(Generic[T]):
    ttl_seconds: int
    _value: T | None = None
    _expires_at: float = 0.0

    def get(self, factory: Callable[[], T]) -> T:
        now = monotonic()
        if self.ttl_seconds <= 0 or self._value is None or now >= self._expires_at:
            self._value = factory()
            self._expires_at = now + self.ttl_seconds
        return self._value

    def clear(self) -> None:
        self._value = None
        self._expires_at = 0.0

# "Listing_Custom_Fields_API/src/listing_custom_fields/service.py"
from __future__ import annotations

from collections.abc import Callable
from pathlib import Path
from typing import Any

from listing_custom_fields.assignment import LISTING_TO_SLOTS
from listing_custom_fields.cache import TTLCache
from listing_custom_fields.storage import PropertySheetSchemaStorage

ListingPayload = dict[str, dict[str, dict[str, Any]]]
SlotProvider = Callable[[], tuple[str, ...]]


class ListingCustomFieldsService:
    '''Collect Solr-indexable custom fields grouped by listing name.'''

    def __init__(
        self,
        schema_dir: Path | str,
        listing_to_slots: dict[str, SlotProvider] | None = None,
        cache_ttl_seconds: int = 0,
    ):
        self.schema_dir = Path(schema_dir)
        self.listing_to_slots = listing_to_slots or LISTING_TO_SLOTS
        self.cache = TTLCache[ListingPayload](ttl_seconds=cache_ttl_seconds)

    def get_custom_fields(self) -> ListingPayload:
        return self.cache.get(self._build_payload)

    def refresh(self) -> ListingPayload:
        self.cache.clear()
        return self.get_custom_fields()

    def _build_payload(self) -> ListingPayload:
        solr_fields: ListingPayload = {}
        storage = PropertySheetSchemaStorage(self.schema_dir)
        if not storage:
            return solr_fields

        for listing_name, slot_provider in self.listing_to_slots.items():
            fields_by_listing: dict[str, Any] = {}
            for slot_name in slot_provider():
                definition = storage.query(slot_name)
                if definition is not None:
                    fields_by_listing.update(definition.get_solr_dynamic_field_schema())
            if fields_by_listing:
                solr_fields[listing_name] = {'properties': fields_by_listing}
        return solr_fields

