from fastapi import FastAPI, HTTPException

from listing_custom_fields.config import Settings, get_settings
from listing_custom_fields.exceptions import ListingFieldsError
from listing_custom_fields.service import ListingCustomFieldsService


def create_app(settings: Settings | None = None) -> FastAPI:
    settings = settings or get_settings()
    app = FastAPI(
        title=settings.service_title,
        version=settings.service_version,
        docs_url='/docs' if settings.enable_docs else None,
        redoc_url='/redoc' if settings.enable_docs else None,
    )
    service = ListingCustomFieldsService(
        schema_dir=settings.schema_dir,
        cache_ttl_seconds=settings.cache_ttl_seconds,
    )

    @app.get('/healthz')
    def healthz() -> dict[str, str]:
        return {'status': 'ok'}

    @app.get('/@listing-custom-fields')
    def listing_custom_fields() -> dict[str, object]:
        try:
            return service.get_custom_fields()
        except ListingFieldsError as exc:
            raise HTTPException(status_code=500, detail=str(exc)) from exc

    @app.post('/-/refresh')
    def refresh() -> dict[str, object]:
        try:
            return service.refresh()
        except ListingFieldsError as exc:
            raise HTTPException(status_code=500, detail=str(exc)) from exc

    return app

