def parse_stack_record(record: str) -> list[StackFrame]:
    frames: list[StackFrame] = []
    for raw_frame in record.split('^'):
        raw_frame = raw_frame.strip()
        if not raw_frame:
            continue
        parts = raw_frame.split('|')
        if len(parts) < 2:
            raise StackParseError(f'Malformed stack frame: {raw_frame!r}')
        pc = parts[0].strip()
        library_path = parts[1].strip()
        symbol_hint = parts[2].strip() if len(parts) > 2 else ''
        if not pc or not library_path:
            raise StackParseError(f'Malformed stack frame: {raw_frame!r}')
        frames.append(StackFrame(pc=pc, library_path=library_path, symbol_hint=symbol_hint))
    return frames

