from __future__ import annotations

import logging
import os
from pathlib import Path
from typing import Any

from shellbot.settings import BotSettings


class Context:
    '''Runtime context shared by the engine, adapters, localization, and commands.'''

    def __init__(self, settings: dict[str, Any] | BotSettings | None = None) -> None:
        if isinstance(settings, BotSettings):
            self.settings = settings
        else:
            self.settings = BotSettings.from_mapping(settings)
        self.root = Path(os.getcwd())
        self.logger = logging.getLogger('shellbot')

    @classmethod
    def from_file(cls, path: str | Path) -> 'Context':
        return cls(BotSettings.from_yaml(path))

    @staticmethod
    def set_logger(level: str | int = 'INFO') -> None:
        numeric = logging.getLevelName(level) if isinstance(level, str) else level
        if isinstance(numeric, str):
            numeric = logging.INFO
        logging.basicConfig(
            level=numeric,
            format='%(asctime)s %(levelname)s [%(name)s] %(message)s',
        )

    def get(self, dotted_path: str, default: Any = None) -> Any:
        current: Any = self.settings.to_dict()
        for part in dotted_path.split('.'):
            if isinstance(current, dict) and part in current:
                current = current[part]
            else:
                return default
        return current

    def require(self, dotted_path: str) -> Any:
        sentinel = object()
        value = self.get(dotted_path, sentinel)
        if value is sentinel:
            raise KeyError(f'missing required setting: {dotted_path}')
        return value

    @property
    def localized(self) -> dict[str, str]:
        return dict(self.settings.localized)

# "Shellbot/src/shellbot/i18n.py"
from __future__ import annotations

from threading import RLock
from typing import Any

from shellbot.context import Context


class Localization:
    '''String localization registry backed by Context.settings.localized.'''

    def __init__(self, context: Context | None = None) -> None:
        self.context = context
        self.actual_strings: dict[str, str] = {}
        self._lock = RLock()

    def set_context(self, context: Context | None) -> None:
        with self._lock:
            self.context = context
            self.actual_strings = {}

    def translate(self, text: str, **variables: Any) -> str:
        with self._lock:
            catalog = self.context.localized if self.context is not None else {}
            value = catalog.get(text, text)
            if variables:
                try:
                    value = value.format(**variables)
                except KeyError as exc:
                    missing = exc.args[0]
                    raise KeyError(f'missing localization variable {missing!r} for {text!r}') from exc
            self.actual_strings[text] = value
            return value

    def _(self, text: str, **variables: Any) -> str:
        return self.translate(text, **variables)


localization = Localization()


def _(text: str, **variables: Any) -> str:
    return localization.translate(text, **variables)

