# "Shellbot/src/shellbot/adapters/base.py"
from __future__ import annotations

from abc import ABC, abstractmethod
from collections import deque
from typing import Any

from shellbot.models import Message, Response, User


class Adapter(ABC):
    @abstractmethod
    async def parse(self, payload: dict[str, Any]) -> Message:
        raise NotImplementedError

    @abstractmethod
    async def send(self, response: Response) -> None:
        raise NotImplementedError


class WebhookAdapter(Adapter):
    async def parse(self, payload: dict[str, Any]) -> Message:
        text = str(payload.get('text', '')).strip()
        if not text:
            raise ValueError('payload does not contain message text')
        user_payload = payload.get('user') or {}
        if isinstance(user_payload, str):
            user_payload = {'id': user_payload}
        user = User(
            id=str(user_payload.get('id') or user_payload.get('email') or 'anonymous'),
            display_name=user_payload.get('display_name') or user_payload.get('name'),
            email=user_payload.get('email'),
        )
        return Message(text=text, user=user, room=payload.get('room'), raw=payload)

    async def send(self, response: Response) -> None:
        return None


class InMemoryAdapter(WebhookAdapter):
    def __init__(self) -> None:
        self.sent: deque[Response] = deque()

    async def send(self, response: Response) -> None:
        self.sent.append(response)

# "Shellbot/src/shellbot/engine.py"
from __future__ import annotations

import logging
from typing import Any

from shellbot.adapters import Adapter, WebhookAdapter
from shellbot.commands import CommandRegistry, build_default_registry
from shellbot.context import Context
from shellbot.i18n import localization
from shellbot.models import EventRecord, Message, Response
from shellbot.storage import JsonlEventStore


class Engine:
    '''Coordinates adapters, command dispatch, localization, and event persistence.'''

    def __init__(
        self,
        context: Context | None = None,
        registry: CommandRegistry | None = None,
        adapter: Adapter | None = None,
        store: JsonlEventStore | None = None,
    ) -> None:
        self.context = context or Context()
        localization.set_context(self.context)
        self.registry = registry or build_default_registry(self.context.settings.commands.prefix)
        self.adapter = adapter or WebhookAdapter()
        self.store = store or JsonlEventStore(self.context.settings.storage.path)
        self.logger = logging.getLogger('shellbot.engine')

    async def handle_payload(self, payload: dict[str, Any]) -> Response | None:
        message = await self.adapter.parse(payload)
        return await self.handle_message(message)

    async def handle_message(self, message: Message) -> Response | None:
        self.store.append(EventRecord(direction='inbound', message=message))
        self.logger.info('received message', extra={'message_id': message.id})
        response = self.registry.dispatch(message)
        if response is None:
            return None
        await self.adapter.send(response)
        self.store.append(EventRecord(direction='outbound', response=response))
        return response

    def health(self) -> dict[str, str]:
        return {'status': 'ok', 'space': self.context.settings.space.title}

# "Shellbot/src/shellbot/web.py"
from __future__ import annotations

from typing import Any

from fastapi import FastAPI, HTTPException, Request

from shellbot.engine import Engine


def create_app(engine: Engine | None = None) -> FastAPI:
    bot = engine or Engine()
    app = FastAPI(title='Shellbot', version='0.4.0')

    @app.get('/health')
    async def health() -> dict[str, str]:
        return bot.health()

    @app.post(bot.context.settings.server.hook)
    async def webhook(request: Request) -> dict[str, Any]:
        try:
            payload = await request.json()
            if not isinstance(payload, dict):
                raise ValueError('webhook payload must be a JSON object')
            response = await bot.handle_payload(payload)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        if response is None:
            return {'handled': False}
        return {'handled': True, 'response': response.model_dump(mode='json')}

    return app

