# "Shellbot/src/shellbot/commands.py"
from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Iterable

from shellbot.i18n import _
from shellbot.models import Message, Response

CommandHandler = Callable[[Message, list[str]], Response]


@dataclass(frozen=True)
class Command:
    name: str
    help_text: str
    handler: CommandHandler
    aliases: tuple[str, ...] = ()


class CommandRegistry:
    def __init__(self, prefix: str = '!') -> None:
        self.prefix = prefix
        self._commands: dict[str, Command] = {}
        self._aliases: dict[str, str] = {}

    def register(self, command: Command) -> None:
        key = command.name.lower()
        if key in self._commands:
            raise ValueError(f'command already registered: {command.name}')
        self._commands[key] = command
        for alias in command.aliases:
            self._aliases[alias.lower()] = key

    def command(self, name: str, help_text: str, aliases: Iterable[str] = ()) -> Callable[[CommandHandler], CommandHandler]:
        def decorator(func: CommandHandler) -> CommandHandler:
            self.register(Command(name=name, help_text=help_text, aliases=tuple(aliases), handler=func))
            return func
        return decorator

    def resolve(self, token: str) -> Command | None:
        normalized = token.lower()
        normalized = self._aliases.get(normalized, normalized)
        return self._commands.get(normalized)

    def dispatch(self, message: Message) -> Response | None:
        text = message.text.strip()
        if not text.startswith(self.prefix):
            return None
        parts = text[len(self.prefix):].split()
        if not parts:
            return Response(text=_('Empty command. Try help.'))
        command = self.resolve(parts[0])
        if command is None:
            return Response(text=_('Unknown command: {name}', name=parts[0]), visibility='private')
        return command.handler(message, parts[1:])

    def help_response(self) -> Response:
        lines = [_('help.header')]
        for command in sorted(self._commands.values(), key=lambda item: item.name):
            lines.append(f'{self.prefix}{command.name} - {command.help_text}')
        return Response(text='\n'.join(lines), visibility='private')


def build_default_registry(prefix: str = '!') -> CommandRegistry:
    registry = CommandRegistry(prefix=prefix)

    @registry.command('ping', _('Check whether the bot is alive'), aliases=('p',))
    def ping(message: Message, args: list[str]) -> Response:
        return Response(text=_('pong'))

    @registry.command('echo', _('Echo the supplied text'))
    def echo(message: Message, args: list[str]) -> Response:
        if not args:
            return Response(text=_('Nothing to echo.'), visibility='private')
        return Response(text=' '.join(args))

    @registry.command('help', _('Show this help message'), aliases=('?',))
    def help_command(message: Message, args: list[str]) -> Response:
        return registry.help_response()

    return registry

