from __future__ import annotations

import json
from pathlib import Path
from threading import RLock
from typing import Iterable

from shellbot.models import EventRecord


class JsonlEventStore:
    def __init__(self, path: str | Path) -> None:
        self.path = Path(path)
        self._lock = RLock()

    def append(self, record: EventRecord) -> None:
        with self._lock:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            with self.path.open('a', encoding='utf-8') as stream:
                stream.write(record.model_dump_json() + '\n')

    def read(self) -> list[EventRecord]:
        if not self.path.exists():
            return []
        records: list[EventRecord] = []
        with self.path.open('r', encoding='utf-8') as stream:
            for line_number, line in enumerate(stream, start=1):
                stripped = line.strip()
                if not stripped:
                    continue
                try:
                    records.append(EventRecord.model_validate_json(stripped))
                except Exception as exc:
                    raise ValueError(f'invalid event record at {self.path}:{line_number}') from exc
        return records

    def extend(self, records: Iterable[EventRecord]) -> None:
        for record in records:
            self.append(record)

