import click
import uvicorn

from shellbot.config import load_context
from shellbot.context import Context
from shellbot.engine import Engine
from shellbot.models import Message, User


@click.group()
def main() -> None:
    pass


@main.command()
@click.option('--config', 'config_path', type=click.Path(exists=True), default=None)
def validate(config_path: str | None) -> None:
    context = load_context(config_path)
    click.echo(json.dumps(context.settings.to_dict(), indent=2, sort_keys=True))


@main.command()
@click.option('--config', 'config_path', type=click.Path(exists=True), default=None)
def serve(config_path: str | None) -> None:
    context = load_context(config_path)
    Context.set_logger(context.settings.logging.level)
    uvicorn.run(
        'shellbot.web:create_app',
        factory=True,
        host=context.settings.server.binding,
        port=context.settings.server.port,
    )


@main.command()
@click.argument('text', nargs=-1, required=True)
@click.option('--config', 'config_path', type=click.Path(exists=True), default=None)
@click.option('--user', default='cli')
def run(config_path: str | None, text: tuple[str, ...], user: str) -> None:
    context = load_context(config_path)
    engine = Engine(context=context)
    message = Message(text=' '.join(text), user=User(id=user, display_name=user))
    response = asyncio.run(engine.handle_message(message))
    if response is not None:
        click.echo(response.text)

