from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml
from pydantic import BaseModel, Field, HttpUrl, field_validator


class ServerSettings(BaseModel):
    url: HttpUrl | str = 'http://localhost:8080'
    hook: str = '/hook'
    binding: str = '127.0.0.1'
    port: int = Field(default=8080, ge=1, le=65535)

    @field_validator('hook')
    @classmethod
    def normalize_hook(cls, value: str) -> str:
        if not value.startswith('/'):
            return '/' + value
        return value


class SpaceSettings(BaseModel):
    title: str = 'shellbot'
    participants: list[str] = Field(default_factory=list)


class CommandSettings(BaseModel):
    prefix: str = '!'
    aliases: dict[str, str] = Field(default_factory=dict)


class LoggingSettings(BaseModel):
    level: str = 'INFO'
    json: bool = False


class StorageSettings(BaseModel):
    path: str = '.shellbot-events.jsonl'


class BotSettings(BaseModel):
    server: ServerSettings = Field(default_factory=ServerSettings)
    space: SpaceSettings = Field(default_factory=SpaceSettings)
    commands: CommandSettings = Field(default_factory=CommandSettings)
    logging: LoggingSettings = Field(default_factory=LoggingSettings)
    storage: StorageSettings = Field(default_factory=StorageSettings)
    localized: dict[str, str] = Field(default_factory=dict)
    metadata: dict[str, Any] = Field(default_factory=dict)

    @classmethod
    def from_mapping(cls, mapping: dict[str, Any] | None) -> 'BotSettings':
        return cls.model_validate(mapping or {})

    @classmethod
    def from_yaml(cls, path: str | Path) -> 'BotSettings':
        location = Path(path)
        if not location.exists():
            raise FileNotFoundError(f'configuration file not found: {location}')
        with location.open('r', encoding='utf-8') as stream:
            data = yaml.safe_load(stream) or {}
        if not isinstance(data, dict):
            raise ValueError('configuration root must be a mapping')
        return cls.from_mapping(data)

    def to_dict(self) -> dict[str, Any]:
        return self.model_dump(mode='json')

# "Shellbot/src/shellbot/context.py"
from __future__ import annotations

import logging
import os
from pathlib import Path
from typing import Any

from shellbot.settings import BotSettings


class Context:
    '''Runtime context shared by the engine, adapters, localization, and commands.'''

    def __init__(self, settings: dict[str, Any] | BotSettings | None = None) -> None:
        if isinstance(settings, BotSettings):
            self.settings = settings
        else:
            self.settings = BotSettings.from_mapping(settings)
        self.root = Path(os.getcwd())
        self.logger = logging.getLogger('shellbot')

    @classmethod
    def from_file(cls, path: str | Path) -> 'Context':
        return cls(BotSettings.from_yaml(path))

    @staticmethod
    def set_logger(level: str | int = 'INFO') -> None:
        numeric = logging.getLevelName(level) if isinstance(level, str) else level
        if isinstance(numeric, str):
            numeric = logging.INFO
        logging.basicConfig(
            level=numeric,
            format='%(asctime)s %(levelname)s [%(name)s] %(message)s',
        )

    def get(self, dotted_path: str, default: Any = None) -> Any:
        current: Any = self.settings.to_dict()
        for part in dotted_path.split('.'):
            if isinstance(current, dict) and part in current:
                current = current[part]
            else:
                return default
        return current

    def require(self, dotted_path: str) -> Any:
        sentinel = object()
        value = self.get(dotted_path, sentinel)
        if value is sentinel:
            raise KeyError(f'missing required setting: {dotted_path}')
        return value

    @property
    def localized(self) -> dict[str, str]:
        return dict(self.settings.localized)

# "Shellbot/src/shellbot/i18n.py"
from __future__ import annotations

from threading import RLock
from typing import Any

from shellbot.context import Context


class Localization:
    '''String localization registry backed by Context.settings.localized.'''

    def __init__(self, context: Context | None = None) -> None:
        self.context = context
        self.actual_strings: dict[str, str] = {}
        self._lock = RLock()

    def set_context(self, context: Context | None) -> None:
        with self._lock:
            self.context = context
            self.actual_strings = {}

    def translate(self, text: str, **variables: Any) -> str:
        with self._lock:
            catalog = self.context.localized if self.context is not None else {}
            value = catalog.get(text, text)
            if variables:
                try:
                    value = value.format(**variables)
                except KeyError as exc:
                    missing = exc.args[0]
                    raise KeyError(f'missing localization variable {missing!r} for {text!r}') from exc
            self.actual_strings[text] = value
            return value

    def _(self, text: str, **variables: Any) -> str:
        return self.translate(text, **variables)


localization = Localization()


def _(text: str, **variables: Any) -> str:
    return localization.translate(text, **variables)

