from __future__ import annotations

from pathlib import Path
from typing import Any

import h5py
import numpy as np

from sofa_acoustics.core.database import AcousticDatabase, MetadataNode


def _write_metadata(group: h5py.Group, values: dict[str, Any]) -> None:
    for key, value in values.items():
        if isinstance(value, dict):
            child = group.require_group(key)
            _write_metadata(child, value)
        else:
            group.attrs[key] = value


def _read_metadata(group: h5py.Group) -> dict[str, Any]:
    values: dict[str, Any] = {key: _decode(value) for key, value in group.attrs.items()}
    for key, child in group.items():
        if isinstance(child, h5py.Group) and key != 'DataArrays':
            values[key] = _read_metadata(child)
    return values


def _decode(value: Any) -> Any:
    if isinstance(value, bytes):
        return value.decode('utf8')
    if isinstance(value, np.generic):
        return value.item()
    return value


def write_database(path: Path, database: AcousticDatabase, overwrite: bool = False) -> None:
    if path.exists() and not overwrite:
        raise FileExistsError(f'{path} already exists; pass overwrite=True to replace it')
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = 'w' if overwrite else 'x'
    with h5py.File(path, mode) as h5:
        _write_metadata(h5, database.to_metadata_dict())
        objects = h5.require_group('Objects')
        for name, spec in database.objects.items():
            group = objects.require_group(name)
            group.attrs['count'] = spec.count
            group.attrs['fixed'] = np.array(spec.fixed, dtype=h5py.string_dtype())
            group.attrs['variances'] = np.array(spec.variances, dtype=h5py.string_dtype())
        arrays = h5.require_group('DataArrays')
        for name, value in database.data.items():
            arrays.create_dataset(name, data=value, compression='gzip' if value.ndim > 1 else None)


def read_database(path: Path) -> AcousticDatabase:
    if not path.exists():
        raise FileNotFoundError(path)
    with h5py.File(path, 'r') as h5:
        db = AcousticDatabase(metadata=MetadataNode.from_dict(_read_metadata(h5)))
        if 'Objects' in h5:
            for name, group in h5['Objects'].items():
                fixed = [_decode(x) for x in group.attrs.get('fixed', [])]
                variances = [_decode(x) for x in group.attrs.get('variances', [])]
                db.set_object(name, int(group.attrs.get('count', 1)), fixed, variances)
        if 'DataArrays' in h5:
            for name, dataset in h5['DataArrays'].items():
                db.data[name] = np.asarray(dataset)
        return db

# "SOFAcoustics/src/sofa_acoustics/processing/ir.py"
from __future__ import annotations

import numpy as np


def normalize_ir(ir: np.ndarray, peak: float = 0.99) -> np.ndarray:
    values = np.asarray(ir, dtype=np.float64)
    maximum = float(np.max(np.abs(values))) if values.size else 0.0
    if maximum == 0.0:
        return values.copy()
    return values * (peak / maximum)


def convolve_signal(signal: np.ndarray, ir: np.ndarray) -> np.ndarray:
    mono = np.asarray(signal, dtype=np.float64).reshape(-1)
    response = np.asarray(ir, dtype=np.float64)
    if response.ndim == 1:
        return np.convolve(mono, response)
    if response.ndim != 2:
        raise ValueError('Impulse response must be one-dimensional or channel x sample')
    rendered = [np.convolve(mono, channel) for channel in response]
    return np.stack(rendered, axis=0)


def render_binaural(signal: np.ndarray, ir_bank: np.ndarray, measurement_index: int = 0) -> np.ndarray:
    bank = np.asarray(ir_bank, dtype=np.float64)
    if bank.ndim != 3:
        raise ValueError('IR bank must have shape measurement x receiver x sample')
    if measurement_index < 0 or measurement_index >= bank.shape[0]:
        raise IndexError(f'measurement_index {measurement_index} out of range for {bank.shape[0]} measurements')
    if bank.shape[1] != 2:
        raise ValueError('Binaural rendering requires exactly two receiver channels')
    return convolve_signal(signal, bank[measurement_index])

