from __future__ import annotations

from pathlib import Path

import numpy as np
def _load_wav_mono(path: Path) -> np.ndarray:
    import wave
    with wave.open(str(path), 'rb') as wav:
        frames = wav.readframes(wav.getnframes())
        channels = wav.getnchannels()
        width = wav.getsampwidth()
    if width != 2:
        raise ValueError('Only 16-bit PCM WAV input is supported by the lightweight renderer')
    data = np.frombuffer(frames, dtype='<i2').astype(np.float64) / 32768.0
    if channels > 1:
        data = data.reshape(-1, channels).mean(axis=1)
    return data

import typer
from rich.console import Console

from sofa_acoustics.conventions import available_conventions, get_convention
from sofa_acoustics.io.sofa import read_database, write_database
from sofa_acoustics.processing.ir import render_binaural
from sofa_acoustics.tracking import JsonlTracker

app = typer.Typer(help='Validate and process SOFA-like spatial audio datasets.')
console = Console()


@app.command()
def conventions() -> None:
    for name in available_conventions():
        console.print(name)


@app.command()
def init(path: Path, convention: str = 'MultiSpeakerBRIR', measurements: int = 1, samples: int = 256, overwrite: bool = False) -> None:
    conv = get_convention(convention)
    db = conv.create_database()
    db.add_array('IR', np.zeros((measurements, int(db.objects['Receiver'].count), samples), dtype=np.float32))
    db.add_array('SamplingRate', np.array([48000.0], dtype=np.float64))
    write_database(path, db, overwrite=overwrite)
    console.print(f'Wrote {path}')


@app.command()
def validate(path: Path, convention: str | None = None, tracker: Path | None = None) -> None:
    db = read_database(path)
    convention_name = convention or str(db.Data.get('Convention', 'MultiSpeakerBRIR'))
    conv = get_convention(convention_name)
    report = conv.validate(db)
    for issue in report.issues:
        console.print(issue.format(), style='red' if issue.severity == 'error' else 'yellow')
    if tracker:
        JsonlTracker(tracker).log('validation', path=str(path), convention=conv.name, ok=report.ok, issues=len(report.issues))
    if not report.ok:
        raise typer.Exit(code=2)
    console.print('Validation passed', style='green')


@app.command()
def render(dataset: Path, input_wav: Path, output_npy: Path, measurement_index: int = 0) -> None:
    db = read_database(dataset)
    if 'IR' not in db.data:
        raise typer.BadParameter('Dataset does not contain an IR array')
    signal = _load_wav_mono(input_wav)
    rendered = render_binaural(signal, db.data['IR'], measurement_index=measurement_index)
    output_npy.parent.mkdir(parents=True, exist_ok=True)
    np.save(output_npy, rendered)
    console.print(f'Wrote rendered signal to {output_npy}')

