from __future__ import annotations

from pathlib import Path
from tempfile import NamedTemporaryFile

from sofa_acoustics.conventions import available_conventions, get_convention
from sofa_acoustics.io.sofa import read_database


def create_app():
    try:
        from fastapi import FastAPI, File, UploadFile
    except ImportError as exc:
        raise RuntimeError('Install sofa-acoustics[server] to use the HTTP service') from exc

    app = FastAPI(title='SOFAcoustics Validation API', version='0.3.0')

    @app.get('/conventions')
    def list_conventions() -> dict[str, list[str]]:
        return {'conventions': available_conventions()}

    @app.post('/validate/{convention_name}')
    async def validate_upload(convention_name: str, file: UploadFile = File(...)) -> dict[str, object]:
        conv = get_convention(convention_name)
        suffix = Path(file.filename or 'upload.h5').suffix or '.h5'
        with NamedTemporaryFile(suffix=suffix, delete=True) as tmp:
            tmp.write(await file.read())
            tmp.flush()
            db = read_database(Path(tmp.name))
        report = conv.validate(db)
        return {'ok': report.ok, 'issues': [issue.format() for issue in report.issues]}

    return app

app = create_app()

