from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal

Severity = Literal['error', 'warning']


@dataclass(frozen=True)
class ValidationIssue:
    severity: Severity
    message: str
    path: str | None = None

    def format(self) -> str:
        location = f' at {self.path}' if self.path else ''
        return f'{self.severity.upper()}{location}: {self.message}'


@dataclass
class ValidationReport:
    convention: str
    issues: list[ValidationIssue] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not any(issue.severity == 'error' for issue in self.issues)

    def add_error(self, message: str, path: str | None = None) -> None:
        self.issues.append(ValidationIssue('error', message, path))

    def add_warning(self, message: str, path: str | None = None) -> None:
        self.issues.append(ValidationIssue('warning', message, path))

    def raise_for_errors(self) -> None:
        if not self.ok:
            details = '\n'.join(issue.format() for issue in self.issues)
            raise ValueError(f'Validation failed for {self.convention}:\n{details}')

# "SOFAcoustics/src/sofa_acoustics/core/database.py"
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Iterable

import numpy as np


class MetadataNode:
    '''Attribute-style metadata tree used by convention code.'''

    def __init__(self, **attrs: Any) -> None:
        object.__setattr__(self, '_attrs', {})
        for key, value in attrs.items():
            setattr(self, key, value)

    def __getattr__(self, item: str) -> Any:
        node = MetadataNode()
        self._attrs[item] = node
        return node

    def __setattr__(self, key: str, value: Any) -> None:
        if key.startswith('_'):
            object.__setattr__(self, key, value)
        else:
            self._attrs[key] = value

    def to_dict(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        for key, value in self._attrs.items():
            if isinstance(value, MetadataNode):
                out[key] = value.to_dict()
            elif isinstance(value, np.ndarray):
                out[key] = value.tolist()
            else:
                out[key] = value
        return out

    @classmethod
    def from_dict(cls, values: dict[str, Any]) -> 'MetadataNode':
        node = cls()
        for key, value in values.items():
            setattr(node, key, cls.from_dict(value) if isinstance(value, dict) else value)
        return node

    def get(self, key: str, default: Any = None) -> Any:
        return self._attrs.get(key, default)


@dataclass
class ObjectSpec:
    name: str
    count: int = 1
    fixed: list[str] = field(default_factory=list)
    variances: list[str] = field(default_factory=list)

    def dimensions(self) -> list[str]:
        return [*self.fixed, *self.variances]


@dataclass
class AcousticDatabase:
    metadata: MetadataNode = field(default_factory=MetadataNode)
    objects: dict[str, ObjectSpec] = field(default_factory=dict)
    data: dict[str, np.ndarray] = field(default_factory=dict)

    def __post_init__(self) -> None:
        for group in ('Data', 'Room', 'Listener', 'Emitter', 'Receiver'):
            getattr(self.metadata, group)

    def __getattr__(self, item: str) -> Any:
        return getattr(self.metadata, item)

    def set_object(self, name: str, count: int, fixed: Iterable[str] = (), variances: Iterable[str] = ()) -> None:
        self.objects[name] = ObjectSpec(name=name, count=count, fixed=list(fixed), variances=list(variances))

    def add_array(self, name: str, value: np.ndarray) -> None:
        if value.size == 0:
            raise ValueError(f'Array {name} must not be empty')
        self.data[name] = np.asarray(value)

    def to_metadata_dict(self) -> dict[str, Any]:
        return self.metadata.to_dict()

# "SOFAcoustics/src/sofa_acoustics/conventions/base.py"
from __future__ import annotations

from collections.abc import Callable
from typing import ClassVar

from sofa_acoustics.core.database import AcousticDatabase
from sofa_acoustics.core.validation import ValidationReport

Condition = Callable[[str, list[str], list[str], int], bool]


class BaseConvention:
    name: ClassVar[str] = 'BaseConvention'
    version: ClassVar[str] = '0.1'

    def __init__(self) -> None:
        self.default_objects: dict[str, dict[str, object]] = {
            'Listener': {'count': 1, 'fixed': ['Position'], 'variances': []},
            'Emitter': {'count': 1, 'fixed': ['Position'], 'variances': []},
            'Receiver': {'count': 1, 'fixed': ['Position'], 'variances': []},
        }
        self.required_arrays: dict[str, tuple[int | None, ...]] = {}
        self.conditions: dict[str, Condition] = {}

    def create_database(self) -> AcousticDatabase:
        db = AcousticDatabase()
        for name, spec in self.default_objects.items():
            db.set_object(
                name,
                int(spec.get('count', 1)),
                spec.get('fixed', []),
                spec.get('variances', []),
            )
        self.add_metadata(db)
        return db

    def add_metadata(self, database: AcousticDatabase) -> None:
        database.Data.Convention = self.name
        database.Data.ConventionVersion = self.version

    def validate(self, database: AcousticDatabase) -> ValidationReport:
        report = ValidationReport(self.name)
        for object_name, spec in database.objects.items():
            for label, condition in self.conditions.items():
                if not condition(object_name, spec.fixed, spec.variances, spec.count):
                    report.add_error(label, path=f'objects.{object_name}')
        for array_name, expected in self.required_arrays.items():
            if array_name not in database.data:
                report.add_error(f'missing required data array {array_name}', path=f'data.{array_name}')
                continue
            actual = database.data[array_name].shape
            if len(actual) != len(expected):
                report.add_error(f'{array_name} rank {len(actual)} does not match expected rank {len(expected)}', path=f'data.{array_name}')
                continue
            for index, (actual_dim, expected_dim) in enumerate(zip(actual, expected, strict=True)):
                if expected_dim is not None and actual_dim != expected_dim:
                    report.add_error(f'{array_name} dimension {index} is {actual_dim}, expected {expected_dim}', path=f'data.{array_name}')
        return report

