from __future__ import annotations

from sofa_acoustics.conventions.base import BaseConvention
from sofa_acoustics.core.database import AcousticDatabase
from sofa_acoustics.core.validation import ValidationReport


class SimpleFreeFieldHRIR(BaseConvention):
    name = 'SimpleFreeFieldHRIR'
    version = '0.3'

    def __init__(self) -> None:
        super().__init__()
        self.default_objects['Listener']['fixed'] = ['Position', 'View', 'Up']
        self.default_objects['Emitter']['fixed'] = ['Position']
        self.default_objects['Receiver']['count'] = 2
        self.default_objects['Receiver']['fixed'] = ['Position']
        self.required_arrays = {'IR': (None, 2, None), 'SamplingRate': (1,)}
        self.conditions['must have at least one Emitter'] = lambda name, fixed, variances, count: name != 'Emitter' or count >= 1
        self.conditions['must have Listener Position'] = lambda name, fixed, variances, count: name != 'Listener' or 'Position' in fixed + variances

    def add_metadata(self, database: AcousticDatabase) -> None:
        super().add_metadata(database)
        database.Data.Type = 'FIR'
        database.Room.Type = 'free field'

    def validate(self, database: AcousticDatabase) -> ValidationReport:
        report = super().validate(database)
        room_type = database.Room.get('Type')
        if room_type not in ('free field', 'reverberant'):
            report.add_warning(f'unusual Room.Type {room_type!r}', path='Room.Type')
        return report

