from sofa_acoustics.conventions.simple_free_field_hrir import SimpleFreeFieldHRIR
from sofa_acoustics.core.database import AcousticDatabase


class MultiSpeakerBRIR(SimpleFreeFieldHRIR):
    name = 'MultiSpeakerBRIR'
    version = '0.3'

    def __init__(self) -> None:
