from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd

UINT32 = float(2**32)


def load_settings(session_path: Path) -> dict[str, Any]:
    raw_dir = Path(session_path) / 'raw_behavior_data'
    candidates = [raw_dir / 'settings.json', raw_dir / '_iblrig_taskSettings.raw.json']
    for path in candidates:
        if path.exists():
            return json.loads(path.read_text(encoding='utf8'))
    return {}


def load_data(session_path: Path) -> list[dict[str, Any]]:
    raw_dir = Path(session_path) / 'raw_behavior_data'
    candidates = [raw_dir / 'trials.jsonl', raw_dir / '_iblrig_taskData.raw.jsonable']
    for path in candidates:
        if path.exists():
            lines = [line for line in path.read_text(encoding='utf8').splitlines() if line.strip()]
            return [json.loads(line) for line in lines]
    json_path = raw_dir / 'trials.json'
    if json_path.exists():
        data = json.loads(json_path.read_text(encoding='utf8'))
        if isinstance(data, list):
            return data
    raise FileNotFoundError(f'no trial data found under {raw_dir}')


def read_ssv(path: Path) -> pd.DataFrame:
    if not path.exists():
        raise FileNotFoundError(path)
    return pd.read_csv(path, sep=r'\s+', engine='python', comment='#')


def repair_monotonic_clock(values: np.ndarray) -> np.ndarray:
    ts = np.asarray(values, dtype=float).copy()
    if ts.size == 0:
        return ts
    if ts.size > 3 and ts[0] > np.nanmedian(ts[1:]) * 10:
        ts = ts[1:]
    repaired = ts.copy()
    offset = 0.0
    for i in range(1, repaired.size):
        if repaired[i] + offset <= repaired[i - 1]:
            if repaired[i - 1] - (repaired[i] + offset) > UINT32 / 2:
                offset += UINT32
            elif i + 1 < repaired.size and repaired[i + 1] > repaired[i - 1]:
                repaired[i], repaired[i - 1] = repaired[i - 1], repaired[i]
                continue
        repaired[i] += offset
    order = np.argsort(repaired, kind='mergesort')
    repaired = repaired[order]
    _, unique_idx = np.unique(repaired, return_index=True)
    return repaired[np.sort(unique_idx)]


def _load_encoder_file(path: Path) -> pd.DataFrame:
    df = read_ssv(path)
    if 're_ts' not in df.columns:
        first = df.columns[0]
        df = df.rename(columns={first: 're_ts'})
    repaired = repair_monotonic_clock(df['re_ts'].to_numpy())
    df = df.iloc[: repaired.size].copy()
    df['re_ts'] = repaired
    return df.reset_index(drop=True)


def load_encoder_positions(session_path: Path, settings: dict[str, Any] | None = None) -> pd.DataFrame:
    raw_dir = Path(session_path) / 'raw_behavior_data'
    path = next(raw_dir.glob('_iblrig_encoderPositions.raw*.ssv'), None)
    if path is None:
        return pd.DataFrame({'re_ts': np.array([], dtype=float), 'position': np.array([], dtype=float)})
    return _load_encoder_file(path)


def load_encoder_events(session_path: Path, settings: dict[str, Any] | None = None) -> pd.DataFrame:
    raw_dir = Path(session_path) / 'raw_behavior_data'
    path = next(raw_dir.glob('_iblrig_encoderEvents.raw*.ssv'), None)
    if path is None:
        return pd.DataFrame({'re_ts': np.array([], dtype=float), 'event': np.array([], dtype=int)})
    return _load_encoder_file(path)


def sync_trials_robust(t0: np.ndarray, t1: np.ndarray, max_missing: int = 2) -> tuple[np.ndarray, np.ndarray]:
    a = np.asarray(t0, dtype=float)
    b = np.asarray(t1, dtype=float)
    if a.size < 3 or b.size < 3:
        n = min(a.size, b.size)
        return a[:n], b[:n]
    best: tuple[float, np.ndarray, np.ndarray] | None = None
    for start_a in range(max_missing + 1):
        for start_b in range(max_missing + 1):
            aa = a[start_a:]
            bb = b[start_b:]
            n = min(aa.size, bb.size)
            if n < 3:
                continue
            aa = aa[:n]
            bb = bb[:n]
            fit = np.polyfit(aa, bb - aa, deg=1)
            residual = (np.polyval(fit, aa) + aa) - bb
            score = float(np.median(np.abs(residual)))
            if best is None or score < best[0]:
                best = (score, aa, bb)
    if best is None:
        n = min(a.size, b.size)
        return a[:n], b[:n]
    aa, bb = best[1], best[2]
    if aa.size != bb.size:
        n = min(aa.size, bb.size)
        aa, bb = aa[:n], bb[:n]
    return aa, bb

