from __future__ import annotations

from pathlib import Path
from typing import Any

import numpy as np

from neurorig_extract.extractors.base import BaseExtractor
from neurorig_extract.raw import load_data, load_settings


def _state(trial: dict[str, Any], name: str) -> float:
    try:
        value = trial['behavior_data']['States timestamps'][name][0][0]
    except Exception:
        return np.nan
    return float(value) if value is not None else np.nan


def _event(trial: dict[str, Any], name: str) -> float:
    try:
        value = trial['behavior_data']['Events timestamps'][name][0]
    except Exception:
        return np.nan
    return float(value) if value is not None else np.nan


def _signed_choice(trial: dict[str, Any]) -> int:
    if not np.isnan(_state(trial, 'no_go')):
        return 0
    choice = trial.get('choice')
    if choice in (-1, 0, 1):
        return int(choice)
    if not np.isnan(_state(trial, 'choice_left')):
        return -1
    if not np.isnan(_state(trial, 'choice_right')):
        return 1
    return 0


def _contrast_pair(trial: dict[str, Any]) -> tuple[float, float]:
    left = trial.get('contrastLeft', trial.get('stimulus', {}).get('contrast_left', np.nan))
    right = trial.get('contrastRight', trial.get('stimulus', {}).get('contrast_right', np.nan))
    left = float(left) if left is not None else np.nan
    right = float(right) if right is not None else np.nan
    if np.isfinite(left) and np.isfinite(right):
        if left > 0 and right > 0:
            right = np.nan
    return left, right


class TrialExtractor(BaseExtractor):
    object_name = 'trials'

    def trials(self) -> list[dict[str, Any]]:
        return load_data(self.session_path)

    def settings(self) -> dict[str, Any]:
        return load_settings(self.session_path)


class FeedbackType(TrialExtractor):
    save_names = ('_ibl_trials.feedbackType.npy',)
    var_names = ('feedbackType',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        values = []
        for trial in self.trials():
            if 'feedbackType' in trial:
                ft = int(trial['feedbackType'])
            else:
                rewarded = bool(trial.get('rewarded', False)) or float(trial.get('rewardVolume', 0) or 0) > 0
                ft = 1 if rewarded else -1
            values.append(ft if ft != 0 else -1)
        return (np.asarray(values, dtype=np.int8),)


class ContrastLR(TrialExtractor):
    save_names = ('_ibl_trials.contrastLeft.npy', '_ibl_trials.contrastRight.npy')
    var_names = ('contrastLeft', 'contrastRight')

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray, np.ndarray]:
        pairs = [_contrast_pair(t) for t in self.trials()]
        left, right = zip(*pairs, strict=False) if pairs else ([], [])
        return np.asarray(left, dtype=float), np.asarray(right, dtype=float)


class ProbabilityLeft(TrialExtractor):
    save_names = ('_ibl_trials.probabilityLeft.npy',)
    var_names = ('probabilityLeft',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        settings = kwargs.get('settings') or self.settings()
        default = 0.5
        allowed = settings.get('BLOCK_PROBABILITY_SET', [0.2, 0.5, 0.8])
        out = []
        for trial in self.trials():
            value = float(trial.get('probabilityLeft', default))
            if value not in allowed and value != 0.5:
                value = min(allowed, key=lambda x: abs(float(x) - value))
            out.append(value)
        return (np.asarray(out, dtype=float),)


class Choice(TrialExtractor):
    save_names = ('_ibl_trials.choice.npy',)
    var_names = ('choice',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        return (np.asarray([_signed_choice(t) for t in self.trials()], dtype=np.int8),)


class RepNum(TrialExtractor):
    save_names = ('_ibl_trials.repNum.npy',)
    var_names = ('repNum',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        reps = [int(t.get('repNum', i % 4)) for i, t in enumerate(self.trials())]
        return (np.asarray(reps, dtype=np.int16),)


class RewardVolume(TrialExtractor):
    save_names = ('_ibl_trials.rewardVolume.npy',)
    var_names = ('rewardVolume',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        return (np.asarray([float(t.get('rewardVolume', 0.0) or 0.0) for t in self.trials()]),)


class FeedbackTimes(TrialExtractor):
    save_names = ('_ibl_trials.feedback_times.npy',)
    var_names = ('feedback_times',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        out = [t.get('feedback_time', _state(t, 'reward') if t.get('rewarded') else _state(t, 'error')) for t in self.trials()]
        return (np.asarray(out, dtype=float),)


class StimOnTriggerTimes(TrialExtractor):
    save_names = ('_ibl_trials.stimOnTrigger_times.npy',)
    var_names = ('stimOnTrigger_times',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        return (np.asarray([t.get('stimOnTrigger_time', _event(t, 'stim_on')) for t in self.trials()], dtype=float),)


class GoCueTriggerTimes(TrialExtractor):
    save_names = ('_ibl_trials.goCueTrigger_times.npy',)
    var_names = ('goCueTrigger_times',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        return (np.asarray([t.get('goCueTrigger_time', _state(t, 'closed_loop')) for t in self.trials()], dtype=float),)


class GoCueTimes(TrialExtractor):
    save_names = ('_ibl_trials.goCue_times.npy',)
    var_names = ('goCue_times',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        return (np.asarray([t.get('goCue_time', _event(t, 'goCue')) for t in self.trials()], dtype=float),)


class ResponseTimes(TrialExtractor):
    save_names = ('_ibl_trials.response_times.npy',)
    var_names = ('response_times',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        return (np.asarray([t.get('response_time', _state(t, 'choice')) for t in self.trials()], dtype=float),)


class Intervals(TrialExtractor):
    save_names = ('_ibl_trials.intervals.npy',)
    var_names = ('intervals',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        rows = []
        for trial in self.trials():
            start = trial.get('interval_start', _state(trial, 'trial_start'))
            stop = trial.get('interval_end', _state(trial, 'exit_state'))
            rows.append([start, stop])
        return (np.asarray(rows, dtype=float),)


class IncludedTrials(TrialExtractor):
    save_names = ('_ibl_trials.included.npy',)
    var_names = ('included',)

    def _extract(self, **kwargs: Any) -> tuple[np.ndarray]:
        included = []
        for trial in self.trials():
            bad = bool(trial.get('exclude', False))
            included.append(not bad)
        return (np.asarray(included, dtype=bool),)


TRIAL_EXTRACTORS = [Intervals, FeedbackType, ContrastLR, ProbabilityLeft, Choice, RepNum, RewardVolume, FeedbackTimes, StimOnTriggerTimes, GoCueTriggerTimes, GoCueTimes, ResponseTimes, IncludedTrials]


def extract_all(session_path: str | Path, save: bool = True, settings: dict[str, Any] | None = None, alf_folder: str = 'alf') -> tuple[dict[str, Any], list[Path]]:
    outputs: dict[str, Any] = {}
    files: list[Path] = []
    for cls in TRIAL_EXTRACTORS:
        extractor = cls(session_path, alf_folder=alf_folder)
        values, paths = extractor.extract(save=save, settings=settings)
        files.extend(paths)
        for name, value in zip(cls.var_names, values, strict=True):
            outputs[name] = value
    return outputs, files

# "NeuroRigExtract/src/neurorig_extract/extractors/wheel.py"
from __future__ import annotations

from pathlib import Path

import numpy as np

from neurorig_extract.alf import save_array
from neurorig_extract.raw import load_encoder_positions


def extract_wheel_moves(session_path: str | Path, save: bool = True, threshold: float = 0.02) -> tuple[dict[str, np.ndarray], list[Path]]:
    session = Path(session_path)
    df = load_encoder_positions(session)
    if df.empty or df.shape[0] < 3:
        raise ValueError('_ibl_wheelMoves.intervals.npy appears to be empty')
    pos_col = 'position' if 'position' in df.columns else df.columns[-1]
    ts = df['re_ts'].to_numpy(dtype=float)
    pos = df[pos_col].to_numpy(dtype=float)
    velocity = np.gradient(pos, ts, edge_order=1)
    moving = np.abs(velocity) >= threshold
    starts = np.flatnonzero(np.diff(np.r_[False, moving]) == 1)
    stops = np.flatnonzero(np.diff(np.r_[moving, False]) == -1)
    intervals = np.c_[ts[starts], ts[np.maximum(stops - 1, starts)]] if starts.size else np.empty((0, 2))
    peak_amp = np.array([np.nanmax(np.abs(pos[s:e] - pos[s])) if e > s else 0 for s, e in zip(starts, stops, strict=False)])
    peak_times = np.array([ts[s + int(np.argmax(np.abs(velocity[s:e])))] if e > s else ts[s] for s, e in zip(starts, stops, strict=False)])
    out = {'intervals': intervals, 'peakAmplitude': peak_amp, 'peakVelocity_times': peak_times}
    files: list[Path] = []
    if save:
        alf = session / 'alf'
        files.append(save_array(alf / '_ibl_wheelMoves.intervals.npy', intervals))
        files.append(save_array(alf / '_ibl_wheelMoves.peakAmplitude.npy', peak_amp))
        files.append(save_array(alf / '_ibl_wheelMoves.peakVelocity_times.npy', peak_times))
    return out, files

# "NeuroRigExtract/src/neurorig_extract/extractors/camera.py"
from __future__ import annotations

from typing import Literal

import numpy as np


def attribute_times(tsa: np.ndarray, tsb: np.ndarray, tol: float = 0.1, take: Literal['first', 'nearest', 'after'] = 'first', injective: bool = True) -> np.ndarray:
    if take not in {'first', 'nearest', 'after'}:
        raise ValueError('take must be one of first, nearest, after')
    a = np.asarray(tsa, dtype=float)
    b = np.asarray(tsb, dtype=float)
    matches = np.full(b.shape, -1, dtype=int)
    used: set[int] = set()
    for i, t in enumerate(b):
        if take == 'after':
            candidates = np.where((a >= t) & (a - t <= tol))[0]
        else:
            candidates = np.where(np.abs(a - t) <= tol)[0]
        if candidates.size == 0:
            continue
        if take == 'nearest':
            order = candidates[np.argsort(np.abs(a[candidates] - t))]
        else:
            order = candidates
        for idx in order:
            if not injective or int(idx) not in used:
                matches[i] = int(idx)
                used.add(int(idx))
                break
    return matches


def groom_pin_state(gpio: dict[str, np.ndarray], audio: dict[str, np.ndarray], ts: np.ndarray, tolerance: float = 0.2, min_diff: float = 1e-3) -> tuple[dict[str, np.ndarray], dict[str, np.ndarray], np.ndarray]:
    frame_ts = np.asarray(ts, dtype=float)
    indices = np.asarray(gpio.get('indices', []), dtype=int)
    polarities = np.asarray(gpio.get('polarities', np.ones(indices.size)), dtype=int)
    valid = (indices >= 0) & (indices < frame_ts.size)
    gpio_times = frame_ts[indices[valid]]
    gpio_pol = polarities[valid]
    audio_times = np.asarray(audio.get('times', []), dtype=float)
    audio_pol = np.asarray(audio.get('polarities', np.ones(audio_times.size)), dtype=int)
    keep_audio = np.r_[True, np.diff(audio_times) > min_diff] if audio_times.size else np.array([], dtype=bool)
    audio_times = audio_times[keep_audio]
    audio_pol = audio_pol[keep_audio]
    matches = attribute_times(gpio_times, audio_times, tol=tolerance, take='nearest')
    matched = matches >= 0
    if matched.any():
        gpio_times = gpio_times[matches[matched]]
        gpio_pol = gpio_pol[matches[matched]]
        audio_times = audio_times[matched]
        audio_pol = audio_pol[matched]
        offset = float(np.median(audio_times - gpio_times))
        corrected_ts = frame_ts + offset
    else:
        corrected_ts = frame_ts.copy()
    return {'times': gpio_times, 'polarities': gpio_pol}, {'times': audio_times, 'polarities': audio_pol}, corrected_ts

# "NeuroRigExtract/src/neurorig_extract/pipeline.py"
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

from neurorig_extract.alf import check_dimensions, load_object
from neurorig_extract.config import ExtractionConfig
from neurorig_extract.extractors.trials import extract_all as extract_trials
from neurorig_extract.extractors.wheel import extract_wheel_moves


@dataclass(frozen=True)
class ExtractionResult:
    session_path: Path
    outputs: dict[str, Any]
    files: list[Path]
    dimension_status: int


def run_extraction(config: ExtractionConfig) -> ExtractionResult:
    settings = {'IBLRIG_VERSION_TAG': config.rig_version} if config.rig_version else None
    outputs, files = extract_trials(config.session_path, save=config.save, settings=settings, alf_folder=config.alf_folder)
    if config.include_wheel:
        try:
            wheel, wheel_files = extract_wheel_moves(config.session_path, save=config.save)
            outputs['wheel'] = wheel
            files.extend(wheel_files)
        except ValueError:
            if config.strict:
                raise
    status = 0
    if config.save:
        status = check_dimensions(load_object(config.alf_path, 'trials'))
