    tsa = np.linspace(0, 10, 101)
    tsb = np.array([0.02, 1.01, 5.03, 20.0])
    matches = attribute_times(tsa, tsb, tol=0.05, take='nearest')
    assert matches[-1] == -1
    gpio = {'indices': np.array([10, 20]), 'polarities': np.array([1, -1])}
    audio = {'times': np.array([1.01, 2.01]), 'polarities': np.array([1, -1])}
    gpio_out, audio_out, corrected = groom_pin_state(gpio, audio, tsa, tolerance=0.05)
    assert gpio_out['times'].size == audio_out['times'].size == 2
    assert corrected.size == tsa.size

