    with (raw / 'trials.jsonl').open('w', encoding='utf8') as fp:
        for i in range(n_trials):
            rewarded = i % 3 != 0
            side_left = i % 2 == 0
            trial = {'feedbackType': 1 if rewarded else -1, 'rewarded': rewarded, 'rewardVolume': 1.5 if rewarded else 0, 'contrastLeft': 0.25 if side_left else None, 'contrastRight': None if side_left else 0.25, 'probabilityLeft': 0.2 if i < n_trials / 2 else 0.8, 'choice': -1 if side_left else 1, 'repNum': i % 4, 'interval_start': float(i), 'interval_end': float(i) + 0.8, 'response_time': float(i) + 0.45, 'goCue_time': float(i) + 0.2, 'behavior_data': {'States timestamps': {'trial_start': [[float(i)]], 'closed_loop': [[float(i) + 0.2]], 'choice': [[float(i) + 0.45]], 'reward': [[float(i) + 0.55]], 'error': [[float(i) + 0.55]], 'exit_state': [[float(i) + 0.8]], 'no_go': [[float('nan')]]}, 'Events timestamps': {'goCue': [float(i) + 0.2], 'stim_on': [float(i) + 0.1]}}}
