# "NeuroRigExtract/src/neurorig_extract/config.py"
from __future__ import annotations

from pathlib import Path
from typing import Literal

from pydantic import BaseModel, Field, field_validator

TaskType = Literal['training', 'biased']


class ExtractionConfig(BaseModel):
    session_path: Path
    task: TaskType = 'training'
    save: bool = True
    alf_folder: str = 'alf'
    rig_version: str | None = None
    strict: bool = False
    include_wheel: bool = True

    @field_validator('session_path')
    @classmethod
    def expand_session_path(cls, value: Path) -> Path:
        return value.expanduser().resolve()

    @property
    def alf_path(self) -> Path:
        return self.session_path / self.alf_folder

    def version_tuple(self) -> tuple[int, int, int]:
        tag = self.rig_version or '5.0.0'
        cleaned = tag.strip().lstrip('v').split('+')[0]
        parts = cleaned.split('.')[:3]
        ints = []
        for part in parts:
            try:
                ints.append(int(part))
            except ValueError:
                ints.append(0)
        while len(ints) < 3:
            ints.append(0)
        return tuple(ints)  # type: ignore[return-value]

    @property
    def is_ge5(self) -> bool:
        return self.version_tuple() >= (5, 0, 0)

