from __future__ import annotations

import json
from pathlib import Path

import numpy as np
import pandas as pd


def make_demo_session(path: Path, n_trials: int = 12) -> None:
    raw = path / 'raw_behavior_data'
    raw.mkdir(parents=True, exist_ok=True)
    settings = {'IBLRIG_VERSION_TAG': '5.1.0', 'BLOCK_PROBABILITY_SET': [0.2, 0.8]}
    (raw / 'settings.json').write_text(json.dumps(settings), encoding='utf8')
    with (raw / 'trials.jsonl').open('w', encoding='utf8') as fp:
        for i in range(n_trials):
            rewarded = i % 3 != 0
            side_left = i % 2 == 0
            trial = {'feedbackType': 1 if rewarded else -1, 'rewarded': rewarded, 'rewardVolume': 1.5 if rewarded else 0, 'contrastLeft': 0.25 if side_left else None, 'contrastRight': None if side_left else 0.25, 'probabilityLeft': 0.2 if i < n_trials / 2 else 0.8, 'choice': -1 if side_left else 1, 'repNum': i % 4, 'interval_start': float(i), 'interval_end': float(i) + 0.8, 'response_time': float(i) + 0.45, 'goCue_time': float(i) + 0.2, 'behavior_data': {'States timestamps': {'trial_start': [[float(i)]], 'closed_loop': [[float(i) + 0.2]], 'choice': [[float(i) + 0.45]], 'reward': [[float(i) + 0.55]], 'error': [[float(i) + 0.55]], 'exit_state': [[float(i) + 0.8]], 'no_go': [[float('nan')]]}, 'Events timestamps': {'goCue': [float(i) + 0.2], 'stim_on': [float(i) + 0.1]}}}
            fp.write(json.dumps(trial) + '\n')
    ts = np.linspace(0, n_trials, n_trials * 20)
    pos = np.sin(ts * 3) * 0.05
    pd.DataFrame({'re_ts': ts, 'position': pos}).to_csv(raw / '_iblrig_encoderPositions.raw.ssv', sep=' ', index=False)
    pd.DataFrame({'re_ts': ts[::10], 'event': np.ones(ts[::10].size, dtype=int)}).to_csv(raw / '_iblrig_encoderEvents.raw.ssv', sep=' ', index=False)


if __name__ == '__main__':
    make_demo_session(Path('demo_session'))

