            trial = {'feedbackType': 1 if i % 2 else -1, 'rewardVolume': 1.0 if i % 2 else 0.0, 'contrastLeft': 0.5 if i % 2 else None, 'contrastRight': None if i % 2 else 0.5, 'probabilityLeft': 0.2 if i < 4 else 0.8, 'choice': -1 if i % 2 else 1, 'repNum': i % 4, 'interval_start': i, 'interval_end': i + 1, 'response_time': i + 0.5, 'goCue_time': i + 0.2, 'behavior_data': {'States timestamps': {'trial_start': [[i]], 'closed_loop': [[i + 0.2]], 'choice': [[i + 0.5]], 'reward': [[i + 0.6]], 'error': [[i + 0.6]], 'exit_state': [[i + 1]], 'no_go': [[float('nan')]]}, 'Events timestamps': {'goCue': [i + 0.2], 'stim_on': [i + 0.1]}}}
            fp.write(json.dumps(trial) + '\n')
    ts = np.linspace(0, 8, 200)
    pd.DataFrame({'re_ts': ts, 'position': np.sin(ts)}).to_csv(raw / '_iblrig_encoderPositions.raw.ssv', sep=' ', index=False)
    pd.DataFrame({'re_ts': ts[::20], 'event': 1}).to_csv(raw / '_iblrig_encoderEvents.raw.ssv', sep=' ', index=False)
    return tmp_path

