def configure_logging(level: int = logging.INFO, log_file: Path | None = None) -> logging.Logger:
    logger = logging.getLogger('neurorig_extract')
    logger.setLevel(level)
    logger.handlers.clear()
    fmt = logging.Formatter('%(asctime)s %(levelname)s %(name)s: %(message)s')
    stream = logging.StreamHandler()
    stream.setFormatter(fmt)
    logger.addHandler(stream)
    if log_file is not None:
        log_file.parent.mkdir(parents=True, exist_ok=True)
        file_handler = logging.FileHandler(log_file)
        file_handler.setFormatter(fmt)
        logger.addHandler(file_handler)
    return logger

# "NeuroRigExtract/src/neurorig_extract/alf.py"
from __future__ import annotations

from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd


class AlfError(RuntimeError):
    pass


def save_array(path: Path, value: Any) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    suffix = path.suffix.lower()
    if suffix == '.npy':
        np.save(path, value)
    elif suffix == '.csv':
        _as_frame(value).to_csv(path, index=False)
    elif suffix == '.tsv':
        _as_frame(value).to_csv(path, sep='\t', index=False)
    elif suffix == '.ssv':
        _as_frame(value).to_csv(path, sep=' ', index=False)
    else:
        raise AlfError(f'unsupported ALF extension: {suffix}')
    return path


def load_array(path: Path) -> Any:
    suffix = path.suffix.lower()
    if suffix == '.npy':
        return np.load(path, allow_pickle=True)
    if suffix == '.csv':
        return pd.read_csv(path)
    if suffix == '.tsv':
        return pd.read_csv(path, sep='\t')
    if suffix == '.ssv':
        return pd.read_csv(path, sep=' ')
    raise AlfError(f'unsupported ALF extension: {suffix}')


def load_object(alf_path: Path, object_name: str) -> dict[str, Any]:
    if not alf_path.exists():
        raise AlfError(f'ALF folder does not exist: {alf_path}')
    prefix = f'_ibl_{object_name}.'
    out: dict[str, Any] = {}
    for path in sorted(alf_path.glob(prefix + '*')):
        attribute = path.name[len(prefix):].split('.')[0]
        out[attribute] = load_array(path)
    return out


def check_dimensions(obj: dict[str, Any]) -> int:
    lengths = []
    for value in obj.values():
        if isinstance(value, pd.DataFrame):
            lengths.append(len(value))
        else:
            arr = np.asarray(value)
            if arr.ndim > 0:
                lengths.append(arr.shape[0])
    if not lengths:
        return 0
    return 0 if len(set(lengths)) == 1 else 1


def _as_frame(value: Any) -> pd.DataFrame:
    if isinstance(value, pd.DataFrame):
        return value
    arr = np.asarray(value)
    if arr.ndim == 1:
        return pd.DataFrame({'value': arr})
    return pd.DataFrame(arr)

