from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

from neurorig_extract.alf import check_dimensions, load_object
from neurorig_extract.config import ExtractionConfig
from neurorig_extract.extractors.trials import extract_all as extract_trials
from neurorig_extract.extractors.wheel import extract_wheel_moves


@dataclass(frozen=True)
class ExtractionResult:
    session_path: Path
    outputs: dict[str, Any]
    files: list[Path]
    dimension_status: int


def run_extraction(config: ExtractionConfig) -> ExtractionResult:
    settings = {'IBLRIG_VERSION_TAG': config.rig_version} if config.rig_version else None
    outputs, files = extract_trials(config.session_path, save=config.save, settings=settings, alf_folder=config.alf_folder)
    if config.include_wheel:
        try:
            wheel, wheel_files = extract_wheel_moves(config.session_path, save=config.save)
            outputs['wheel'] = wheel
            files.extend(wheel_files)
        except ValueError:
            if config.strict:
                raise
    status = 0
    if config.save:
        status = check_dimensions(load_object(config.alf_path, 'trials'))
    return ExtractionResult(config.session_path, outputs, files, status)

# "NeuroRigExtract/src/neurorig_extract/qa.py"
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from neurorig_extract.alf import check_dimensions, load_object


@dataclass(frozen=True)
class ValidationReport:
    alf_path: Path
    object_name: str
    n_attributes: int
    dimension_status: int

    @property
    def ok(self) -> bool:
        return self.dimension_status == 0 and self.n_attributes > 0


def validate_alf_object(alf_path: str | Path, object_name: str = 'trials') -> ValidationReport:
    path = Path(alf_path)
    obj = load_object(path, object_name)
    return ValidationReport(path, object_name, len(obj), check_dimensions(obj))

# "NeuroRigExtract/src/neurorig_extract/cli.py"
from __future__ import annotations

from pathlib import Path

import typer
from rich.console import Console

from neurorig_extract.config import ExtractionConfig
from neurorig_extract.pipeline import run_extraction
from neurorig_extract.qa import validate_alf_object

app = typer.Typer(help='Extract raw behavioral rig sessions into ALF-style arrays.')
console = Console()


@app.command()
def extract(session: Path, task: str = 'training', save: bool = True, rig_version: str | None = None, strict: bool = False, include_wheel: bool = True) -> None:
    config = ExtractionConfig(session_path=session, task=task, save=save, rig_version=rig_version, strict=strict, include_wheel=include_wheel)  # type: ignore[arg-type]
    result = run_extraction(config)
    console.print(f'extracted {len(result.outputs)} outputs from {result.session_path}')
    if save:
        console.print(f'wrote {len(result.files)} files; dimension_status={result.dimension_status}')


@app.command()
def validate(alf_path: Path, object_name: str = 'trials') -> None:
    report = validate_alf_object(alf_path, object_name)
    color = 'green' if report.ok else 'red'
    console.print(f'[{color}]object={report.object_name} attributes={report.n_attributes} dimension_status={report.dimension_status}[/{color}]')

# "NeuroRigExtract/src/neurorig_extract/serving.py"
from __future__ import annotations

from pathlib import Path
from typing import Any

from neurorig_extract.config import ExtractionConfig
from neurorig_extract.pipeline import run_extraction


def create_app() -> Any:
    try:
        from fastapi import FastAPI
    except ImportError as exc:
        raise RuntimeError('install neurorig-extract[serve] to use the API server') from exc
    app = FastAPI(title='NeuroRigExtract')

    @app.post('/extract')
    def extract(payload: dict[str, Any]) -> dict[str, Any]:
        config = ExtractionConfig(session_path=Path(payload['session_path']), task=payload.get('task', 'training'), save=payload.get('save', True), rig_version=payload.get('rig_version'), strict=payload.get('strict', False), include_wheel=payload.get('include_wheel', True))
        result = run_extraction(config)
        return {'session_path': str(result.session_path), 'files': [str(p) for p in result.files], 'dimension_status': result.dimension_status, 'outputs': list(result.outputs)}

    return app

