def test_repair_monotonic_clock_handles_reset_and_swaps():
    raw = np.array([10, 11, 12, 2, 3, 20, 19, 21], dtype=float)
    repaired = repair_monotonic_clock(raw)
    assert np.all(np.diff(repaired) > 0)


def test_sync_trials_robust_missing_edges():
    drift = np.array([11e-6, -20.0])
    rng = np.random.default_rng(784)
    t0 = np.cumsum(rng.random(50)) + 0.001
    t1 = np.polyval(drift, t0) + t0
    a, b = sync_trials_robust(t0, t1[:-1])
    assert np.allclose(b, np.polyval(drift, a) + a)


